    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】光聚合固化成型技術 (VPP) 之固化光源與光化學反應波長\n### 【正確答案說明】\n光聚合固化成型技術（Vat Photopolymerization, VPP，如 SLA、DLP、LCD）所使用的光敏樹脂，主要由寡聚物、單體以及光起始劑（Photoinitiator）組成。商用光敏樹脂中的光起始劑對紫外光（UV，波長通常介於 355 nm 至 405 nm 之間）具有極高的光吸收截面與量子產率，能有效引發自由基或陽離子聚合反應，使液態樹脂迅速交聯轉化為固態三維高分子。因此，紫外光是光固化樹脂最佳的反應光源。\n### 【選項辨析】\n- **(A) 紅外光**：波長大於 780 nm，主要產生熱效應，用於加熱或熱熔成型，無法激發光固化起始劑。\n- **(B) 紅光**：屬於可見光長波段（約 620-750 nm），光子能量較低，常態下不具備引發樹脂光聚合所需之激發能。\n- **(C) 綠光**：屬於可見光中波段（約 495-570 nm），光子能量不足以有效誘發一般光敏樹脂之快速硬化反應。\n- **(D) 紫外光**：正確。光子能量高且精確匹配光起始劑吸收光譜，固化交聯速率與深度最為理想。",
