    "stem": "材料噴印成型技術(MJT)中，相對於熱泡式(Thermal)噴頭而言，關於壓電式 (Piezoelectric)噴頭的特性，下列敘述何者有誤？",
    "question": "材料噴印成型技術(MJT)中，相對於熱泡式(Thermal)噴頭而言，關於壓電式 (Piezoelectric)噴頭的特性，下列敘述何者有誤？",
