    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】材料噴印成型技術 (MJT) 噴頭機制：壓電式 (Piezoelectric) vs 熱泡式 (Thermal)\n### 【正確答案說明】\n在材料噴印成型技術（Material Jetting, MJT，如 PolyJet / Projet）中，主要採用熱泡式或壓電式微滴噴射噴頭。壓電式噴頭是利用壓電陶瓷晶體在外加電場作用下的機械微變形來擠出液滴，過程中不產生高溫，因此不會造成高分子材料熱裂解，耐用度極高且使用壽命顯著長於熱泡式噴頭；熱泡式噴頭則因反覆瞬時加熱至 300°C 以上產生氣泡，容易受到熱應力疲勞與墨水沉積結垢影響而壽命較短。故 (A) 選項「壽命較短」敘述有誤，為本題正解。\n### 【選項辨析】\n- **(A) 壽命較短**：有誤。壓電式無熱應力衰減，工作壽命顯著優於熱泡式。\n- **(B) 成本較高**：正確。壓電陶瓷元件加工與多通道微致動器驅動電路造價昂貴。\n- **(C) 反應速度較快**：正確。壓電振盪頻率可達數十 kHz，脈衝響應精確迅速。\n- **(D) 可用於非水性材料**：正確。無高溫加熱蒸發限制，可相容多種有機溶劑、紫外線光敏樹脂與高黏度材料。",
