    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】熔融擠製成型技術 (FFF) 遠端進料 (Bowden) 與近端進料 (Direct Drive) 比較\n### 【正確答案說明】\n在 FFF（或 FDM）設備中，進料機構分為兩大架構：\n1. **近端進料（Direct Drive）**：擠出馬達直接安裝在加熱噴頭上方，進料路徑極短，對線材推拉控制精準，非常適合列印熱塑性聚氨酯（TPU）等低蕭氏硬度的軟性彈性體線材。\n2. **遠端進料（Bowden）**：進料馬達固定於機架上，透過長距離鐵氟龍導管將線材推向噴頭。由於軟性線材受壓易在導管內發生彈性彎曲、扭曲與摩擦卡死，因此遠端進料「極不適合」列印軟性線材。故 (C) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 近端進料可以精確控制回抽量**：正確。進料齒輪至熔池距離短，回抽遲滯效應極小。\n- **(B) 近端進料可以減少線材推送的阻力**：正確。路徑短且無長鐵氟龍管摩擦阻力。\n- **(C) 遠端進料適合列印軟性線材**：有誤。軟料在遠端導管內易彈性變形導致出料不順或塞料。\n- **(D) 遠端進料可以降低噴頭模組的運動慣性**：正確。重型馬達移至機身，工具頭極輕，可提高列印加速度與速度。",
