    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】高能束金屬積層製造：電子束熔融成型技術 (EBM) 之高真空工作環境\n### 【正確答案說明】\n電子束熔融成型技術（Electron Beam Melting, EBM，歸類於 PBF）是利用高能聚焦電子束掃描並熔化金屬粉末。電子在常壓空氣或氣體中移動時會與氣體分子發生劇烈碰撞產生散射，導致束流發散且能量急劇衰減；此外，高溫金屬熔池極易與氧氣、氮氣劇烈氧化。因此，EBM 設備必須在 $10^{-4}$ 至 $10^{-5}$ mbar 的高真空（High Vacuum）環境下作業，才能維持電子束高能量聚焦並防止活性金屬（如鈦合金、鎳基超合金）氧化污染。\n### 【選項辨析】\n- **(A) 疊層實體成型技術 (LOM)**：以紙張或薄片材料加壓雷射切割堆疊，在大氣環境下進行。\n- **(B) 電子束熔融成型技術 (EBM)**：正確。電子傳導必須依賴高真空環境防止電子散射與材料氧化。\n- **(C) 連續液體介面成型技術 (CLIP)**：以液態樹脂在常壓氧阻聚透氣窗環境下連續列印。\n- **(D) 選擇性雷射熔融成型技術 (SLM)**：利用雷射光束照射，通常在常壓充氬氣或氮氣的惰性氣氛保護艙內進行，非高真空。",
