    "explanation": "### 【核心考點】航太工業導入積層製造技術 (AM) 之核心效益分析\n### 【正確答案說明】\n航太領域導入積層製造技術（如金屬 PBF、DED），核心優勢在於：\n1. **結構最佳化與輕量化**：藉由拓撲最佳化（Topology Optimization）與點陣晶格結構（Lattice Structure），大幅減輕飛行器結構重量，達成顯著的「買飛比（Buy-to-Fly Ratio）」改善。\n2. **組件整合化**：將原本由數十至數百個零件焊接鉚接的複雜總成整合為單一列印零件，提升可靠度並減少組裝工時。\n3. **少量多樣與按需製造**：航太零件需求批量小但構型複雜多變。\n相對而言，「產品量產化」是傳統模具與高效率 CNC 切削大量生產的優勢，並非積層製造的核心優勢。因此 (C) 並非主要優勢。\n### 【選項辨析】\n- **(A) 少量多樣化**：正確。航太機隊零件數量少且具客製化需求，AM 免開模效益高。\n- **(B) 結構最佳化**：正確。能自由成型內部流道與拓撲輕量化曲面。\n- **(C) 產品量產化**：非 AM 優勢。積層製造生產節拍相對較慢，單件製造時間長，不適合大規模高產量生產。\n- **(D) 材料輕量化**：正確。降低機體重量可直接降低發動機油耗與碳排放。",
