    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】光聚合固化成型技術 (VPP) 之工業安全與危害防護規範\n### 【正確答案說明】\n光敏樹脂含有丙烯酸酯單體與光起始劑，對皮膚、呼吸道與眼部黏膜具有接觸刺激性、過敏性及潛在毒性。若操作中樹脂不慎噴濺至眼睛，應「立即使用大量潔淨清水或專用洗眼液持續沖洗至少 15 分鐘」，並儘速就醫評估；「絕對嚴禁使用丙酮、酒精等有機溶劑清洗眼部」，因為有機溶劑會直接破壞眼角膜上皮組織造成永久性化學灼傷與失明危險。因此若題述提及使用溶劑清洗眼部即屬嚴重違規操作。\n### 【選項辨析】\n- **(A) 需配戴耐化學品手套（如丁腈橡膠手套）**：正確。防止未固化樹脂滲透接觸皮膚導致接觸性皮炎。\n- **(B) 需配戴活性碳防護口罩**：正確。有效吸附光敏樹脂揮發之有機揮發物（VOCs）。\n- **(C) 需配戴防護眼罩**：正確。阻絕液滴飛濺並防護部分 UV 雜散光。\n- **(D) 不慎噴濺眼睛時應以有機溶劑沖洗**：有誤。有機溶劑具強烈腐蝕與滲透性，嚴禁用於眼部沖洗，應以大量清水沖洗後就醫。",
