    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】連續液體介面成型技術 (CLIP) 之氧阻聚死區 (Dead Zone) 原理\n### 【正確答案說明】\nCLIP（Continuous Liquid Interface Production）由 Carbon3D 提出，能在光固化成型過程中實現無需停頓的超高速連續列印。其技術核心是在樹脂槽底部採用透氧特氟龍薄膜（Amorphous fluoropolymer membrane），氧氣透過薄膜進入樹脂底層形成一層約數十微米厚的「死區（Dead Zone）」。由於自由基光聚合反應對氧氣極為敏感，氧氣會優先與光起始劑生成的自由基反應而終止聚合（即「氧阻聚/厭氧性」，Oxygen Inhibition），使得死區內的樹脂維持液態不與窗底固化黏結，從而讓成型平台能以均勻速率連續往上拉伸。\n### 【選項辨析】\n- **(A) 高流動性**：樹脂雖需流動填補，但連續列印機制本質是由於氧阻聚死區的存在。\n- **(B) 低揮發性**：此為樹脂環保與配方品質要求，非連續列印之關鍵光化學機轉。\n- **(C) 厭氧性（氧阻聚反應）**：正確。利用氧氣抑制光聚合使界面維持液態死區，達成無離型力連續抽拉。\n- **(D) 熱塑性**：光敏樹脂為熱固性高分子（Thermoset），非熱塑性材料。",
    "id": 7,
    "display_num": 7,
    "source_id": "3d-5aea795c88f46166",
