    "assessmentContent": "歷屆",
    "num": 8,
    "stem": "下列哪種 3D 列印技術的成型方法是以粉末為主要列印材料？",
    "question": "下列哪種 3D 列印技術的成型方法是以粉末為主要列印材料？",
    "options": [
      "薄片疊層成型技術(SHL)",
      "黏著劑噴印成型技術(BJT)",
      "材料擠製成型技術(MEX)",
      "材料噴印成型技術(MJT)"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】ASTM F42 七大積層製造技術分類與粉末原料製程判讀\n### 【正確答案說明】\nASTM / ISO 52900 定義了積層製造七大製程類別：\n1. **Binder Jetting（BJT，黏著劑噴印成型技術）**：將液態黏合劑選擇性噴塗於粉末床（金屬、陶瓷、砂模、石膏粉末）上黏結成型，原料型態為「粉末」。\n2. **Sheet Lamination（SHL，薄片疊層成型技術）**：原料為「片狀/薄板材」（紙張、金屬箔、塑膠膜）。\n3. **Material Extrusion（MEX，材料擠製成型技術）**：原料為「線材或顆粒狀熱塑性塑料」。\n4. **Material Jetting（MJT，材料噴印成型技術）**：原料為「液態光敏樹脂或熱熔液滴」。\n### 【選項辨析】\n- **(A) 薄片疊層成型技術 (SHL)**：原料為固態薄片材料。\n- **(B) 黏著劑噴印成型技術 (BJT)**：正確。以粉末為主要基底，透過噴頭沉積黏結劑。\n- **(C) 材料擠製成型技術 (MEX)**：原料為熱塑性線材（Filament）或塑料顆粒。\n- **(D) 材料噴印成型技術 (MJT)**：原料為微滴液態樹脂或液態蠟。",
    "id": 8,
    "display_num": 8,
