    "assessmentContent": "歷屆",
    "num": 10,
    "stem": "關於指向性能量沉積技術(DED)，下列敘述何者正確？",
    "question": "關於指向性能量沉積技術(DED)，下列敘述何者正確？",
    "options": [
      "可噴印光固化樹脂並透過能量沉積成型",
      "使用 UV-LED 光源照射熔融金屬粉體",
      "製作模型的尺寸受粉床大小限制",
      "可以在曲面上進行堆疊加工"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】指向性能量沉積技術 (DED) 製程特性與自由曲面沉積應用\n### 【正確答案說明】\n指向性能量沉積技術（Directed Energy Deposition, DED，常見如 LENS、WAAM、雷射熔覆 Cladding）是利用高能雷射、電子束或電弧聚焦於基板表面形成熔池，同時透過同軸或旁軸送粉/送絲噴嘴將金屬材料直接送入熔池中熔化堆疊。DED 不受粉末床封閉空間限制，通常配備多軸（如 5 軸聯動 CNC 或多軸工業機器手臂），能夠在既有的三維非平面或磨損曲面零件上直接進行局部堆疊、表面強化與破損修復。\n### 【選項辨析】\n- **(A) 可噴印光固化樹脂並透過能量沉積成型**：錯誤。DED 專用於金屬、合金與金屬基複合材料，不用於光固化樹脂。\n- **(B) 使用 UV-LED 光源照射熔融金屬粉體**：錯誤。UV-LED 能量極低，金屬熔融必須使用千瓦級高功率光纖雷射、電子束或電弧。\n- **(C) 製作模型的尺寸受粉床大小限制**：錯誤。DED 無粉末床，工件尺寸僅受機器人或龍門運動範圍限制，可製造數米級大型工件。\n- **(D) 可以在曲面上進行堆疊加工**：正確。多軸靈活姿態控制使其極適合在既有零件或曲面基材上增材修復。",
