    "subject": "s1",
    "subject_name": "第一科：3D列印概論",
    "chapter": "115年第一次歷屆試題",
    "assessmentTopic": "歷屆",
    "assessmentContent": "歷屆",
    "num": 11,
    "stem": "關於目前熔融擠製成型技術(FFF)的 3D 列印設備，下列何者為其主要使用材料？",
    "question": "關於目前熔融擠製成型技術(FFF)的 3D 列印設備，下列何者為其主要使用材料？",
    "options": [
      "光聚合固化樹脂",
      "金屬粉末",
      "熱塑線材",
      "陶瓷粉末"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】熔融擠製成型技術 (FFF) 之主流耗材類型\n### 【正確答案說明】\n熔融擠製成型技術（Fused Filament Fabrication, FFF，又稱 FDM）利用加熱套筒將連續供應的熱塑性塑料線材（Thermoplastic Filament，標準直徑通常為 1.75 mm 或 2.85 mm）加熱軟化至黏流態，並透過細噴嘴擠出於成型平台上，冷卻固化成型。常用熱塑性線材包括 PLA、ABS、PETG、PA（尼龍）、PC、TPU 等。\n### 【選項辨析】\n- **(A) 光聚合固化樹脂**：為光聚合固化技術（VPP / MJT）使用之液態感光原料。\n- **(B) 金屬粉末**：為粉末床熔融（PBF）或指向性能量沉積（DED）之原料。\n- **(C) 熱塑線材**：正確。FFF 最主要的材料形式為直徑均勻之熱塑性高分子卷裝線材。\n- **(D) 陶瓷粉末**：主要用於黏著劑噴印（BJT）或光固化陶瓷漿料成型。",
    "id": 11,
