    "num": 13,
    "stem": "以粉末材料為原料，平鋪於成型表面，利用雷射等能量源選擇性熔化或燒結，透 過每層重複堆疊，以建構成 3D 模型，請問以上敘述為何種技術？",
    "question": "以粉末材料為原料，平鋪於成型表面，利用雷射等能量源選擇性熔化或燒結，透 過每層重複堆疊，以建構成 3D 模型，請問以上敘述為何種技術？",
