    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】粉末床熔融成型技術 (PBF) 之製程定義與原理\n### 【正確答案說明】\nASTM F42 將「以熱能選擇性熔化或燒結粉末床中特定區域之積層製造製程」統稱為粉末床熔融成型技術（Powder Bed Fusion, PBF）。其加工流程為：供粉缸上升、鋪粉滾筒或刮刀將金屬或高分子粉末平鋪於成型表面成一層均勻薄層、雷射或電子束依照 CAD 截面選擇性照射熔化/燒結粉末、成型缸下降一個層厚，反覆循環堆疊為三維實體。\n### 【選項辨析】\n- **(A) 粉末床熔融成型技術 (PBF)**：正確。包含 SLS、SLM、DMLS、EBM 等典型粉末床熱熔製程。\n- **(B) 黏著劑噴印成型技術 (BJT)**：使用液體黏合劑黏結粉末，不使用雷射等高能熱源燒結。\n- **(C) 指向性能量沉積成型技術 (DED)**：同軸同步噴送粉末至熔池，非預先平鋪粉末床。\n- **(D) 材料擠製成型技術 (MEX)**：以固態線材或顆粒擠出，非粉末原料。",
