    "assessmentContent": "歷屆",
    "num": 20,
    "stem": "以金屬粉末為材料的指向性能量沉積技術(DED)，會以何種流體帶動金屬粉末噴 出？",
    "question": "以金屬粉末為材料的指向性能量沉積技術(DED)，會以何種流體帶動金屬粉末噴 出？",
    "options": [
      "乾燥空氣",
      "惰性氣體",
      "高壓氧氣",
      "去離子水"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】指向性能量沉積技術 (DED) 粉末輸送載氣 (Carrier Gas) 選擇\n### 【正確答案說明】\n在粉末饋送型 DED（如 LENS、粉末等離子堆焊）設備中，金屬粉末存放在送粉器（Powder feeder）中，必須藉由氣流懸浮並透過同軸噴嘴高速噴入熔池。由於金屬粉末（尤其是鈦合金、鋁合金、高溫合金）在高溫下極易氧化、燃燒甚至發生粉塵爆炸，因此輸送粉末的載氣必須使用「高純度惰性保護氣體」，工業上最標準且廣泛採用的載氣為「氬氣（Argon, Ar）」或高純氮氣。\n### 【選項辨析】\n- **(A) 壓縮空氣**：含有約 21% 氧氣與水氣，會導致高溫金屬劇烈氧化、脆化及噴粉引燃危險。\n- **(B) 氬氣等惰性氣體**：正確。化學性質極其穩定，能順暢攜帶粉末並同時為熔池提供局部隔氧保護罩。\n- **(C) 二氧化碳**：高溫下金屬可能與 CO2 發生還原反應引起增碳或氧化。\n- **(D) 氧氣**：劇烈助燃氣體，高溫金屬接觸會發生嚴重燃燒與飛濺，絕不可使用。",
    "id": 20,
    "display_num": 20,
    "source_id": "3d-5aea795c88f46166",
