    "assessmentContent": "歷屆",
    "num": 21,
    "stem": "黏著劑噴印成型技術(BJT)的製程，關於其原理的敘述，下列何者有誤？",
    "question": "黏著劑噴印成型技術(BJT)的製程，關於其原理的敘述，下列何者有誤？",
    "options": [
      "粉末可為高分子、金屬或陶瓷",
      "需透過噴嘴將黏著劑噴印於粉末材料表面",
      "黏著劑可為熱塑性材料，如：ABS、PLA",
      "需配合鋪粉機構逐層建構成型"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】黏著劑噴印成型技術 (BJT) 之常溫沉積與低能耗特性\n### 【正確答案說明】\n黏著劑噴印成型技術（Binder Jetting, BJT）在粉末床室溫環境下作業，其成型機制是透過壓電式噴頭將液態有機/無機黏合劑（Binder）選擇性噴灑滲入粉末顆粒孔隙中，利用毛細作用與黏劑交聯硬化將粉末顆粒黏結成型。整個成型打印過程完全「無需高能量熱源（如雷射或電子束）進行局部熔融」，亦無需消耗巨額加熱電能，屬於低能耗冷態製程。完成列印後獲得之生胚，才在後續工序送入高溫燒結爐中進行脫脂與固相燒結。故 (C) 選項「需要以高能量雷射將粉末熔融結合」敘述嚴重違背 BJT 原理。\n### 【選項辨析】\n- **(A) 列印過程可在常溫環境下進行**：正確。黏合劑噴射無需粉床整體維持高溫。\n- **(B) 未受黏著劑噴印之散粉可作為模型支撐**：正確。四周粉末自然托附懸臂結構。\n- **(C) 依靠高功率雷射束直接熔融金屬粉末成型**：錯誤。此為 PBF（SLM/DMLS）原理，BJT 絕不使用雷射熔化粉末。\n- **(D) 列印完成後的生胚（Green part）強度較低需後處理**：正確。需後續固化、脫脂、燒結或滲透浸漬提升強度。",
