    "num": 23,
    "stem": "下列何種 3D 列印成型技術可使用蠟為支撐材料，並透過加熱來移除？",
    "question": "下列何種 3D 列印成型技術可使用蠟為支撐材料，並透過加熱來移除？",
    "options": [
      "材料噴印成型技術(MJT)",
      "光聚合固化成型技術(VPP)",
      "薄片疊層成型技術(SHL)",
      "粉末床熔融成型技術(PBF)"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】材料噴印成型技術 (MJT) 相變材料蠟支撐與熱熔移除法\n### 【正確答案說明】\n材料噴印成型技術（Material Jetting, MJT，如 Solidscape 珠寶蠟模機或 3D Systems MultiJet Printing）具備多噴嘴噴射系統，模型本體通常使用可鑄造蠟（Castable wax）或光敏聚合物，而對於懸臂與內部複雜空腔的支撐結構，則特意噴印「低熔點固體蠟（Support wax）」。列印完成後，將整件模型置入溫控烤箱、熱水浴或專用油浴中加溫至約 55°C~65°C，低熔點支撐蠟即會完全熔化為液態自然流出，而高熔點的模型本體毫髮無傷，完全避免機械剝除工具刮傷精細花紋表面。\n### 【選項辨析】\n- **(A) 材料噴印成型技術 (MJT)**：正確。採用低熔點相變蠟作為支撐，加熱融化即可徹底無損去除。\n- **(B) 粉末床熔融成型技術 (PBF)**：靠周圍鬆散未熔粉末支撐，以吹氣或噴砂去除，不使用蠟支撐。\n- **(C) 疊層實體製造技術 (LOM)**：以薄板雷射網格切割廢料分離，不使用蠟支撐。\n- **(D) 立體光固化成型技術 (SLA)**：支撐與本體皆為同種光敏樹脂，需以斜口鉗機械剪除打磨。",
