    "num": 24,
    "stem": "關於產品採用積層製造(AM)技術進行設計與製造的優勢，下列敘述何者不正確？",
    "question": "關於產品採用積層製造(AM)技術進行設計與製造的優勢，下列敘述何者不正確？",
    "options": [
      "可透過拓樸優化設計實現產品輕量化",
      "不受傳統減法加工路徑干涉的限制",
      "可獲得比傳統加工更高的尺寸精度",
      "容易製造幾何形狀較複雜的零件"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】積層製造 (AM) 之工業價值、設計自由度與批量經濟性邊界\n### 【正確答案說明】\n積層製造（3D 列印）被譽為第三次工業革命的關鍵驅動力，其革命性優勢在於「設計複雜度免費（Complexity is free）」——製造幾何極度複雜的仿生結構、點陣減重結構或內部隨形水冷流道，其製造成本與製造簡單立方體無異；此外，無需開發耗資昂貴且耗時數月的金屬模具，能以數位圖檔實現極致的少量客製化與快速反覆運算。\n然而，積層製造的單件生產時間長、能耗大且專用耗材價格昂貴；在面對「數十萬至數百萬件的單一規格標準化產品」時，傳統模具射出成型或衝壓鑄造在開模完成後，單件生產週期僅需數秒至數十秒，單件分攤成本極低，展現出壓倒性的規模經濟優勢。因此，「大批量標準件之大規模量產」絕非目前積層製造的優勢所在。故 (C) 選項敘述不正確。\n### 【選項辨析】\n- **(A) 具備極高的設計自由度，可製作傳統加工難以成型的複雜內部流道**：正確。擺脫傳統切削刀具干涉限制。\n- **(B) 免除模具開發成本，縮短新產品研發迭代週期**：正確。由 CAD 圖檔直接列印出原型樣件。\n- **(C) 適合單一產品大規模量產以顯著降低單件生產成本**：不正確。量產規模經濟效益遠遜於射出成型與沖壓。\n- **(D) 可整合多零件為一體化結構，減少裝配工序與接合失效點**：正確。減少零件料號與裝配誤差。",
