    "num": 25,
    "stem": "下列何者為熔融擠製成型技術(FFF)最常見的噴頭加熱方式？",
    "question": "下列何者為熔融擠製成型技術(FFF)最常見的噴頭加熱方式？",
    "options": [
      "電阻式(Electric resistance)",
      "微波式(Micro-wave)",
      "超音波(Ultra-sonic)",
      "雷射(Laser)"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】熔融擠製成型技術 (FFF) 噴頭熱端加熱模組元件\n### 【正確答案說明】\n在 FFF / FDM 設備的熱端（Hot End）總成中，最通用且標準的電熱轉換加熱組件為「金屬筒式電阻加熱棒（Cartridge Heater）」。加熱棒內部為鎳鉻合金電阻絲，封裝於不銹鋼金屬圓柱套筒內，插入純銅或鋁合金加熱塊（Heater Block）的安裝孔中，配合 NTC 熱敏電阻或熱電偶，由主板 PID 演算法控制通電工作週期，提供穩定精準的 180°C~300°C 熔融高溫。\n### 【選項辨析】\n- **(A) 電阻式加熱棒**：正確。為 FFF 設備最標準、成熟且響應快速的加熱元件。\n- **(B) 高頻感應線圈**：主要用於金屬冶煉或特定超高溫特種實驗設備，非一般 FFF 噴頭加熱主流。\n- **(C) 聚焦雷射束**：為 SLA、SLM 等高階光學設備之能量源，非 FFF 加熱方式。\n- **(D) 微波加熱器**：微波對熱塑性非極性高分子加熱效率低且腔體體積龐大，不用於 3D 列印噴頭。",
    "id": 25,
