    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】FFF 列印設備熱失控與塑料高溫焦化之緊急應變措施\n### 【正確答案說明】\nFFF 列印機在正常運作下不應產生肉眼可見之煙霧。若列印中突然發現噴頭部位有煙霧冒出或聞到強烈刺鼻焦味，通常代表發生了極度危險的「加熱熱失控（Thermal Runaway）」——即熱敏電阻鬆脫、短路或主板驅動 MOS 管擊穿導通，導致加熱管持續以全功率無限加熱超過 300°C~400°C，使噴頭內部的聚四氟乙烯（PTFE）導管與塑料嚴重熱分解焦化，隨時有引發火災之虞。此時唯一且最優先的標準應變處置是「立即關閉主電源或拔除電源插頭（緊急斷電），中止加熱」，待冷卻後進行安全排查。\n### 【選項辨析】\n- **(A) 加快列印速度以迅速排出高溫材料**：極度危險。馬達運動可能拉扯電線加劇短路或引燃火苗。\n- **(B) 關閉模型風扇以避免煙霧擴散**：錯誤。未解決熱失控根源，反而使熱端散熱惡化。\n- **(C) 用手拔出線材並繼續觀察**：危險且錯誤。極易造成高溫燙傷且徒手無法撲滅電氣失火。\n- **(D) 立即按下緊急停止開關或拔除電源斷電停機**：正確。切斷電能供應是消除熱失控火災風險的最高原則。",
    "id": 28,
    "display_num": 28,
    "source_id": "3d-5aea795c88f46166",
