    "stem": "光聚合固化成型技術(VPP)中，下列製程的曝光方式何者不是屬於面曝光？",
    "question": "光聚合固化成型技術(VPP)中，下列製程的曝光方式何者不是屬於面曝光？",
    "options": [
      "Nanoscribe 的雙光子列印(Two-Photon)",
      "Phrozen 的液晶直曝(LCD)",
      "Carbon3D 的連續液體介面列印(CLIP)",
      "MiiCraft 的數位光投影列印(DLP)"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】VPP 點曝光 (Point-by-point) vs 面曝光 (Area exposure) 機制辨析\n### 【正確答案說明】\n在光聚合固化（VPP）中，依光源照射截面的幾何形式分為兩大流派：\n1. **點掃描曝光（Point-by-point scanning）**：典型代表為 **SLA（立體光固化）**。利用單一細微雷射光束，經由高速雙軸振鏡（Galvo mirrors）的反射角度偏轉，在液面上以「向量點-線」移動的方式高速掃描勾勒出截面輪廓與填充，屬於點曝光。\n2. **面曝光（Area-wide / Mask projection exposure）**：包含 **DLP**（數位微鏡投影）、**LCD**（液晶光罩遮蔽）與 **CLIP**（連續液面投影），整層圖像的所有像素點同步一次性照射固化。\n故 SLA 不屬於面曝光。\n### 【選項辨析】\n- **(A) 雷射立體光固化技術 (SLA)**：正確（非面曝光）。SLA 是利用雷射單點經振鏡連續掃描之點曝光技術。\n- **(B) 數位光處理技術 (DLP)**：屬於面曝光。以微鏡陣列將整層圖形一次性投影。\n- **(C) 液晶面板光罩技術 (LCD/mSLA)**：屬於面曝光。整面陣列背光透過 LCD 遮罩一次成像。\n- **(D) 連續液體介面成型技術 (CLIP)**：屬於面曝光。連續進行面投影無停頓曝光。",
