    "subject": "s1",
    "subject_name": "第一科：3D列印概論",
    "chapter": "115年第一次歷屆試題",
    "assessmentTopic": "歷屆",
    "assessmentContent": "歷屆",
    "num": 30,
    "stem": "光聚合固化成型技術(VPP)當中，何種製程的成型平台不需上下往復運動，且層紋 對外觀造成的影響最小？",
    "question": "光聚合固化成型技術(VPP)當中，何種製程的成型平台不需上下往復運動，且層紋 對外觀造成的影響最小？",
    "options": [
      "數位光投影技術(DLP)",
      "立體光固化成型技術(SLA)",
      "液晶顯示遮光式曝光技術(LCD)",
      "連續液體介面成型技術(CLIP)"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】CLIP 技術之垂直無層紋連續抽拉特性\n### 【正確答案說明】\n傳統下照式光固化（DLP/LCD）為「步進式曝光」：上升一層脫模拉拔 $\\rightarrow$ 下降復位填補樹脂 $\\rightarrow$ 曝光硬化 $\\rightarrow$ 再上升，反覆往復運動不僅速度緩慢，且停頓間隙在 Z 軸表面必然留下微小的層次銜接線（階梯層紋，Layer lines）。\n**CLIP（連續液體介面成型）** 利用底部透氧窗建立不固化的「液態死區（Dead Zone）」，完全消除了樹脂槽底部的剝離拉拔力，使得成型平台能夠以每小時數十公分的恆定速率「持續不中斷地向上平滑抽拉」，紫外線影像像電影般連續變換投射，從根本上消除了層與層之間的物理停頓介面，列印出的零件表面平滑光潔，層紋對外觀影響極小，具有接近射出成型件的等方性力學品質。\n### 【選項辨析】\n- **(A) 傳統雷射立體光固化 (SLA)**：平台每層需上下往復浸入樹脂刮平，具明顯層次結構。\n- **(B) 傳統數位光處理 (DLP)**：平台每層必須往復升降脫模，具階梯紋路。\n- **(C) 液晶面板光罩成型 (LCD)**：每層需上下升降離型脫模，層紋依然存在。\n- **(D) 連續液體介面成型 (CLIP)**：正確。平台連續無往復抬升，層紋影響最小且表面品質最優。",
