    "assessmentContent": "歷屆",
    "num": 31,
    "stem": "在熔融擠製成型技術(FFF)的參數設定當中，關於內部填充(Infill)的敘述，下列 何者有誤？",
    "question": "在熔融擠製成型技術(FFF)的參數設定當中，關於內部填充(Infill)的敘述，下列 何者有誤？",
    "options": [
      "填充型式(Infill Pattern)不同，會影響模型強度",
      "填充密度(Infill Density)越高，使用材料越多",
      "填充密度(Infill Density)越高，列印時間越長",
      "填充密度(Infill Density)越高，列印品質越精細"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】FFF 內部填充率 (Infill Density) 與力學性能、耗時之關聯\n### 【正確答案說明】\n在 FFF 切層設定中，內部填充（Infill）用以支撐頂層封頂壁面並提供零件結構剛性：\n- 填充率通常在 10% 到 100% 之間可調。\n- 填充率設定愈高，模型內部的實體塑料密度愈大，零件抗壓、抗折與剛性愈高，總體消耗線材量與重量也隨之增加。\n- 由於噴頭需要在每層內部走訪繪製更多的填充路徑線段，因此提高填充率必然會「大幅增加總列印時間」。若敘述稱「提高填充率可減少列印時間」，顯屬與物理事實相反的錯誤論述。故 (D) 選項有誤。\n### 【選項辨析】\n- **(A) 填充率愈高，模型重量愈重**：正確。消耗更多克數的塑料耗材。\n- **(B) 填充率愈高，工件的機械結構剛性通常愈強**：正確。內部實心支撐抗變形能力好。\n- **(C) 不同的填充樣式（如網格、蜂巢、陀螺儀 Gyroid）會呈現各向異性強度差異**：正確。陀螺儀具全向等方均勻強度。\n- **(D) 提高填充密度可有效縮短整體列印時間**：錯誤。填充線段大幅增加，列印總時間必然顯著延長。",
