    "num": 32,
    "stem": "熔融擠製成型技術(FFF)在列印過程中，無法再調整下列何種列印參數？",
    "question": "熔融擠製成型技術(FFF)在列印過程中，無法再調整下列何種列印參數？",
    "options": [
      "噴嘴溫度",
      "熱床溫度",
      "移動速度",
      "填充密度"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】切層後 G-code 預處理靜態參數 vs 機台即時動態調整參數\n### 【正確答案說明】\n當 3D CAD 模型完成切層（Slicing）運算並輸出為 G-code 加工程式後：\n- G-code 內部每一層的 Z 軸絕對高度座標（例如 Z=0.20, Z=0.40, Z=0.60...）以及對應的幾何輪廓軌跡、每段擠出量（E值）已經預先固定運算完畢。因此，「切層厚度（Layer Thickness）」屬於離線幾何幾構參數，在列印進行中「完全無法動態調整」。\n- 相對地，主機板韌體支援在列印中即時調節硬體動態運轉參數，如：噴頭加熱目標溫度（Hotend Temp）、熱床溫度（Bed Temp）、進給速度百分比（Feedrate / Speed Multiplier）、擠出出料乘數（Flow / Extrusion Multiplier）與風扇轉速（Fan Speed）。\n### 【選項辨析】\n- **(A) 噴頭加熱溫度**：可即時調整。韌體可即時設定 PID 控溫目標。\n- **(B) 列印移動速度百分比 (Feedrate)**：可即時調整。操作面板可即時加減速（50%~150%）。\n- **(C) 擠出機出料流量比例 (Flow Rate)**：可即時調整。可針對出料不足或過擠進行微調。\n- **(D) 切層厚度 (Layer Thickness)**：無法調整。Z軸分層高度已於切層軟體中固化於 G-code 座標中。",
    "id": 32,
