    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】選擇性雷射燒結 (SLS / PBF) 高分子粉末床自我支撐特點\n### 【正確答案說明】\n在粉末床熔融技術（PBF）處理高分子塑膠粉末（如 PA12 尼龍）的**選擇性雷射燒結（SLS）**製程中：\n- 整個成型艙粉末床會預熱至接近材料熔點（如 170°C）。\n- 雷射僅選擇性掃描熔融燒結實體部位，而周圍所有未被雷射照射到的鬆散散粉，依然緊密填充於整個粉床空間中。\n- 這些未燒結的乾燥粉末本身就具備足夠的機械支撐力，能全方位 360 度托附上層所有懸臂、空腔、倒勾與孤島特徵。\n因此，高分子 SLS 製程「完全不需要在 CAD 中設計任何額外的支撐結構」，列印完成冷卻後只需在清粉站將多餘散粉噴砂吹除即可，設計自由度極高。金屬 PBF 則因劇烈熱應力與重力仍需金屬支撐散熱防翹曲。\n### 【選項辨析】\n- **(A) 光聚合固化成型技術 (VPP)**：液態樹脂浮力不足以抵抗重力與拉拔力，懸臂必須設計支撐。\n- **(B) 熔融擠製成型技術 (FFF)**：懸臂大於 45 度時熔絲懸空垂墜，必須建立支撐結構。\n- **(C) 指向性能量沉積技術 (DED)**：懸臂處熔池在重力下流淌，需要支撐或多軸姿態旋轉。\n- **(D) 高分子材料之選擇性雷射燒結 (SLS / PBF)**：正確。周圍未燒結之鬆散粉末天然提供均勻支撐，無需支撐結構。",
