    "assessmentContent": "歷屆",
    "num": 36,
    "stem": "在火星上欲直接利用其地表之岩石與土壤粉末作為成型原料，來建造基地建築， 下列何種積層製造製程最適當？",
    "question": "在火星上欲直接利用其地表之岩石與土壤粉末作為成型原料，來建造基地建築， 下列何種積層製造製程最適當？",
    "options": [
      "光聚合固化成型技術(VPP)",
      "材料擠製成型技術(MEX)",
      "粉末床熔融成型技術(PBF)",
      "薄片疊層成型技術(SHL)"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】地外原位資源利用 (ISRU) 建築積層製造技術選擇\n### 【正確答案說明】\n在太空探索原位資源利用（In-Situ Resource Utilization, ISRU）情境下（如月球基地或火星殖民地建築），從地球運輸大量液態樹脂或高分子線材成本極度昂貴。火星地表富含玄武岩碎屑、二氧化矽及富鐵風化土壤粉末（Regolith，風化層壤）。針對鬆散的土壤與岩石粉末，最適當的積層製造策略是直接利用當地的顆粒粉體：\n1. **粉末床選擇性太陽能/雷射聚能燒結（PBF 原理）**；或\n2. **黏著劑噴印成型（Binder Jetting, BJT）**，利用少量黏結劑噴射黏固火星壤粉末堆疊厚重防護牆。\n相較之下，FFF 需先提煉合成均勻線材，VPP 需精細液態光化學有機樹脂，在火星環境均不可行。\n### 【選項辨析】\n- **(A) 熔融擠製成型技術 (FFF)**：岩石土壤非熱塑性塑膠，無法直接拉絲成線材擠出。\n- **(B) 光聚合固化成型技術 (VPP)**：火星表面無光敏樹脂單體與寡聚物原料。\n- **(C) 粉末床熔融或粉末黏印沉積成型**：正確。直接就地取材利用鬆散風化岩土粉末進行燒結或黏合。\n- **(D) 薄片疊層成型技術 (SHL)**：火星壤無法自然壓延成大面積韌性薄片。",
