    "num": 37,
    "stem": "電弧熔絲積層製造(WAAM: Wire Arc Additive Manufacturing)是下列積層製造分 類中的哪一類？",
    "question": "電弧熔絲積層製造(WAAM: Wire Arc Additive Manufacturing)是下列積層製造分 類中的哪一類？",
    "options": [
      "指向性能量沉積技術(DED)",
      "粉末床熔融成型技術(PBF)",
      "材料擠製成型技術(MEX)",
      "薄片疊層成型技術(SHL)"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】電弧熔絲積層製造 (WAAM) 之 ASTM 技術類別歸屬\n### 【正確答案說明】\n電弧熔絲積層製造（Wire Arc Additive Manufacturing, WAAM）是以傳統氣體保護銲接電弧（如 GMAW/MIG、GTAW/TIG、CMT 冷金屬過渡）為熱源，將金屬焊絲連續饋入電弧熔池中，在運動機構帶動下逐道堆疊熔覆形成金屬結構。\n依據 ASTM F42 / ISO 52900 積層製造標準分類：\nWAAM 具備「將原料（金屬絲）直接引導至沉積區域並同步利用熱能（電弧）沉積」的完整特徵，因此嚴格歸屬於 **指向性能量沉積技術（Directed Energy Deposition, DED）** 大類。\n### 【選項辨析】\n- **(A) 指向性能量沉積成型技術 (DED)**：正確。WAAM 為送絲型 DED 製程之典型代表。\n- **(B) 材料擠製成型技術 (MEX)**：MEX 專指高分子塑料或金屬漿料擠出，非高能電弧放電熔覆。\n- **(C) 粉末床熔融成型技術 (PBF)**：PBF 原料必須為預鋪粉末床，與 WAAM 連續送絲電弧無關。\n- **(D) 黏著劑噴印成型技術 (BJT)**：使用液態化學膠水噴印，無電弧高溫冶金。",
    "id": 37,
