    "stem": "積層製造技術近年常應用於醫學工程領域，請問關於技術優勢的考量，下列敘述 何者有誤？",
    "question": "積層製造技術近年常應用於醫學工程領域，請問關於技術優勢的考量，下列敘述 何者有誤？",
