    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】積層製造於生醫工程領域應用之技術價值與邊界評估\n### 【正確答案說明】\n積層製造（3D 列印）在生醫醫療工程之所以獲得爆炸性應用，是因為其完美解決了醫療的核心痛點：\n1. **患者專屬客製化**：人體解剖結構因人而異，AM 結合 CT/MRI 醫學影像可製造百分百吻合骨缺損之客製化植入物（如顱骨補片、髖關節臼杯）。\n2. **多孔骨整合結構（Trabecular Bone Structure）**：金屬 3D 列印能直接成型模仿人體松質骨的多孔晶格，促進自體骨細胞長入（Osseointegration）。\n3. **手術導板與病灶模型**：輔助醫師術前模擬規劃，縮短手術時間與創傷。\n生醫 3D 列印追求的是「極致客製化與高精準醫療價值」，並非「單一規格醫療器材之低成本大量生產」。傳統標準骨釘骨板大量製造仍以 CNC 數控車銑具成本優勢。故 (C) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 可依據患者斷層掃描 (CT) 數據製作高度客製化植入體**：正確。完美匹配個人解剖幾何。\n- **(B) 可製造多孔仿生骨小樑結構以促進骨細胞生長結合**：正確。傳統切削無法成型內部通孔晶格。\n- **(C) 旨在透過單一標準品之海量生產以最大化壓低零件成本**：有誤。醫療 AM 重心在客製化高附加價值，非標準品低價批產。\n- **(D) 可快速製造手術導板以大幅提升手術定位精度**：正確。縮短手術麻醉時間並降低風險。",
