    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】FFF 成型件微觀層間黏結本質與力學各向異性 (Anisotropy)\n### 【正確答案說明】\n在 FFF（FDM）成型過程中：\n- 水平 XY 平面內，塑料熔絲是由噴嘴連續擠出拉伸鋪設，高分子長鏈分子在剪切流場中沿著擠出軸向高度定向排列，且線段內部為連續相，因此 XY 平面具有優異的抗拉強度。\n- 垂直 Z 軸方向，則是依靠後一沉積層的餘熱將已冷卻的前一層上表面局部重熔，分子鏈透過熱擴散跨越介面纏結。由於熔接時間極短且缺乏足夠的靜水壓力，層與層之間不可避免地存在接觸頸部（Neck growth）空隙與次強熱融介面，導致垂直 Z 軸的抗拉強度通常僅有水平 XY 方向的 40%~70%，呈現極度顯著的「力學各向異性（Anisotropy）」。\n因此，若敘述稱「FFF 成型件各方向具備均勻一致的力學各向同性（Isotropy）」，完全違背高分子積層沉積物理本質。故 (C) 選項有誤。\n### 【選項辨析】\n- **(A) 靠熱熔融線材逐層黏結堆疊成型**：正確。FFF 基本熱物理成型機制。\n- **(B) 列印方位對工件承受拉力的方向強度有決定性影響**：正確。拉力應盡量配置於纖維同向之 XY 平面。\n- **(C) 成品在各方向具備均勻一致的各向同性力學強度**：錯誤。層間结合弱於層內，具強烈各向異性。\n- **(D) 噴嘴直徑會影響水平特徵的最小解析度**：正確。線寬受噴嘴出口孔徑限制。",
