    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】積層製造 (Additive Manufacturing) 之標準術語與近義詞辨析\n### 【正確答案說明】\n依據國際標準組織 ISO / ASTM 52900 規範：\n- 「**積層製造（Additive Manufacturing, AM）**」為正式標準統稱。\n- 工業界與大眾媒體常使用的同義或近義詞包括：**3D 列印（3D Printing）**、**快速原型（Rapid Prototyping, RP）**、**實體自由成型（Solid Freeform Fabrication, SFF）**、**增材製造** 等。\n- 「**減材製造（Subtractive Manufacturing）**」則是傳統機械加工的統稱（如 CNC 數控車削、銑削、刨削、磨削），其原理是從大塊實體毛坯上逐步切除多餘材料留下零件，與「加法逐層堆疊」的積層製造在原理上完全對立。故 (B) 不屬於積層製造之別稱。\n### 【選項辨析】\n- **(A) 3D 列印 (3D Printing)**：為大眾最普及之同義統稱。\n- **(B) 減材製造 (Subtractive Manufacturing)**：錯誤（本題正解）。指 CNC 車銑等切除材料之加工法。\n- **(C) 快速原型 (Rapid Prototyping)**：為 AM 技術早期之正式工業別稱。\n- **(D) 增材製造**：為華語地區對 Additive Manufacturing 之另一標準翻譯。",
