    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】材料噴印成型技術 (MJT) 光敏樹脂微滴固化特徵辨析\n### 【正確答案說明】\n在 MJT（如 PolyJet）設備中，噴頭陣列高速噴出極微細的光敏樹脂液滴於工作台表面。噴頭小車兩側均安裝有高強度紫外光燈（UV Curing Lamp / UV-LED），在噴射微滴剛鋪展整平的「瞬間（數毫秒內）」，UV 燈緊隨掃描而過照射強光，直接誘發光化學交聯反應將液態微滴瞬時固化為堅硬固體。\nMJT 所使用的樹脂屬於「反應型光聚合高分子」，其固化完全依賴光化學反應，絕非依賴如蠟材那般的「物理自然冷卻硬化」。故 (D) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 可達成極薄切層厚度 (如 16-30 微米)**：正確。液滴微小，垂直分層極其細緻平滑。\n- **(B) 可在同一工件混合噴射不同硬度與顏色的樹脂**：正確。數位材料（Digital Materials）技術之獨特優勢。\n- **(C) 需要同步噴射可溶性或凝膠狀支撐材料**：正確。懸臂處靠專用支撐液滴承托。\n- **(D) 噴出之液態樹脂完全依賴自然降溫冷卻達到凝固狀態**：錯誤。光敏樹脂需依賴 UV 光照射引發聚合反應，無光照不會固化。",
