    "assessmentContent": "歷屆",
    "num": 46,
    "stem": "光聚合固化成型技術(VPP)的 SLA 上照式(Top-down)系統中，為提升固化深度，其 參數調整下列何者正確？",
    "question": "光聚合固化成型技術(VPP)的 SLA 上照式(Top-down)系統中，為提升固化深度，其 參數調整下列何者正確？",
    "options": [
      "提高掃描速度",
      "提高雷射功率",
      "加大雷射光斑",
      "加大掃描線間距"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】Beer-Lambert 定律與雷射立體光固化 (SLA) 固化深度 (Cd) 參數控制\n### 【正確答案說明】\n在 SLA 光固化反應中，雷射照射使樹脂固化的垂直深度 $C_d$ 遵循著名的 Jacobs 光固化方程（源自 Beer-Lambert 吸收定律）：\n$$C_d = D_p \\ln\\left(\\frac{E_{\\max}}{E_c}\\right)$$\n其中：\n- $D_p$ 為樹脂透光深度（Penetration depth，材料固有物理常數）；\n- $E_c$ 為臨界固化曝光能量（Critical exposure）；\n- $E_{\\max}$ 為雷射在樹脂液面中心點賦予的最大能量密度。\n能量密度 $E_{\\max}$ 與雷射輸出功率 $P_L$ 成正比，與雷射掃描掃劃速度 $V_s$ 及光斑半徑 $w_0$ 成反比：\n$$E_{\\max} \\propto \\frac{P_L}{w_0 V_s}$$\n因此，若要「提升單層固化深度 $C_d$」，必須提高液面接受的能量密度 $E_{\\max}$，其正確的操作參數調整為「**提高雷射發射功率**」或「**降低雷射掃描速度（增加局部受光時間）**」。故 (B) 選項正確。\n### 【選項辨析】\n- **(A) 提高雷射掃描速度，降低雷射功率**：錯誤。會急劇減少能量密度，使固化深度變淺甚至無法硬化。\n- **(B) 降低雷射掃描速度，或提高雷射功率**：正確。提高單位面積沉積能量，顯著加深光化學反應固化深度。\n- **(C) 提高掃描速度且不改變功率**：錯誤。曝光時間縮短，固化深度降低。\n- **(D) 降低樹脂槽溫度以延緩光反應**：錯誤。降溫提高黏度不利於固化深度控制。",
