    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】FFF 工具頭運動機構傳動元件 vs 光學元件分類\n### 【正確答案說明】\nFFF 3D 列印機的噴頭在空間進行 X/Y/Z 三軸精密平移運動，其機械運動傳動鏈標準零件包含：\n- 步進馬達（驅動動力源）\n- 同步齒輪與同步帶（Timing Belt，皮帶傳動）\n- 線性光軸、導軌滑塊或 V 型槽導輪\n- 導螺桿與消反向間隙螺母（Z 軸升降傳動）\n「光學振鏡（Galvanometer / Galvo Scanner）」是一對高頻微動馬達帶動反射鏡片，專門用於 SLA、SLM 等雷射光學系統中偏轉雷射光束的高精密光學模組，完全不屬於 FFF 噴頭運動控制零件。\n### 【選項辨析】\n- **(A) 光學振鏡 (Galvanometer)**：正確（非 FFF 零件）。屬於雷射光學掃描系統部件。\n- **(B) 同步帶 (Timing Belt)**：FFF 零件。用於帶動 X/Y 軸擠出頭高速平移。\n- **(C) 步進馬達 (Stepper Motor)**：FFF 零件。提供精準開迴路/閉迴路步進旋轉角度。\n- **(D) 線性滑軌 (Linear Rail)**：FFF 零件。提供精確平直之幾何滑動約束。",
    "id": 47,
    "display_num": 47,
