    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】面光源光固化技術 (DLP / LCD) 之像素縮放與精度物理限制\n### 【正確答案說明】\n在面曝光光聚合固化（DLP / LCD）系統中：\n- DLP / LCD 將整層影像所有像素一次性投射固化，因此無論該層是小零件還是滿盤零件，單層曝光秒數（如 2.5 秒）完全固定。\n- 面曝光的空間幾何解析度由「物理像素尺寸（Pixel Pitch / Size）」決定。當投影光學系統放大投影畫面以獲得更大的列印幅面（Build Area）時，原本 1920×1080 個像素點會被放大拉伸覆蓋在更大的面積上，使得「單個像素在成型平面的物理長寬放大」，細節還原能力隨之劣化，邊緣鋸齒（Voxelization）增粗，因此列印精度會「顯著下降」。\n故 (B) 選項稱「擴大列印範圍時精度完全不受影響」為嚴重錯誤。\n### 【選項辨析】\n- **(A) 整層一次曝光，列印時間主要取決於模型高度而非單層面積大小**：正確。面曝光之高效率本質。\n- **(B) 相同解析度之投影機，投射列印面積擴大時其成型精度完全不變**：錯誤。面積放大導致單位像素增大，成型精度必然降低。\n- **(C) 液晶面板式 (LCD) 常採用高密度矩陣 UV-LED 作為背光源**：正確。提供平行均勻的紫外平行光源。\n- **(D) 可利用抗鋸齒（Anti-aliasing）演算法平滑像素邊界梯級**：正確。以灰階半像素調光弱化台階感。",
