    "explanation": "### 【核心考點】有機清洗溶劑 (IPA) 與個人防護裝備 (PPE) 之手套材質相容性\n### 【正確答案說明】\n在光固化模型後處理初期，必須將附著大量有毒光敏樹脂的模型浸入異丙醇（IPA）或專用清洗液中振盪沖洗。\n- **乳膠手套（Natural Latex Rubber）**：分子結構孔隙較大，對有機溶劑（如酒精、IPA、丙酮、甲苯）耐受性極差。當乳膠接觸異丙醇時，會在數分鐘內發生迅速溶脹、滲透軟化甚至溶解破裂，使有毒化學物質迅速滲透至手部皮膚。\n- **丁腈橡膠手套（Nitrile Gloves）**：對油脂、光固化樹脂丙烯酸酯單體及異丙醇等醇類溶劑具有卓越的耐化學滲透防護能力，為全球生化與 3D 列印實驗室標準防護手套。\n因此，在異丙醇清洗步驟中，「天然乳膠手套」極不適合使用。故 (C) 為本題正解。\n### 【選項辨析】\n- **(A) 丁腈橡膠手套 (Nitrile)**：高度推薦。耐溶劑與抗樹脂穿透能力極佳。\n- **(B) 防化學飛濺護目鏡**：必備。防止清洗溶劑與樹脂液滴飛濺入眼。\n- **(C) 天然乳膠手套 (Latex)**：不適合。會被異丙醇等有機溶劑迅速滲透軟化失效。\n- **(D) 活性碳防護口罩**：推薦使用。吸附有機溶劑高揮發性有機廢氣。",
