    "explanation": "### 【核心考點】3D 列印模型表面後處理機械打磨之工業安全與粉塵防護\n### 【正確答案說明】\n在光固化模型完成酒精清洗並於紫外光箱二次固化後，工件已成為化學穩定的固態交聯高分子。進行模型支撐殘留凸點的剪除、銼削與砂紙機械打磨時，涉及的工業安全與衛生規範包括：\n1. **防塵口罩（如 N95 / P100 / 防塵面罩）**：打磨會產生大量微細高分子粉塵，吸入肺泡會沉積引起塵肺病或呼吸道黏膜過敏損傷，必須嚴格配戴。\n2. **安全防護眼鏡**：防止高速飛濺的固體碎屑與粉塵刺入眼睛。\n3. **通風集塵或水磨濕式作業**：砂紙沾水濕磨可直接從源頭抑制粉塵飛揚。\n由於此時模型內部與表面之光敏化學鍵已於後固化箱中徹底完全交聯，且已無液態光敏樹脂存在，一般的常態可見光已不可能造成材料變質，因此打磨工序「完全不需要在防紫外線的黃光室中操作」。故 (D) 非其要求。\n### 【選項辨析】\n- **(A) 應配戴防塵防微粒口罩以避免吸入打磨碎屑微粒**：必要要求。保護呼吸道防範微細高分子粉塵危害。\n- **(B) 應配戴防護眼鏡以防高速碎屑噴濺**：必要要求。防止碎屑機械刺傷眼球。\n- **(C) 建議採沾水濕磨或於通風集塵環境作業**：必要要求。降低粉塵濃度維持良好環境衛生。\n- **(D) 打磨工序必須嚴格在防紫外線的黃光潔淨室中進行**：非安全要求。固化已完全終止，黃光室僅為未固化感光材料配製作業所需。",
