    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】下照式 (Bottom-Up) VPP 底層附著不良 (Adhesion Failure) 之參數調控\n### 【正確答案說明】\n在下照式光聚合固化（VPP）中，若發生列印初期模型無法附著在金屬成型板上，反而黏在槽底離型膜上脫落，最常見的原因是第一層（Bottom Layer）光聚合程度不足，未能在金屬板微觀粗糙孔隙中建立牢固的機械咬合力。\n改善此問題最標準且有效的參數調整是「增加底層曝光時間（Bottom Exposure Time）」，通常將底層曝光時間設定為正常單層曝光時間的 5 至 10 倍（例如正常層 2.5 秒，底層設為 20-30 秒），透過深度過固化產生極高交聯度，確保底層牢牢錨定在金屬平台上。\n### 【選項辨析】\n- **(A) 增加底層曝光時間**：正確。大幅提升底層光聚合硬化程度與對金屬平台的錨固黏著力。\n- **(B) 提高支撐結構密度**：支撐是生長在底座之上的結構，若底層本身未黏住平台，增加支撐密度無法解決脫底問題。\n- **(C) 增加平台抬升距離**：抬升距離影響的是離型膜充分剝離，與底層對平台的初始黏附力無關。\n- **(D) 提高平台抬升速度**：拉抬速度越快瞬態剝離阻力越大，反而更容易將模型從平台上扯落。",
    "id": 51,
    "display_num": 1,
    "source_id": "3d-3f916a89e907031a",
    "source_version": "official-through-115-05",
    "question_uid": "3d-41cc89d48aa45483e546cfc6",
    "content_hash": "b65f54ba5c7dbbce7da6d53b82e7e1d7c9b0224e2abd5bff6e15a4a7770b4e44"
