    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】熔融擠製成型 (FFF) 模型底層翹曲 (Warping) 熱應力機理與改善對策\n### 【正確答案說明】\n在 FFF 列印中，熱塑性熔融材料自噴嘴擠出（約 200°C~250°C）沉積在平台上時，高低溫差會產生顯著的冷卻收縮體積變化。若環境溫度偏低或溫差過大，上下層冷卻速率不均會累積巨大的內部熱收縮彎曲應力，將模型邊角硬生生從平台上拉扯掀起，造成「翹曲（Warping）」。\n有效的改善對策包括：\n1. **提高列印環境溫度（使用封閉保溫箱體）**：降低材料與環境溫差，減緩冷卻收縮速率，促使熱應力退火釋放。\n2. **開啟並提高熱床溫度**：維持底層處於高分子玻璃轉移溫度（$T_g$）附近，保持附著黏性。\n3. **開啟邊緣擴展（Brim）輔助結構**：擴大底層附著面積。\n故 (B) 選項「提高列印環境溫度」是消除翹曲的根本對策。\n### 【選項辨析】\n- **(A) 關閉熱床加熱功能**：錯誤。無熱床保溫會使底層劇烈急速冷卻，大幅惡化翹曲。\n- **(B) 提高列印環境溫度**：正確。維持腔體恆溫能有效減緩收縮應力，消除邊角翹曲。\n- **(C) 關閉邊緣支撐功能**：錯誤。關閉 Brim 會使接觸面積減小，更容易翹曲。\n- **(D) 提高模型內部填充率**：錯誤。填充率越高，冷卻收縮的材料體積與拉力越大，反而加劇翹曲。",
