    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】光聚合固化成型 (VPP) 之紫外線二次後固化 (Post-Curing)\n### 【正確答案說明】\n在光聚合固化成型技術（Vat Photopolymerization, VPP）中，機台內部逐層列印完成的工件被稱為「生胚（Green Part）」，其內部的化學反應轉化率通常僅達 70%~85%，仍殘留部分未完全交聯的單體與游離基，材料力學性能與熱變形溫度尚未達到峰值，且表面微黏。\n因此，VPP 零件在經過酒精清洗乾燥後，「通常必須置入紫外線後固化箱中進行二次曝光（UV Post-Curing）」，甚至輔以溫控加熱，促使殘留活性基團徹底交聯反應，達成 95% 以上之交聯密度，顯著提高零件的抗拉強度、彈性模數、硬度與尺寸耐候穩定性。\n### 【選項辨析】\n- **(A) 熔融擠製成型技術 (FFF)**：熱塑性塑料靠物理降溫冷卻結晶凝固，無需 UV 二次曝光。\n- **(B) 粉末床熔融成型技術 (PBF)**：高分子或金屬粉末靠熱熔融結合，冷卻後即達最終力學性能，無光化學反應。\n- **(C) 薄片疊層成型技術 (SHL)**：利用膠黏劑或超音波壓合，不涉及光化學二次曝光。\n- **(D) 光聚合固化成型技術 (VPP)**：正確。化學反應生胚必須經過紫外線二次曝光以達到完全交聯硬化。",
    "id": 53,
    "display_num": 3,
