    "question": "下列哪一項不屬於材料擠製成型技術(MEX)的切層參數？",
    "options": [
      "壁厚(Wall Thickness)",
      "層厚(Layer Thickness)",
      "內部填充率(Infill Density)",
      "曝光時間(Light-Curing Time)"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】材料擠製成型技術 (MEX / FFF) 切層工藝參數識別\n### 【正確答案說明】\n材料擠製成型（MEX / FFF）切層軟體（如 Cura、PrusaSlicer、Bambu Studio）中的關鍵切層參數包括：\n- **層厚（Layer Thickness / Height）**\n- **壁厚 / 外圈數（Wall Thickness / Perimeters）**\n- **內部填充率與樣式（Infill Density & Pattern）**\n- **列印溫度與熱床溫度（Printing / Bed Temperature）**\n- **列印速度與回抽參數（Speed & Retraction）**\n「雷射光斑聚焦直徑 / 雷射功率」屬於粉末床熔融（PBF）或立體光固化（SLA）等高能光學系統之專用參數，MEX 製程中完全不使用雷射，故不屬於 MEX 切層參數。\n### 【選項辨析】\n- **(A) 壁厚 (Wall Thickness)**：為 MEX 關鍵切層參數，決定外殼實心圈數與表面強度。\n- **(B) 層厚 (Layer Thickness)**：為 MEX 核心幾何切層參數，決定 Z 軸解析度。\n- **(C) 內部填充率 (Infill Density)**：為 MEX 內部結構切層參數。\n- **(D) 雷射功率 / 光學焦距**：正確（不屬於 MEX）。MEX 是熱熔機械擠出，完全無雷射光學組件。",
