    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】聚乳酸 (PLA) 之生物相容性、低毒性與生物可降解性\n### 【正確答案說明】\n聚乳酸（Polylactic Acid, PLA）是一種熱塑性脂肪族聚酯，其原料直接提煉自玉米、木薯或甘蔗等可再生植物澱粉，經過發酵生成乳酸後縮聚而成：\n- 列印過程中散發微甜香氣，揮發性有機化合物（VOCs）排放量極低，生物毒性在所有 FFF 線材中最低；\n- 在工業堆肥環境（溫度 55-60°C、適當濕度與微生物菌群）下，能在數月內被微生物完全分解轉化為水與二氧化碳，具備高度之「生物可降解性與環境相容性」。\n### 【選項辨析】\n- **(A) 丙烯腈-丁二烯-苯乙烯 (ABS)**：源自石油提煉，列印會釋放苯乙烯有毒刺激氣體，不可生物降解。\n- **(B) 聚碳酸酯 (PC)**：高熔點工程塑料，難以自然降解。\n- **(C) 聚乳酸 (PLA)**：正確。源自植物澱粉，低毒性且具優異生物可分解性。\n- **(D) 聚苯乙烯 (HIPS)**：石油基合成塑料，不可生物分解。",
