    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】FFF 支撐結構 (Support) 之接觸間隙與介面分離原理\n### 【正確答案說明】\n在 FFF 列印中，支撐結構用來承托懸空模型：\n- 懸空角度一般大於 45°~50° 時需要開啟支撐。\n- 支撐與模型本體在垂直方向上「必須保留微小的 Z 軸分離間隙（Z Contact / Support Roof Gap，通常設定為 1 個層厚約 0.1~0.2 mm）」；若支撐頂面與模型底面完全緊密無間隙融合，兩者在高溫下會完全熔為一體，導致列印完成後支撐「完全無法剝離」，強行拆卸會造成模型表面嚴重破損。故 (C) 選項稱「不需要保留間隙」為嚴重錯誤。\n### 【選項辨析】\n- **(A) 一般懸空角大於 45 度之特徵通常需要生成支撐**：正確。經驗臨界自支撐傾角法則。\n- **(B) 支撐類型包含線狀、網格狀與樹狀（Tree support）**：正確。樹狀支撐省料且接觸點小易拆除。\n- **(C) 支撐結構必須與模型表面完全無縫貼合熔接，不可預留任何間隙**：錯誤。必須保留微小 Z 間隙以利後續機械剝除。\n- **(D) 開啟支撐會增加總體耗材用量與列印時間**：正確。額外列印支撐體會增加耗時與廢料。",
