    "num": 7,
    "stem": "STL 檔案被廣泛用於描述 3D 模型，關於 STL 檔案特性的敘述，下列何者正確？",
    "question": "STL 檔案被廣泛用於描述 3D 模型，關於 STL 檔案特性的敘述，下列何者正確？",
    "options": [
      "有 ASCII 與 Binary 兩種格式",
      "檔案內含材料密度改變的資訊",
      "可使用表面貼圖以建立全彩模型",
      "可透過三角網格精確描述曲面無誤差"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】STL 檔案格式特徵與三維幾何描述限制\n### 【正確答案說明】\nSTL（Stereolithography）是由 3D Systems 於 1987 年制訂的積層製造標準幾何介面檔案格式：\n1. **檔案編碼格式**：包含 **ASCII（文字檔）** 與 **Binary（二進位檔）** 兩種格式，Binary 格式體積小、讀取快速，為工業主流。\n2. **描述方式**：僅使用一系列未結構化的三角形小平面（Facets）及其外法向量來近似逼近 3D 物體的表面幾何。\n3. **資訊限制**：STL「完全不包含」任何顏色、材質、紋理貼圖、內部實體密度或階層特徵資訊（全彩或材質需使用 3MF 或 OBJ/AMF 格式）；且曲線與曲面皆是以平面的三角形網格近似逼近，存在弦高逼近誤差。故 (A) 選項正確。\n### 【選項辨析】\n- **(A) 有 ASCII 與 Binary 兩種格式**：正確。ASCII 具可讀性，Binary 傳輸效率高。\n- **(B) 檔案內含材料密度與重量資訊**：錯誤。STL 僅記錄表面幾何網格頂點座標，無物理屬性。\n- **(C) 可使用表面貼圖以建立全彩模型**：錯誤。STL 完全不支援顏色與 UV 貼圖。\n- **(D) 可透過三角網格精確描述連續曲面無誤差**：錯誤。以平面逼近曲面必然存在弦高誤差（Chordal error）。",
