    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】光聚合固化 (VPP) 切層厚度 (Layer Thickness) 對成型品質之影響\n### 【正確答案說明】\n在光固化切層設定中，切層厚度（常見設定為 0.025 mm 至 0.1 mm）：\n- 切層厚度愈小，在相同的模型高度下，所需的總切層層數愈多，垂直方向的台階效應（Staircase effect）愈微小，表面粗糙度顯著降低，細節還原度極高；但總列印時間也會等比例大幅增加。\n- 當切層厚度設定較大時，單層樹脂變厚，因此需要適度提高單層曝光時間以確保光子能穿透足夠深度達成層間結合。\n- 「模型的整體垂直高度」是由原始 3D CAD 幾何尺寸決定的，切層厚度的改變只會微調最頂層分層的四捨五入誤差，絕對不會導致「模型總高度隨切層厚度大幅增加」。故 (D) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 切層厚度愈小，相同高度下所需列印層數愈多**：正確。高度除以層厚等於總層數。\n- **(B) 切層厚度愈小，模型表面粗糙度相對降低**：正確。階梯效應弱化，表面更光潔。\n- **(C) 切層厚度愈大，需提升曝光時間以確保層間結合**：正確。需更深固化深度以防層間剝離。\n- **(D) 切層厚度愈大，模型的整體高度將隨之顯著增加**：錯誤。工件實體宏觀高度由 CAD 尺寸決定。",
