    "stem": "有四個具四階斷差的模型，列印製程採用下照式(Bottom-Up)光聚合固化成型技術 (VPP)，各段的切層順序如下圖：    其四段的切層截面圖包括下列四個樣式：  1 2 3 4  模型甲第一段至第四段的切層截面順序為: 1→2→3→4  模型乙第一段至第四段的切層截面順序為: 4→3→2→1  模型丙第一段至第四段的切層截面順序為: 2→1→4→3  模型丁第一段至第四段的切層截面順序為: 1→4→2→3  請問哪一個模型可以成功列印？\n\n![切層順序](images/3d/exam2_q9_order.png)\n\n樣式 1: ![樣式1](images/3d/exam2_q9_sec1.png) 樣式 2: ![樣式2](images/3d/exam2_q9_sec2.png)\n樣式 3: ![樣式3](images/3d/exam2_q9_sec3.png) 樣式 4: ![樣式4](images/3d/exam2_q9_sec4.png)",
