    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】下照式 VPP 懸臂截面階梯幾何與由大至小連續生長判讀\n### 【正確答案說明】\n在下照式（Bottom-Up）光固化製程中，成型平台自樹脂槽底「由下往上」逐步拉抬。模型若要成功列印且「不添加額外懸空支撐」，每一新固化層的投影面積「必須被前一層的固化實體所覆蓋或完全承托」；若新固化層的截面突變、或某部分截面懸空於液體中（即出現孤島 Island 或突發大截面倒懸），該懸空部位在固化瞬間無法附著於上方的已成型模型上，反而會硬化黏附在透明槽底離型膜上，導致列印失敗。\n四階斷差模型在下照式列印中，最穩固的自支撐順序是讓成型板底座先成型出大截面，隨後截面「由大至小」順序遞減延伸，或者截面具備合理自承托搭接。在題目給定的四段截面樣式中，乙（4→3→2→1）或丙模型符合投影截面自下而上連續承托幾何邏輯，能避免懸空孤島脫落，達成成功列印。\n### 【選項辨析】\n- **(A) 模型甲**：初期截面小，後續截面大幅擴展懸空，無支撐必然脫落。\n- **(B) 模型乙**：需配合截面幾何拓撲驗證是否滿足連續覆蓋。\n- **(C) 模型丙**：正確。截面拓撲延伸滿足下照式逐層附著與幾何包覆限制。\n- **(D) 模型丁**：截面跳躍出現懸空孤島特徵，無法成功附著。",
    "id": 59,
    "display_num": 9,
    "source_id": "3d-3f916a89e907031a",
