    "assessmentTopic": "歷屆",
    "assessmentContent": "歷屆",
    "num": 10,
    "stem": "在熔融擠製成型技術(FFF)中，常見列印材料 PLA(聚乳酸)與 ABS(丙烯腈-丁二烯- 苯乙烯共聚物)的列印參數特性，下列敘述何者不正確？",
    "question": "在熔融擠製成型技術(FFF)中，常見列印材料 PLA(聚乳酸)與 ABS(丙烯腈-丁二烯- 苯乙烯共聚物)的列印參數特性，下列敘述何者不正確？",
    "options": [
      "PLA 的噴嘴溫度常低於 ABS",
      "PLA 的列印腔體溫度常低於 ABS",
      "PLA 的熱床溫度常低於 ABS",
      "PLA 的列印速度常低於 ABS"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】PLA 與 ABS 線材熱物理特性與熱床參數對比\n### 【正確答案說明】\n在 FFF 常用耗材中，PLA 與 ABS 具有截然不同的熱力學參數：\n1. **聚乳酸（PLA）**：玻璃轉移溫度 $T_g \\approx 55-60^\\circ\\text{C}$，熔點約 150-160°C，列印溫度約 190-220°C，熱膨脹係數小收縮率低。列印時熱床設定為 **50-60°C**，甚至塗膠冷床即可成型。\n2. **ABS**：玻璃轉移溫度 $T_g \\approx 105^\\circ\\text{C}$，無固定熔點，列印溫度約 230-250°C，熱收縮率高達 0.8%。為克服劇烈熱應力與翹曲，熱床溫度必須提高至 **90-110°C**，且必須在封閉恆溫箱中列印。\n因此，ABS 的熱床溫度「遠高於」PLA。若稱「PLA 所需熱床溫度高於 ABS」，完全違背熱物理事實。故 (D) 選項敘述不正確。\n### 【選項辨析】\n- **(A) ABS 的擠出列印溫度通常高於 PLA**：正確。ABS 需 230-250°C，PLA 需 190-215°C。\n- **(B) ABS 材料冷卻收縮率大於 PLA，較容易產生翹曲**：正確。ABS 熱脹冷縮劇烈。\n- **(C) PLA 建議開啟模型散熱風扇以提高懸臂冷卻成型品質**：正確。風冷能迅速使 PLA 固化成型。\n- **(D) PLA 列印時所需之熱床溫度通常高於 ABS**：錯誤（本題正解）。ABS 熱床需 100°C 左右，遠高於 PLA 之 50-60°C。",
    "id": 60,
