    "subject_name": "第二科：3D製程與材料概論",
    "chapter": "115年第一次歷屆試題",
    "assessmentTopic": "歷屆",
    "assessmentContent": "歷屆",
    "num": 12,
    "stem": "以熔融擠製成型技術(FFF)列印模型時，為了降低列印中出現牽絲(Stringing)缺 陷的狀況，下列哪種調整方式無法達成？",
    "question": "以熔融擠製成型技術(FFF)列印模型時，為了降低列印中出現牽絲(Stringing)缺 陷的狀況，下列哪種調整方式無法達成？",
    "options": [
      "降低熱床溫度",
      "降低擠出頭溫度",
      "增加回抽速度",
      "增加回抽距離"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】FFF 牽絲 (Stringing / Oozing) 缺陷之流變學機理與抑制對策\n### 【正確答案說明】\n牽絲（Stringing）是指噴頭在非列印的空移（Travel move）過程中，熱端熔融腔內的熔體因重力與毛細壓力自噴嘴滲漏溢出（Oozing），在模型不同凸起島嶼間拉出微細蜘蛛網狀塑料絲的缺陷。\n抑止牽絲的標準工藝手段包含：\n1. **啟用並增加回抽距離（Retraction Distance）與速度**：在空移前將線材微向後抽，在噴嘴內形成負壓吸回熔體。\n2. **適度降低列印溫度**：高溫會急劇降低塑料熔體的剪切黏度，大幅增強液體流動性而加劇流涎；降低列印溫度能提升黏度，有效抑制滲漏。\n3. **提高空移速度（Travel Speed）**：減少空移過渡時間。\n若「提高列印溫度」，熔體流動性大增，只會使噴嘴滴料漏料更加劇烈，牽絲必然嚴重惡化，絕對「無法」達成降低牽絲的目的。故 (A) 選項無法達成。\n### 【選項辨析】\n- **(A) 提高噴頭列印溫度**：無法達成（本題正解）。提高溫度會使熔體黏度驟降、流動性倍增，加劇牽絲缺陷。\n- **(B) 增加回抽距離 (Retraction Distance)**：有效對策。在噴嘴內部形成負壓吸回熔體防流涎。\n- **(C) 提高回抽速度 (Retraction Speed)**：有效對策。瞬間卸除熔體擠出壓力。\n- **(D) 提高空行程移動速度 (Travel Speed)**：有效對策。縮短噴嘴在空氣中停留流涎的滯留時間。",
