    "num": 14,
    "stem": "以熔融擠製成型技術(FFF)列印模型時，下列何者為增加內部填充率的主要功用？",
    "question": "以熔融擠製成型技術(FFF)列印模型時，下列何者為增加內部填充率的主要功用？",
    "options": [
      "減少模型收縮",
      "減少列印時間",
      "增加模型強度",
      "增加列印高度"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】FFF 內部填充率 (Infill Density) 對零件宏觀剛度之決定性作用\n### 【正確答案說明】\n在 FFF 切層設定中，模型外圍由實心外壁（Perimeters/Walls）和頂底封頂層包覆，而內部由切層軟體自動填充不同密度與拓撲形貌的晶格網格（Infill）。\n增加內部填充率（例如從 15% 提高至 60%~100%）：\n- 會在零件內部沉積更多的塑料骨架，顯著提升模型承受外力彎曲、壓縮與剪切時的「**整體機械強度、抗壓剛度與衝擊韌性**」。\n- 填充率增加與提高列印速度無關（反而會使列印更耗時），且不會節省耗材（耗材用量成倍增加）。\n### 【選項辨析】\n- **(A) 大幅縮短整體列印所需工時**：錯誤。路徑增加，列印時間顯著延長。\n- **(B) 減少塑料耗材消耗量以降低生產成本**：錯誤。耗材用量隨填充率大幅攀升。\n- **(C) 顯著增強模型的整體機械強度與抗變形剛性**：正確。增加實體截面抗彎與抗壓能力。\n- **(D) 消除外壁表面的階梯層紋以提升外觀精度**：錯誤。層紋由層厚與噴嘴決定，與內部填充無直接關聯。",
