    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】下照式 (Bottom-Up) VPP 長底層曝光 (Burn-in Layers) 之工程目的\n### 【正確答案說明】\n在下照式光固化中，最致命的成型失敗即為「第一層未能牢固黏附在成型金屬板上」。新固化的第一層樹脂與金屬平台（通常為鋁合金拉絲或噴砂表面）之間僅依靠微觀機械嵌合與分子間凡得瓦力結合。\n因此切層軟體通常設定前 3 至 8 層為底層（Burn-in / Bottom Layers），給予極長的曝光時間（正常層的 5~10 倍）：\n1. 激發極高濃度的自由基，使樹脂達到接近 100% 的極致交聯固化度；\n2. 讓固化樹脂產生微觀深度擴散並牢牢咬合滲入金屬平台的細微噴砂孔隙中；\n3. 建立足夠強大的附著結合力，足以承受後續數千層在槽底 FEP 離型膜剝離時產生的劇烈向下垂直拉拔阻力。\n故 (C) 是其最核心之工程目的。\n### 【選項辨析】\n- **(A) 為了避免樹脂槽底部過熱**：錯誤。長時間曝光會使燈源與螢幕產熱增加，非散熱考量。\n- **(B) 為了減少成型件內部的殘餘熱應力**：錯誤。過度固化會加劇固化收縮應力。\n- **(C) 強化模型底層與金屬成型平台之附著強度，防止脫落**：正確。抵抗離型脫模拉拔力的最關鍵保障。\n- **(D) 提升模型頂部外觀精細度**：錯誤。底層曝光僅作用於最底部幾層，與頂部品質無關。",
    "id": 65,
    "display_num": 15,
