    "num": 16,
    "stem": "使熔融擠製成型技術(FFF)列印相同模型，關於噴嘴直徑與層厚的設定，下列何者 為較佳的組合？",
    "question": "使熔融擠製成型技術(FFF)列印相同模型，關於噴嘴直徑與層厚的設定，下列何者 為較佳的組合？",
    "options": [
      "噴嘴直徑 0.4mm、層厚 0.3mm",
      "噴嘴直徑 0.6mm、層厚 0.3mm",
      "噴嘴直徑 0.4mm、層厚 0.4mm",
      "噴嘴直徑 0.6mm、層厚 0.4mm"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】FFF 噴嘴孔徑 (Nozzle Diameter) 與層厚 (Layer Height) 之匹配準則\n### 【正確答案說明】\n在 FFF 擠出加工中，層厚與噴嘴出口直徑存在嚴格的流體力學與幾何幾構經驗匹配規則：\n1. **層厚上限**：層厚「絕對不可超過噴嘴直徑的 75%~80%」（極限通常為 80%）。若層厚過大，噴嘴平唇面（Nozzle flat）無法對剛擠出的圓形截面熔絲施加足夠的垂直熨燙擠壓壓力，熔絲呈自由圓柱狀堆疊，接觸面極窄，會造成極度嚴重的層間結合失效與剝離。\n2. **層厚下限**：層厚過小（小於噴嘴直徑 20%~25%），噴嘴背壓過高易發生回流刨料。\n3. **黃金比例**：最佳工作層厚通常設定在噴嘴直徑的 **25% 至 75%** 之間（最均衡穩定值約為 50%）。\n- 選項 (A)：0.4mm 噴嘴配 0.3mm 層厚（層厚佔 75%，已達極限邊界，層間強度偏弱）。\n- 選項 (B)：**0.6mm 噴嘴配 0.3mm 層厚**（層厚恰為噴嘴直徑的 **50%**），既能維持優異的層間壓合熱傳導，又能發揮 0.6mm 大流量的高列印效率，結構強度與列印穩定性最為理想。\n- 選項 (C)、(D)：層厚等於噴嘴直徑（100%），噴嘴無法擠壓熔絲，必然列印失敗。\n### 【選項辨析】\n- **(A) 噴嘴直徑 0.4mm、層厚 0.3mm**：層厚達 75%，層間結合偏弱。\n- **(B) 噴嘴直徑 0.6mm、層厚 0.3mm**：最佳組合。層厚為孔徑的 50%，擠壓熨燙充分，強度與速度兼備。\n- **(C) 噴嘴直徑 0.4mm、層厚 0.4mm**：錯誤。層厚達 100%，熔絲無法壓平，層間極易開裂分離。\n- **(D) 噴嘴直徑 0.6mm、層厚 0.4mm**：雖可行（66%），但 (B) 之 50% 幾何比例更為穩健。",
