    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】光聚合固化 (VPP) 設備操作之個人防護裝備 (PPE) 規範\n### 【正確答案說明】\n光敏樹脂含有丙烯酸酯單體、低聚物及芳香族光起始劑，具化學刺激性與致敏毒性；清洗溶劑（異丙醇）具揮發性有機廢氣刺激。操作 VPP 設備標準防護裝備包括：\n- **防護眼鏡 / 護目鏡**：防範液滴飛濺入眼及阻隔紫外輻射。\n- **耐化學品手套（丁腈手套）**：阻斷樹脂經皮滲透。\n- **活性碳防護口罩**：吸附有機溶劑與單體刺鼻揮發蒸氣。\n「防塵帽」主要用於半導體高潔淨度無塵室防止人體毛髮皮屑脫落污染晶圓，一般 VPP 光固化設備操作中並非必備之安全防護裝備。\n### 【選項辨析】\n- **(A) 防塵帽**：非必需安全裝備。防塵帽不具備化學危害防護功能。\n- **(B) 防護眼鏡**：必備。防範樹脂飛濺化學灼傷與 UV 光危害。\n- **(C) 活性碳口罩**：必備。過濾光敏單體與異丙醇之揮發氣體。\n- **(D) 合成橡膠 (丁腈) 手套**：必備。提供優異之化學阻隔防護。",
