    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】可自然降解綠色農業育苗盆耗材選型\n### 【正確答案說明】\n在現代綠色農業中，3D 列印培育盆栽或育苗盆時，若要求幼苗移栽時無需脫盆、可直接連盆植入土壤中並在自然環境中由泥土微生物逐步自然降解轉化為有機養分：\n- **聚乳酸（PLA）** 是唯一具備植物生質來源、環境無毒且具生物可降解特性的熱塑性線材，在土壤環境中經過水解與微生物作用最終分解為水與二氧化碳，不會造成微塑料殘留污染。\n- ABS、PETG 與 TPE 皆為不可降解之傳統石油基高分子，深埋土壤百年不腐，會嚴重阻礙幼苗根系發育。\n### 【選項辨析】\n- **(A) 聚乳酸 (PLA)**：正確。生質來源，具生物分解特性，適合作為環保自然降解育苗容器。\n- **(B) 丙烯腈-丁二烯-苯乙烯 (ABS)**：不可降解石油塑料，殘留土壤會造成微塑膠污染。\n- **(C) 聚對苯二甲酸乙二酯 (PETG)**：耐化學性強，自然環境下無法分解。\n- **(D) 熱塑性彈性體 (TPE)**：合成橡膠聚合物，不可生物分解。",
