    "num": 19,
    "stem": "以最少的資料量描述下列四個模型的 STL 檔案，何者所記錄的資料量最少？",
    "question": "以最少的資料量描述下列四個模型的 STL 檔案，何者所記錄的資料量最少？",
    "options": [
      "![選項A](images/3d/exam2_q19_a.png)",
      "![選項B](images/3d/exam2_q19_b.png)",
      "![選項C](images/3d/exam2_q19_c.png)",
      "![選項D](images/3d/exam2_q19_d.png)"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】STL 檔案三角形網格面數量與幾何資料量最小化評估\n### 【正確答案說明】\nSTL 檔案以三角形小平面（Facet）記錄幾何體，每個三角形包含 12 個 32 位元浮點數（1 個法向量 (i,j,k) + 3 個頂點 (x,y,z)）：\n四個基礎幾何體所需的最小三角形面數分別為：\n1. **正四面體（Tetrahedron）**：具有 4 個平面三角形邊界面，描述其幾何僅需 **4 個三角網格**。\n2. **正方體（Cube）**：6 個面，每面需 2 個三角形，共需 **12 個三角網格**。\n3. **圓柱體 / 球體 / 複雜多面體**：曲面需大量三角網格近似，面數至少數十至數百個以上。\n因此，在所有可能的三維閉合多面體中，正四面體所需的三角形數量最少（4個），其 STL 檔案記錄的二進位資料量最小。\n### 【選項辨析】\n- **(A) 正四面體**：正確。僅需 4 個三角網格即可完整封閉描述三維體積，資料量最少。\n- **(B) 三角柱體**：2個三角形底面 + 3個四邊形側面（每面2個三角形），共需 2 + 6 = 8 個網格。\n- **(C) 四角錐體**：1個四邊形底面（2個三角形）+ 4個三角形側面，共需 6 個網格。\n- **(D) 正方體**：6個面 × 2 = 12 個網格，資料量顯著多於四面體。",
