    "num": 21,
    "stem": "以熔融擠製成型技術(FFF)列印模型，請問下列設定何者能提高架橋部位的跨距？",
    "question": "以熔融擠製成型技術(FFF)列印模型，請問下列設定何者能提高架橋部位的跨距？",
    "options": [
      "降低列印溫度，降低列印速度",
      "降低列印溫度，增加列印速度",
      "增加列印溫度，降低列印速度",
      "增加列印溫度，增加列印速度"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】FFF 架橋 (Bridging) 懸空成型物理機制與參數最佳化\n### 【正確答案說明】\n在 FFF 列印中，當噴頭橫跨兩個獨立支撐柱之間的無支撐水平懸空區域時，稱為「架橋（Bridging）」：\n- 熔絲在懸空橫跨過程中，下方完全無任何物體支撐，僅依靠熔絲兩端的張力拉伸支撐自身重量；\n- 若熔體溫度過高，高分子黏度低、呈液態流淌，在重力作用下熔絲會嚴重下垂、斷裂下塌；\n- **改善架橋跨距的關鍵設定**：\n  1. 「**降低列印溫度**」：大幅提升熔絲熔融黏度，促使其剛自噴嘴擠出即迅速硬化；\n  2. 「**提高冷卻風扇風量並適度調整列印速度（通常稍增加拉伸速度或維持平穩速度）**」：使熔絲在空中被強力冷風瞬間冷卻固化成緊繃的水平弦線。\n故「降低列印溫度，增加列印/冷卻速度」能有效避免熔絲積熱下墜，顯著提升架橋跨距。\n### 【選項辨析】\n- **(A) 降低列印溫度，降低列印速度**：速度過慢會使熔絲在熱端下方受熱輻射烘烤過久而下垂。\n- **(B) 降低列印溫度，增加列印速度 (快速拉出並風冷凝固)**：正確。低溫高黏度配合快速拉線風冷，使懸空熔絲迅速凝結成跨橋。\n- **(C) 增加列印溫度，降低列印速度**：最劣組合。熔體如水滴般完全流淌塌落。\n- **(D) 增加列印溫度，增加列印速度**：高溫熔體強度不足，高速拉伸易直接拉斷。",
