    "assessmentContent": "歷屆",
    "num": 22,
    "stem": "以材料擠製成型技術(MEX)列印 3D 物件，示意圖當中的變化，應是使用者進行了 何種參數設定的調整？\n\n![示意圖](images/3d/exam2_q22.png)",
    "question": "以材料擠製成型技術(MEX)列印 3D 物件，示意圖當中的變化，應是使用者進行了 何種參數設定的調整？\n\n![示意圖](images/3d/exam2_q22.png)",
    "options": [
      "提高支撐密度",
      "提高填充密度",
      "更換填充樣式",
      "更換木筏樣式"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】MEX / FFF 切層內部填充密度 (Infill Density) 幾何特徵判讀\n### 【正確答案說明】\n在材料擠製成型（MEX / FFF）切層示意圖中，觀察模型內部由稀疏的網格線條變為密集緊湊的交叉網格線條，這明確代表使用者調高了「**內部填充密度（Infill Density）**」參數（例如由 15% 增加至 40%）。\n提高填充密度會使零件內部晶格單元尺寸縮小、晶胞壁密度增加，進而增強模型整體的結構剛性與承重能力。\n### 【選項辨析】\n- **(A) 提高支撐密度**：支撐是生長在模型外部懸空處之輔助結構，非模型本體內部網格。\n- **(B) 提高填充密度 (Infill Density)**：正確。內部網格密度顯著增加。\n- **(C) 更換填充樣式**：示意圖中網格拓撲形態未改變，僅網格間距縮小。\n- **(D) 更換木筏 (Raft) 樣式**：木筏為底層打印之墊板，與模型內部切層無關。",
    "id": 72,
