    "assessmentContent": "歷屆",
    "num": 23,
    "stem": "以熔融擠製成型技術(FFF)列印相同模型的條件下，關於層厚的參數調整描述，下 列何者正確？",
    "question": "以熔融擠製成型技術(FFF)列印相同模型的條件下，關於層厚的參數調整描述，下 列何者正確？",
    "options": [
      "層厚越大，支撐結構越密",
      "層厚越小，支撐結構越密",
      "層厚越大，模型表面越細緻",
      "層厚越小，模型表面越細緻"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】切層厚度 (Layer Height) 對 FFF 階梯效應與表面細緻度之影響\n### 【正確答案說明】\n積層製造是利用離散的二維層面堆疊近似三維實體連續曲面，因此在傾斜或彎曲表面必然會產生階梯狀的微觀邊緣，稱為「**階梯效應（Staircase Effect）**」。\n階梯效應的高度直接等於設定的「切層厚度（Layer Thickness）」：\n- **層厚越小**（例如 0.08 mm 或 0.1 mm）：垂直方向的階梯高度越微小，模型傾斜表面越平順連續，宏觀視覺與觸覺上的「模型表面越細緻光潔」；\n- **層厚越大**（例如 0.3 mm 或 0.4 mm）：階梯效應粗糙明顯，表面呈現明顯的紋路感。\n故 (D) 選項敘述正確。\n### 【選項辨析】\n- **(A) 層厚越大，支撐結構越密**：錯誤。支撐密度由切層軟體獨立參數設定，與層厚無正比必然關係。\n- **(B) 層厚越小，支撐結構越密**：錯誤。同上，支撐密度為獨立設定項。\n- **(C) 層厚越大，模型表面越細緻**：錯誤。層厚愈大階梯紋路愈粗糙。\n- **(D) 層厚越小，模型表面越細緻**：正確。小層厚大幅削弱階梯效應，表面光潔度最高。",
