    "assessmentContent": "歷屆",
    "num": 25,
    "stem": "下照式(Bottom-Up)的光聚合固化成型技術(VPP)列印一個 30mm×30mm×10mm 的方體 模型，於相同支撐參數的條件下，下列何種擺放方式，列印時模型與支撐分離的機 率較高？",
    "question": "下照式(Bottom-Up)的光聚合固化成型技術(VPP)列印一個 30mm×30mm×10mm 的方體 模型，於相同支撐參數的條件下，下列何種擺放方式，列印時模型與支撐分離的機 率較高？",
    "options": [
      "![選項A](images/3d/exam2_q25_a.png)",
      "![選項B](images/3d/exam2_q25_b.png)",
      "![選項C](images/3d/exam2_q25_c.png)",
      "![選項D](images/3d/exam2_q25_d.png)"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】下照式 VPP 幾何截面積對離型拉拔力與支撐拉斷風險之影響\n### 【正確答案說明】\n在下照式（Bottom-Up）光固化中，列印長寬高為 $30\\times 30\\times 10\\text{ mm}$ 的長方體：\n- 若以 **$30\\times 30\\text{ mm}$ 的大底面水平平行於樹脂槽底擺放**：單層橫截面面積高達 $900\\text{ mm}^2$。成型板向上抬升時，大面積的固化平層與槽底離型膜之間會產生極其巨大的瞬間真空負壓與液體黏滯阻力（拉拔力 Peeling Force 達到峰值）。此巨大拉拔力會遠遠超過細小支撐柱的抗拉極限，導致支撐頭部被連根拔斷，模型脫離支撐掉入槽底；\n- 相對地，若將模型傾斜 30°~45° 擺放，每層橫截面僅為細窄長條狀，拉拔力可降低 80% 以上，支撐完好無損。\n故擺放方式中以大截面水平橫置（如選項 B 所示之平放方式）與支撐分離的失敗機率最高。\n### 【選項辨析】\n- **(A) 傾斜空間立體擺放**：單層截面積小，拉拔力分散平緩，支撐不易斷裂。\n- **(B) 大平面完全平行於平台水平橫放**：正確。單層瞬態截面積最大（$900\\text{ mm}^2$），拉拔力峰值極大，模型最易與支撐分離失敗。\n- **(C) 小截面豎直擺放 (10x30mm 截面)**：截面積僅 $300\\text{ mm}^2$，拉拔力顯著小於大平放。\n- **(D) 適當角度斜置並加粗主支撐**：支撐受力均勻，列印成功率高。",
