    "stem": "熔融擠製成型技術(FFF)中，下列何種列印參數會增加材料的使用量？",
    "question": "熔融擠製成型技術(FFF)中，下列何種列印參數會增加材料的使用量？",
    "options": [
      "提高列印速度",
      "降低切層厚度",
      "提高填充密度",
      "降低外壁厚度"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】FFF 列印參數對材料總消耗量之影響機制\n### 【正確答案說明】\n在 FFF 3D 列印中，模型消耗的線材總量（以公克或米計）直接取決於列印路徑所佔據的「實體塑料體積」：\n- **提高填充密度（Infill Density）**：內部實體晶格由疏變密，單位體積內填充的熔絲重量成正比急劇增加，直接大幅「增加材料的使用量」。\n- **提高列印速度**：僅改變噴頭平移快慢，不改變零件實體體積與材料用量。\n- **降低切層厚度**：僅增加 Z 軸分層細緻度，零件內部與外部實體體積基本守恆，不顯著增加材料用量。\n- **降低外壁厚度**：外殼圈數減少，反而會「減少」材料使用量。\n故 (C) 選項正確。\n### 【選項辨析】\n- **(A) 提高列印速度**：僅縮短工時，單位模型所用材料總量不變。\n- **(B) 降低切層厚度**：改善表面細緻度，對實體塑料總質量無實質增量影響。\n- **(C) 提高填充密度**：正確。內部實心度提高，材料消耗量成正比顯著增加。\n- **(D) 降低外壁厚度**：外殼圈數減少，材料使用量反而減少。",
