    "num": 27,
    "stem": "在熔融擠製成型技術(FFF)的列印過程中，模型底部發生如圖所示之翹曲現象。關 於此類成型之缺陷，下列何者並非可能造成的原因？\n\n![翹曲示意圖](images/3d/exam2_q27.png)",
    "question": "在熔融擠製成型技術(FFF)的列印過程中，模型底部發生如圖所示之翹曲現象。關 於此類成型之缺陷，下列何者並非可能造成的原因？\n\n![翹曲示意圖](images/3d/exam2_q27.png)",
    "options": [
      "平台黏著劑塗抹不平均",
      "內部填充密度過高",
      "列印腔體溫度過高",
      "工作平台溫度過低"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】FFF 底層翹曲 (Warping) 物理成因分析與環境溫控\n### 【正確答案說明】\nFFF 模型底層翹曲的核心物理機制是「高分子熱收縮應力」克服了「底板黏著附著力」：\n1. **工作平台溫度過低**：塑料熔體接觸底板瞬間急速冷卻收縮，底層黏性不足引發翹曲。\n2. **平台黏著劑塗抹不均勻**：局部附著力弱的地方最先被收縮應力拉脫。\n3. **內部填充率過高**：冷卻收縮的材料體積大，累積的內應力拉力巨大。\n4. **「列印腔體溫度過高」**：提高腔體/環境溫度能將塑料維持在玻璃轉移溫度附近，使高分子鏈能進行應力鬆弛與退火，大幅減緩冷卻溫差與收縮應力，這正是「抑制與消除翹曲」的有效手段，絕非「造成翹曲的原因」。故 (C) 並非可能造成翹曲的原因。\n### 【選項辨析】\n- **(A) 平台黏著劑塗抹不平均**：可能原因。附著薄弱處易被應力扯起。\n- **(B) 內部填充密度過高**：可能原因。填充高意味著材料體積大，累積收縮拉扯力大。\n- **(C) 列印腔體溫度過高**：非翹曲原因（本題正解）。高腔溫有助於退火消除熱應力，能有效防範翹曲。\n- **(D) 工作平台溫度過低**：可能原因。底層急冷收縮且失去黏著力，極易翹曲。",
