    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】熱塑性聚氨酯 (TPU) 彈性體流變學特性與列印速度限制\n### 【正確答案說明】\n熱塑性聚氨酯（TPU）屬於熱塑性彈性體（TPE）：\n- 其高分子結構中含有軟段與硬段嵌段共聚物，在常溫下具有高彈性、極佳耐磨性與優異韌性；\n- 其物理特性為「**線材本體極為柔軟且具高度彈性屈服形變**」。當進料齒輪向噴頭喉管推擠線材時，噴嘴微孔內部具有天然熔融背壓阻力。若列印速度偏快，高進料推力會使柔軟的 TPU 線材像受壓彈簧般在進料輪與喉管入口間隙處發生彈性彎曲、側向起拱爆出，造成嚴重卡料與供料中斷。\n因此列印 TPU 時必須「大幅調降列印速度（通常設為 15-25 mm/s）」，降低擠出阻力以適應其「線材較軟」的物理特性。\n### 【選項辨析】\n- **(A) 熔點較高**：錯誤。TPU 熔融溫度約 200-220°C，屬中等加工溫度，非特高熔點。\n- **(B) 線材較軟**：正確。柔軟高彈性線材受壓易屈曲變形卡死，必須降低列印速度與擠出背壓。\n- **(C) 收縮較大**：錯誤。TPU 熱收縮率遠低於 ABS，收縮非降速主要原因。\n- **(D) 黏度較低**：錯誤。TPU 熔體黏度通常偏高且具強剪切變稀特性。",
    "id": 78,
    "display_num": 28,
    "source_id": "3d-3f916a89e907031a",
    "source_version": "official-through-115-05",
    "question_uid": "3d-4834bf9e9d51435712ac9b7c",
    "content_hash": "c147828b804ab8e1395df3201f43de3fbc3630fa6ede84a564c3afee416be535"
