    "num": 29,
    "stem": "關於熱塑性彈性體(TPE)線材在熔融擠製成型技術(FFF)的使用，下列敘述何者正 確？",
    "question": "關於熱塑性彈性體(TPE)線材在熔融擠製成型技術(FFF)的使用，下列敘述何者正 確？",
    "options": [
      "其列印速度通常高於 PLA 線材",
      "適合採用遠端送料機構進行列印",
      "可以應用於列印客製化彈性鞋墊",
      "可以運用丙酮蒸氣進行表面處理"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】熱塑性彈性體 (TPE) 特性與客製化鞋墊功能應用\n### 【正確答案說明】\n熱塑性彈性體（TPE / TPU）兼具橡膠的高回彈性與熱塑性塑料的熔融加工性，具備優異的減震性、耐疲勞性與生物相容性：\n- 廣泛應用於醫學與運動領域製作「**客製化彈性機能鞋墊**」、義肢減震襯墊及柔性穿戴護具。\n- TPE 軟料在遠端送料管中極易彎折，適合採用「近端進料」而非遠端進料；其列印速度通常低於 PLA；丙酮蒸氣燻蒸僅對 ABS 有效，對耐化學溶劑的 TPE 完全無效。故 (C) 選項正確。\n### 【選項辨析】\n- **(A) 其列印速度通常高於 PLA 線材**：錯誤。軟料出料阻力大，列印速度遠低於 PLA。\n- **(B) 適合採用遠端送料機構進行列印**：錯誤。遠端長管易卡料，必須採用近端進料機構。\n- **(C) 可以應用於列印客製化彈性鞋墊**：正確。優異之彈性減震與足弓仿生支撐應用。\n- **(D) 可以運用丙酮蒸氣進行表面處理**：錯誤。丙酮無法溶解 TPE，此為 ABS 專用化學平滑法。",
    "id": 79,
