    "assessmentContent": "歷屆",
    "num": 31,
    "stem": "如圖為有軸孔配合的一組配合件模型，若使用下照式(Bottom-Up)面投影光聚合固 化成型技術(VPP)列印，下列四種列印方向的組合，何者配合精度較佳？\n\n![配合件模型示意圖](images/3d/exam2_q31_stem.png)",
    "question": "如圖為有軸孔配合的一組配合件模型，若使用下照式(Bottom-Up)面投影光聚合固 化成型技術(VPP)列印，下列四種列印方向的組合，何者配合精度較佳？\n\n![配合件模型示意圖](images/3d/exam2_q31_stem.png)",
    "options": [
      "![選項A](images/3d/exam2_q31_a.png)",
      "![選項B](images/3d/exam2_q31_b.png)",
      "![選項C](images/3d/exam2_q31_c.png)",
      "![選項D](images/3d/exam2_q31_d.png)"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】軸孔配合公差與光固化面曝光 (XY 像素) 尺寸精度方向性\n### 【正確答案說明】\n在面投影光聚合固化（VPP / DLP / LCD）中：\n- 水平 XY 平面的解析度由高密度光學像素（Pixel pitch，約 25-50 微米）精確決定，在 XY 平面繪製圓形截面時，圓周由微鏡陣列精準成像，孔徑與軸徑的「真圓度（Circularity）與尺寸幾何公差」極為優異；\n- 垂直 Z 軸方向則受到切層厚度（Layer height）離散分層與階梯效應影響，且受到成型板向上拉拔力的微觀拉伸應變干擾，因此垂直軸向圓孔容易發生孔頂下垂失圓或階梯摩擦干涉。\n對於有嚴格同軸度與滑動配合要求的軸孔配合件模型，將圓軸與圓孔的「配合柱面截面放置於 XY 投影平面上列印」（即軸心垂直於成型板，截面平行於 XY 面，如組合 B 所示），能獲得最佳真圓度與嚴密配合公差。\n### 【選項辨析】\n- **(A) 組合 A**：若孔軸橫臥，切層階梯效應會破壞真圓度導致卡死或配合鬆動。\n- **(B) 組合 B**：正確。圓柱與配合孔皆在 XY 投影平面成型，真圓度最高，配合公差最精確。\n- **(C) 組合 C**：軸孔打印方位不匹配，收縮與階梯方向各異導致裝配干涉。\n- **(D) 組合 D**：大角度傾斜切層會產生橢圓階梯，孔軸配合精度不良。",
    "id": 81,
    "display_num": 31,
    "source_id": "3d-3f916a89e907031a",
    "source_version": "official-through-115-05",
