    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】金字塔尖端過熱熔塌之冷卻風扇參數調控\n### 【正確答案說明】\n如題圖所示，金字塔模型頂部出現紅圈處的軟化、熔塌與輪廓模糊缺陷，是極其典型的「尖端冷卻不足導致熱量堆積（Overheating）」：\n- 在金字塔底部截面較大時，噴頭每層繞行時間長，底層有充足時間冷卻固化；但越接近金字塔頂部，截面面積急劇縮小，噴頭高溫熱端持續在微小尖端盤旋，累積大量熱能無法散失。\n- 最直接有效的硬體與工藝改善對策是「**開啟並提高模型散熱風扇（Part Cooling Fan）轉速**」，強制導入外界冷空氣進行對流冷卻，使沉積出的熔絲瞬間降溫至玻璃轉移溫度以下迅速定型固化。\n### 【選項辨析】\n- **(A) 開啟物件風扇 (Part Cooling Fan)**：正確。強化尖端強制對流風冷，使每層塑料快速凝固定型。\n- **(B) 降低切層厚度**：增加層數反而延長噴頭在頂部加熱時間，無法改善熱堆積。\n- **(C) 提高列印溫度**：嚴重惡化缺陷。過高溫度會使尖端融化得更加嚴重。\n- **(D) 增加回抽距離**：回抽僅防牽絲，對連續小截面的局部過熱熔塌毫無幫助。",
    "id": 82,
    "display_num": 32,
    "source_id": "3d-3f916a89e907031a",
