    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】PLA 模型後處理支撐拆除與機械修整工具規範\n### 【正確答案說明】\n在 FFF 列印完成後，PLA 零件的後處理標準流程為：\n1. **冷卻取件**：必須等待加熱熱床自然完全冷卻至室溫（底板收縮脫膠），方可輕鬆取下模型；若趁熱強行掰下，底層尚處於軟化態極易造成模型底部拉伸永久變形。\n2. **拆除支撐結構**：手動或輔以斜口鉗（Flush Cutters）、尖嘴鉗、美工刀等工具小心剪除拆除支撐結構。\n3. **表面精修**：以細砂紙（400-1500目）沾水濕磨修平支撐殘留凸點。\n線切割（W-EDM）專用於導電金屬加工，絕緣的 PLA 無法進行線切割；滲銅法為金屬粉末燒結後處理技術，與塑料無關。故 (B) 選項正確。\n### 【選項辨析】\n- **(A) 趁熱床完全冷卻之前趁早拆下**：錯誤。高溫下模型底部柔軟，強拔必變形損壞。\n- **(B) 拆除支撐時，可以使用斜口鉗等手工具輔助**：正確。斜口鉗能精確剪斷支撐與本體連接頸部。\n- **(C) 可透過線切割機 (W-EDM) 修整表面**：錯誤。線切割要求材料必須導電，塑料絕緣體無法加工。\n- **(D) 處理模型後，可使用滲銅法提升強度**：錯誤。滲銅法為粉末冶金/金屬 BJT 專用高溫工藝。",
