    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】VPP 切層厚度倍增時曝光時間 (Exposure Time) 補償調控\n### 【正確答案說明】\n在光聚合固化（VPP）中，根據 Beer-Lambert 光吸收定律，紫外光強度隨著穿透樹脂液層深度增加而呈指數衰減。\n當為了提升列印效率，將切層厚度由 $0.05\\text{ mm}$ 放大為 $0.10\\text{ mm}$（單層厚度增加一倍）時：\n- 紫外光必須穿透更深的樹脂厚度，且必須穿透深入到上一已固化層表面以達成牢固的「層間分子鏈化學交聯」；\n- 若維持原曝光時間不變，底層深處接收到的光子能量將低於樹脂臨界固化曝光量 $E_c$，導致層與層之間無法黏結，列印中途發生嚴重的「層間剝離分離（Delamination）」；\n- 因此，層厚增加時，最必要且關鍵的參數調整是「**增加單層曝光時間（Exposure Time）**」，以提供足夠的能量密度達成更深的透光硬化深度。\n### 【選項辨析】\n- **(A) 增加單層曝光時間 (Exposure Time)**：正確。確保光子穿透更厚的樹脂層並達成足夠層間交聯深度。\n- **(B) 降低單層曝光時間**：嚴重錯誤。會導致光固化深度不足而層間剝離脫層。\n- **(C) 提高樹脂槽冷卻速度**：降溫增加黏度不利於固化深度控制。\n- **(D) 大幅提高成型平台拉拔速度**：層厚大時樹脂流動更需時間，提速易造成拉斷。",
    "id": 84,
    "display_num": 34,
    "source_id": "3d-3f916a89e907031a",
