    "assessmentContent": "歷屆",
    "num": 35,
    "stem": "熔融擠製成型技術(FFF)中，為了改善層間分離的狀況，應降低下列哪一項的參數 設定？",
    "question": "熔融擠製成型技術(FFF)中，為了改善層間分離的狀況，應降低下列哪一項的參數 設定？",
    "options": [
      "熱床溫度",
      "腔體溫度",
      "擠出流量",
      "列印速度"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】FFF 層間剝離 (Delamination / Cracking) 熔接熱能與風扇控制\n### 【正確答案說明】\n在 FFF 列印中，「層間分離 / 開裂（Layer Delamination）」是指模型相鄰兩層塑料在 Z 軸方向無法良好黏合，在外力下沿分層介面斷裂剝離。\n其根本物理原因是：新沉積的高溫熔絲未能及時向前一層上表面傳遞足夠熱量以重熔介面高分子鏈。若「模型冷卻風扇（Part Cooling Fan）轉速過高或風量過大」，強冷風會將剛擠出的熔體表面瞬間急冷吹結皮，嚴重阻礙界面分子熱擴散與鏈纏結，造成層間結合強度微弱。\n因此，為改善層間分離，應「**降低冷卻風扇轉速（Fan Speed）**」，保留足夠熱量促進層間熔接；同時亦可適度調低列印速度以增加受熱接觸時間。故 (D) 選項正確。\n### 【選項辨析】\n- **(A) 提高冷卻風扇轉速**：錯誤。強風急速降溫會徹底破壞層間熱熔接，加劇層間開裂。\n- **(B) 降低噴頭加熱溫度**：錯誤。降低溫度使熔體更冷，層間更難熔合。\n- **(C) 提高列印移動速度**：錯誤。高速出料使層間傳熱時間不足，削弱結合力。\n- **(D) 降低冷卻風扇轉速 (或降低列印速度)**：正確。減慢吹風冷卻速率，提供充裕熱能促成層間分子鏈高溫交聯熔合。",
