    "assessmentContent": "歷屆",
    "num": 36,
    "stem": "以光聚合固化成型技術(VPP)製作模型，關於降低切層厚度對模型造成之影響，下 列敘述何者有誤？",
    "question": "以光聚合固化成型技術(VPP)製作模型，關於降低切層厚度對模型造成之影響，下 列敘述何者有誤？",
    "options": [
      "總列印時間越長",
      "列印成品精度越高",
      "每層曝光時間越長",
      "列印的側面愈平滑"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】VPP 降低切層厚度之光化學與外觀綜合效應辨析\n### 【正確答案說明】\n在光固化成型技術（VPP）中，將切層厚度由大調小（例如由 0.05 mm 降至 0.025 mm）：\n- 垂直 Z 軸方向的階梯微觀台階高度減半，表面平滑度大幅提高；\n- 在總高度相同下，總層數成倍增加，總列印時間必然顯著延長；\n- 在光化學曝光設定上，因為每層樹脂厚度變薄，光線穿透所需深度變淺，切層軟體通常應「適度縮短單層曝光時間」，若維持過長曝光時間反而會造成過固化（Over-curing）使得微細特徵膨脹模糊。若稱「降低切層厚度會使階梯效應加劇」，顯屬完全顛倒之錯誤結論。故 (C) 選項有誤。\n### 【選項辨析】\n- **(A) 增加模型列印所需之總切層層數**：正確。高度除以層厚等於層數。\n- **(B) 延長整體列印完成所需之時間**：正確。層數倍增意味著曝光與機械升降次數倍增。\n- **(C) 會顯著加劇模型表面的階梯紋路效應**：錯誤（本題正解）。層厚越小階梯紋越不明顯，表面越細膩平滑。\n- **(D) 有助於提升模型垂直傾斜曲面之精細度**：正確。細分層大幅提高幾何逼真度。",
    "id": 86,
