    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】光敏樹脂流體流變學與溫度-黏度特性\n### 【正確答案說明】\n液態光聚合固化樹脂屬於典型的感溫型非牛頓流體：\n- 其黏度隨著液體溫度的升高而呈顯著的指數下降。常溫低溫時（如 15°C~20°C）樹脂黏度極大、流動遲緩，在下照式抬升回流時無法迅速均勻填平槽底，極易造成缺料空洞；\n- 若在設備中「**對樹脂槽進行加熱（如升溫至 25°C~35°C）**」，高分子鏈熱運動加劇，樹脂黏度會大幅降低，流動潤濕性顯著改善，能迅速流平填補微小間隙並加速氣泡排出，大幅提高列印可靠性與速度。\n### 【選項辨析】\n- **(A) 對樹脂進行適度加熱升溫**：正確。熱運動降低高分子內摩擦力，顯著降低樹脂流動黏度。\n- **(B) 降低樹脂槽的工作溫度**：錯誤。降溫會使樹脂黏度大幅上升變得稠厚。\n- **(C) 增加單體在陽光下的暴露時間**：錯誤。陽光含紫外光會直接引發預固化凝膠化，使液體報廢。\n- **(D) 加入高黏度增稠劑**：錯誤。增稠劑會使黏度成倍提高。",
