    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】VPP 紫外二次固化箱 (UV Curing Chamber) 強化機理\n### 【正確答案說明】\n光固化成型結束後的工件表面黏附未硬化液體，且內部尚有大量未完全配對反應的雙鍵基團：\n- 經過酒精清洗乾淨並充分乾燥後，將模型置入專用紫外光固化箱中，接受高強度紫外光（通常配以 40°C~60°C 溫控加熱）照射數分鐘至數十分鐘；\n- 紫外線光子深入穿透高分子結構內部，激發殘留之光起始劑與游離雙鍵，引發充分的「**二次後固化交聯反應（Secondary Crosslinking）**」，使聚合物網絡三維交聯度達到最大化；\n- 此後處理步驟能顯著提升零件的**抗拉強度、洛氏硬度、耐磨性、抗蠕變性與耐化學腐蝕耐久性**。\n### 【選項辨析】\n- **(A) 使用超音波酒精長時間浸泡數天**：錯誤。長時間浸泡會使樹脂溶脹開裂脆化。\n- **(B) 進行紫外線二次曝光後固化處理 (UV Post-Curing)**：正確。大幅提升樹脂交聯密度，顯著增強耐久度與剛性。\n- **(C) 放入冷水浴中快速淬火**：錯誤。無任何強化化學交聯之作用。\n- **(D) 塗佈丙酮溶劑進行表面溶解**：錯誤。丙酮無法溶解固化交聯樹脂，甚至可能造成表面白化微裂。",
