    "explanation": "### 【核心考點】特種工程塑料聚醚醚酮 (PEEK) 高溫熱加工性能\n### 【正確答案說明】\n聚醚醚酮（PEEK）是金字塔頂端的半結晶特種芳香族工程塑料：\n- 具有極高的熔點（$T_m \\approx 343^\\circ\\text{C}$）與極佳的耐高溫熱變形溫度（長期工作溫度可達 250°C~260°C 以上）；\n- 其機械強度、抗拉剛性、耐疲勞性與抗化學腐蝕能力接近甚至超越部分金屬鋁合金，廣泛應用於航太無人機高載荷結構件與人體植入骨骼醫療器械；\n- 在 FFF 列印時，為確保 PEEK 線材完全熔融塑化並在層間形成強固結晶熔接，**噴頭列印溫度必須達到 360°C 至 420°C**，熱床需 120-150°C，且必須在 70-100°C 的高溫恆溫腔體中成型。\n在所有商用 FFF 線材中，PEEK 所需列印溫度最高。\n### 【選項辨析】\n- **(A) 聚乳酸 (PLA)**：加工溫度僅 190-220°C，耐溫僅 55°C，強度與耐溫低。\n- **(B) 丙烯腈-丁二烯-苯乙烯 (ABS)**：加工溫度約 230-250°C，耐溫約 85-95°C。\n- **(C) 聚對苯二甲酸乙二酯 (PETG)**：加工溫度約 220-250°C，耐溫約 70-80°C。\n- **(D) 聚醚醚酮 (PEEK)**：正確。熔點高達 343°C，需近 400°C 擠出高溫，強度與耐溫性能極佳。",
