    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】薄壁無蓋容器 FFF 擺放方位與免支撐工藝設計\n### 【正確答案說明】\n使用 FFF 列印題圖所示之「矩形無蓋深容器（薄壁中空盒狀結構）」：\n- **若採「開口朝上（容器底面平貼成型平台）」擺放**：\n  1. 容器底部的整個大平面牢牢附著於熱床上，接觸面積大，列印穩定性極高；\n  2. 容器四面垂直外壁自底板筆直向上生長，均屬於完全垂直無傾角的壁面（懸臂角為 0°），「內部與外部完全不需添加任何支撐結構」；\n  3. 打印路徑連續單純，耗材最省、工時最短，成型成功率與加工效率達到最高。\n- 若開口朝下，懸空的封頂天花板需要龐大的內部支撐承托；若側向橫臥，側壁懸空需大量支撐且圓角失真。故 (A) 選項為最佳擺放方式。\n### 【選項辨析】\n- **(A) 開口朝上**：最佳方式。底面平貼平台，四壁垂直生長，完全無需內部支撐，效率與成功率最高。\n- **(B) 開口朝側 (如朝左橫臥)**：側壁懸空需要大量內部支撐填充，浪費耗材且表面粗糙。\n- **(C) 開口朝下**：頂部底板在空中懸空，內部需填滿密密麻麻的支撐，極難拆除。\n- **(D) 開口朝斜上**：懸空面與投影均需建立複雜支撐，表面精度與耗時皆劣於直立。",
    "id": 92,
    "display_num": 42,
