    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】大型實心模型 FFF 填充率激增之後果與尺寸收縮應力分析\n### 【正確答案說明】\n列印大型立方骰子模型，將填充率由 20% 劇烈提高至 80%：\n- **增加列印時間**：填充路徑大幅暴增，噴頭需來回走訪更多內部軌跡，工時顯著延長；\n- **增加模型重量**：實體內部塑料質量倍增；\n- **提高封頂品質**：密集的內部網格為頂部實心層提供了極佳的平整支撐，避免頂部塌陷。\n然而，高達 80% 的高密度填充意味著模型內部積蓄了大量的塑料熔體，在冷卻硬化過程中會產生巨大的「整體體積熱收縮與內部冷卻應力」，導致模型產生顯著的整體尺寸收縮、邊緣向內凹陷變形，甚至誘發底角翹曲拉脫，因此「絕不會提高尺寸精度，反而容易造成尺寸超差縮小」。故 (C) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 會顯著增加整體列印所需工時**：正確。內部走線量倍增，列印時間大幅延長。\n- **(B) 會增加模型成品的實體重量與耗材成本**：正確。塑料用量成倍增加。\n- **(C) 可顯著提高模型之宏觀幾何尺寸精度**：錯誤（本題正解）。高收縮內應力易導致外壁內凹與尺寸收縮超差。\n- **(D) 可提高頂面封頂層之支撐品質以防塌陷**：正確。密集填充為頂層提供了平整基底。",
    "id": 94,
    "display_num": 44,
