    "explanation": "### 【核心考點】下照式 DLP 光固化成型幾何尺寸決定因素辨析\n### 【正確答案說明】\n在下照式 DLP 光固化中：\n- 增加曝光秒數：提升自由基轉化率，增強層與層之間的共價鍵結合力；\n- 提高成型板上升速度：增強液體黏滯阻力與負壓吸力，使瞬間離型拉拔力顯著增加；\n- 減少延遲曝光時間（Light-off Delay）：每層升降後縮短液面靜置等待秒數，可縮短列印總時長。\n而「切層厚度（Layer Thickness）」控制的是垂直 Z 軸方向的每層抬升分層高度：\n降低切層厚度只會增加 Z 軸的總切層數並提高垂直平滑度，模型在水平 XY 平面的「幾何外輪廓尺寸」是由投影的像素遮罩圖像大小嚴格決定的，微觀外輪廓「絕不會因為切層厚度降低而縮小」。故 (D) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 增加曝光秒數，可提高層間結合力**：正確。加深光固化穿透度使層間牢固交聯。\n- **(B) 提高成型板上升速度，拉拔力會增加**：正確。黏性流體動態剝離阻力隨拉拔速度劇增。\n- **(C) 減少延遲曝光時間，可縮短列印總時間**：正確。縮短液面靜置等待時長。\n- **(D) 降低切層厚度，模型水平外輪廓尺寸會顯著縮小**：錯誤（本題正解）。切層厚度僅作用於 Z 軸，XY 輪廓尺寸由投影圖檔決定。",
