    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】FFF 噴嘴牽絲 (Stringing) 機理與材料熔融黏度-溫度關係\n### 【正確答案說明】\n牽絲測試模型由兩個獨立柱體組成，噴頭在兩柱之間進行空行程移動時，若出現大量橫向毛邊拉絲，即為「牽絲（Stringing）缺陷」：\n- 高分子材料的熔體剪切黏度對溫度極為敏感，遵循阿瑞尼士（Arrhenius）流變關係；\n- **當列印溫度設定愈高**，塑料在熱端內的分子熱運動愈劇烈，熔融黏度急劇下降、流動性倍增如稀液。在空移移動中，高流動性的熔體極易在重力與殘留腔壓下自噴嘴尖端流涎滲出，隨噴頭移動被拉伸成微細塑料絲，因此「**列印溫度越高時，越容易發生嚴重的牽絲狀況**」。\n降低溫度、提高回抽距離與回抽速度則是抑止牽絲的有效手段。故 (A) 選項敘述正確。\n### 【選項辨析】\n- **(A) 列印溫度越高時，越容易發生牽絲的狀況**：正確。熔體黏度大幅降低，流動性過強極易流涎拉絲。\n- **(B) 列印速度越快時，越容易發生牽絲**：錯誤。空行程速度越快，流涎在空中的滴漏時間越短，反而減輕牽絲。\n- **(C) 回抽距離越長時，越容易發生牽絲**：錯誤。回抽距離增加能將熔體吸入噴嘴內，有效防止牽絲。\n- **(D) 回抽速度越快時，越容易發生牽絲**：錯誤。快速回抽能瞬間切斷熔絲釋放壓力，抑制牽絲。",
    "id": 97,
    "display_num": 47,
