    "assessmentTopic": "歷屆",
    "assessmentContent": "歷屆",
    "num": 48,
    "stem": "以光聚合固化成型技術(VPP)製作的模型，若要使其外觀光滑，關於其後處理的方 式，下列何者有誤？",
    "question": "以光聚合固化成型技術(VPP)製作的模型，若要使其外觀光滑，關於其後處理的方 式，下列何者有誤？",
    "options": [
      "使用細沙紙沾水打磨",
      "使用丙酮蒸氣做平滑處理",
      "使用環氧樹脂塗佈",
      "使用補土填縫打磨再噴塗處理"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】光固化熱固性樹脂 vs 熱塑性塑料之化學後處理相容性\n### 【正確答案說明】\n光聚合固化成型技術（VPP）成型的模型是由丙烯酸酯或環氧體系經光引發交聯聚合形成的三維立體網絡結構，屬於「**不可逆的熱固性高分子（Thermosetting Polymer）**」：\n- 熱固性聚合物在完全固化後，耐化學溶劑性能極強，在常溫溶劑中只會微溶脹，絕不會被溶劑均勻溶解重新液化；\n- 「**丙酮蒸氣燻蒸平滑法（Acetone Vapor Smoothing）**」是利用丙酮能劇烈溶解熱塑性塑膠 **ABS** 表面的物理特性，使 ABS 表層塑料再流動融合撫平階梯層紋；\n- 若將光固化樹脂置入丙酮蒸氣中，丙酮根本無法溶解高度交聯的熱固性樹脂表面，反而會使材料內部產生微裂紋、表面泛白起泡甚至嚴重脆化損壞。故 (B) 選項為嚴重錯誤之後處理方式。\n### 【選項辨析】\n- **(A) 使用細砂紙沾水打磨 (濕磨)**：正確。濕磨能抑制粉塵並均勻修平微小支撐殘點與台階紋。\n- **(B) 使用丙酮蒸氣做化學平滑處理**：錯誤（本題正解）。丙酮燻蒸僅適用於熱塑性 ABS，對熱固性光敏樹脂完全無效且具破壞性。\n- **(C) 使用環氧透明樹脂薄薄塗佈覆蓋**：正確。利用透明樹脂表面張力自流平填平層紋並增加光澤度。\n- **(D) 使用補土填縫打磨再噴塗底漆面漆**：正確。工業級模型上漆前標準表面整平製程。",
