    "assessmentContent": "歷屆",
    "num": 49,
    "stem": "以熔融擠製成型技術(FFF)機台列印模型，列印時若使用 PLA 材料，應採用下列哪 一個擠出溫度範圍？",
    "question": "以熔融擠製成型技術(FFF)機台列印模型，列印時若使用 PLA 材料，應採用下列哪 一個擠出溫度範圍？",
    "options": [
      "110-140℃",
      "150-180°C",
      "190-220℃",
      "230-260℃"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】聚乳酸 (PLA) 之標準 FFF 擠出加工溫度工藝視窗\n### 【正確答案說明】\n聚乳酸（PLA）是 FFF 最主流的標準耗材：\n- 其玻璃轉移溫度 $T_g \\approx 55-60^\\circ\\text{C}$，熔點約 155-165°C；\n- 在實際 3D 列印中，為使線材在高速通過加熱腔時具備充足的熱傳導效率與優良的熔融剪切流動性，標準的 FFF 擠出列印溫度範圍建議設定在 **190°C 至 220°C**（通常以 200°C~205°C 為最通用黃金溫度）：\n  - 若溫度低於 180°C，塑料未能完全塑化熔融，擠出阻力巨大，進料輪會打滑甚至堵頭；\n  - 若溫度高於 230°C，PLA 易熱裂解焦化，流涎牽絲極度嚴重。\n故 (C) 為最準確的溫度區間。\n### 【選項辨析】\n- **(A) 110-140°C**：過低。PLA 尚未達到熔融黏流態，完全無法擠出。\n- **(B) 150-180°C**：偏低。接近熔點但黏度極大流動不暢，易引發欠擠出或進料喉管卡料。\n- **(C) 190-220°C**：正確。PLA 之標準理想擠出成型加工溫度視窗。\n- **(D) 230-260°C**：過高。為 ABS / PETG 常用加工溫度，PLA 在此高溫下會嚴重降解碳化與流涎。",
