    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】聚乙烯醇 (PVA) 水溶性支撐材料特徵與力學局限\n### 【正確答案說明】\n聚乙烯醇（Polyvinyl Alcohol, PVA）是一種獨特的水溶性合成高分子線材：\n- 核心功能：專門應用於「**多噴頭（雙擠出機）FFF 設備中作為複雜懸空與封閉內腔的專用水溶性支撐材料**」；列印完成後將工件浸泡於普通溫水中數小時，PVA 支撐會完全溶解於水中消失，留下光潔完好的本體模型。\n- 力學局限：PVA 質地脆弱、極度容易吸收大氣中的水分而潮解軟化，且熔融熱穩定性較差，其本身的抗拉剛度與耐久力學強度遠遠低於 PLA、ABS 或 PETG，因此「**絕對不常用於列印結構強度要求較高的本體模型**」。故 (A) 選項「常用於列印強度較高的模型」之敘述為非，符合題意。\n### 【選項辨析】\n- **(A) 常用於列印強度較高的模型**：非其目的（本題正解）。PVA 強度脆弱且易潮解，不用於結構主體。\n- **(B) 常使用於多材料 (雙噴頭) 的設備當中**：正確。主模型材料（如 PLA）與支撐材料（PVA）雙料分工。\n- **(C) 可以清水為溶劑進行無害溶解清除**：正確。具環境友善可溶性，無需化學強酸鹼。\n- **(D) 可用在複雜幾何形狀與封閉內腔模型的支撐**：正確。水可滲入微小孔道將內部支撐完全溶出。",
