    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】積層製造多樣化能量源與成型加工工具分類\n### 【正確答案說明】\n在積層製造（3D 列印）的各類製程中，因所處理的材料物理型態（固態線材、液態樹脂、粉末床、薄片）各異，系統採用的核心成型工具包括：\n- **雷射（Laser）**：應用於 SLA 光固化、SLM/SLS/DMLS 金屬及高分子粉末燒結熔融、LOM 薄片輪廓切割。\n- **加熱器（Heater Block / Bed）**：應用於 FFF/FDM 噴頭熱端熔融塑料與熱床保溫。\n- **噴嘴（Nozzle）與壓電微滴噴頭（Piezoelectric Printhead）**：應用於 FFF 熔絲擠出、MJT 液態微滴噴射及 BJT 黏合劑微滴精準沉積。\n此外電子束熔融（EBM）使用高能電子槍，部分薄片疊層製程使用超音波刀具。因此，雷射、加熱器、各類噴嘴皆為常見之積層製造加工工具，故選 (D) 以上皆是。\n### 【選項辨析】\n- **(A) 雷射**：SLA、PBF、DED、SHL 之關鍵能量工具。\n- **(B) 加熱器**：FFF、SLS 預熱缸之必備熱能工具。\n- **(C) 噴嘴**：FFF 擠出頭、MJT/BJT 壓電微滴陣列。\n- **(D) 以上皆是**：正確。涵蓋了主流 3D 列印系統之核心加工工具。",
