    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】積層製造材料三態（液態、固態、粉末態）分類\n### 【正確答案說明】\n依據國際材料試驗協會（ASTM）與 ISO 標準，積層製造使用的耗材形式主要分為三大物理型態：\n1. **液態類**：以光聚合固化樹脂（丙烯酸酯、環氧樹脂體系）為代表，用於 VPP 及 MJT；\n2. **固態類**：以固態熱塑性高分子線材（PLA、ABS）、薄片材（紙張、塑膠膜、金屬箔）及微鑄造蠟材（Wax）為代表，用於 FFF、SHL、MJT；\n3. **粉末類**：包含金屬粉末（鈦合金、不銹鋼、鈷鉻鉬）、高分子塑料粉末（尼龍 PA11/PA12）、陶瓷粉末及石膏砂模粉末，用於 PBF 及 BJT。\n因此粉末、蠟材、光聚合固化樹脂皆為常見的 3D 列印材料，故選 (D) 以上皆是。\n### 【選項辨析】\n- **(A) 粉末**：PBF 與 BJT 的核心原料形式。\n- **(B) 蠟材**：MJT 鑄造珠寶模具或相變支撐材料。\n- **(C) 光聚合固化樹脂**：VPP 與光固化噴墨之核心感光材料。\n- **(D) 以上皆是**：正確。涵蓋了積層製造三大材料基本形態。",
