    "assessmentTopic": "S11",
    "assessmentContent": "S1101",
    "num": 5,
    "stem": "根據下圖 ， 射出成型與積層製造(AM)的製造成本案例比較 ， 下列述敘何者正確？\n\n![射出成型與積層製造製造成本比較圖](images/3d/sg_s1_c1_q5.png)",
    "question": "根據下圖 ， 射出成型與積層製造(AM)的製造成本案例比較 ， 下列述敘何者正確？\n\n![射出成型與積層製造製造成本比較圖](images/3d/sg_s1_c1_q5.png)",
    "options": [
      "量產射出成型成本較高；",
      "數量越多，積層製造的製造成本相對越低；",
      "射出成型在大量製造時反而沒有優勢；",
      "數量少於 200 件時，積層製造的 製造成本比射出成型低"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】積層製造 (AM) vs 傳統射出成型 (Injection Molding) 之損益平衡點 (Break-even Analysis)\n### 【正確答案說明】\n如題圖「射出成型與積層製造製造成本比較圖」所示：\n1. **射出成型**：前端需要投入高昂的金屬模具開發費用（開模費往往高達數十萬至數百萬元），因此在生產數量極少時，單件分攤模具成本極高；當生產批量極大時，模具費用被大量件數攤平，單件邊際成本極低。\n2. **積層製造 (AM)**：完全無需模具，前期固定成本趨近於零，其單件製造成本（耗材費與電能折舊）基本維持恆定水平線。\n圖中兩條成本曲線的交叉點約在 200 件處：當生產數量小於 200 件時，積層製造的單件總成本明顯低於射出成型；當生產數量超過 200 件時，射出成型才展現出成本優勢。故 (D) 正確。\n### 【選項辨析】\n- **(A) 量產射出成型成本較高**：錯誤。大量生產時射出成型單件成本遠低於 AM。\n- **(B) 數量越多，積層製造的製造成本相對越低**：錯誤。AM 缺乏規模經濟，單件成本曲線基本為水平線。\n- **(C) 射出成型在大量製造時反而沒有優勢**：錯誤。大量生產正是射出成型最具壓倒性成本優勢的領域。\n- **(D) 數量少於 200 件時，積層製造的製造成本比射出成型低**：正確。免開模費用，在小批量生產極具經濟效益。",
