    "assessmentTopic": "S11",
    "assessmentContent": "S1101",
    "num": 6,
    "stem": "近年常運用積層製造技術於醫療上 ， 請問關於技術的應用方式 ， 下列敘述何者 有誤？",
    "question": "近年常運用積層製造技術於醫療上 ， 請問關於技術的應用方式 ， 下列敘述何者 有誤？",
