    "explanation": "### 【核心考點】汽車產業導入積層製造之生產情境與經濟性分析\n### 【正確答案說明】\n汽車產業導入 3D 列印技術的典型情境包括：\n- 超級跑車或極少銷量之奢華高單價車種的客製化專屬零件；\n- 已經停產斷料的經典古董老爺車的備品修復與按需逆向重建；\n- 賽車（如 F1）在風洞實驗室進行空氣動力學測試的比例模型與快速迭代空力套件。\n對於年產量數萬至數百萬輛的「長銷型大眾普及車輛零件（如常規保險桿、內裝門板）」，量產製造絕對是以傳統金屬沖壓、壓鑄或塑膠鋼模射出成型為核心，才能將單件生產成本降至最低。若用 3D 列印生產長銷車常規零件，其生產速度慢且成本過高，完全不符經濟效益。故 (C) 有誤。\n### 【選項辨析】\n- **(A) 用在銷量較少的高單價車種零件**：正確。免開模即可滿足高階超跑客製化需求。\n- **(B) 用在斷貨的古董車維修零件**：正確。數位庫存按需列印解決絕版備品斷料痛點。\n- **(C) 用在長銷型車輛的零件常規批量生產**：有誤（本題正解）。大量量產以傳統模具開模生產降低成本為主。\n- **(D) 用在賽車的風洞試驗模型**：正確。快速試驗不同擾流板外形以迅速迭代。",
