    "explanation": "### 【核心考點】航太製造導入 3D 列印之核心驅動因素與局限\n### 【正確答案說明】\n航太與國防工業是推動金屬積層製造進步的最主要推手，其核心驅動價值為：\n1. **結構最佳化與材料輕量化**：航太器重量每減輕一公斤，終身節省的航空燃油或火箭酬載推力價值極高，AM 能成型複雜的拓撲點陣晶格結構；\n2. **組件高度整合**：將數十個次零件焊接總成直接列印為單一整體構件，消除裝配誤差與焊縫疲勞隱患；\n3. **少量多樣化**：航太發動機與飛機結構件製造批量通常為數十至數百件，極契合 AM 特性。\n積層製造生產速度緩慢、設備折舊高，無法勝任「產品大規模量產化（Mass Production）」任務，大量生產並非航太導入 AM 的目的。故 (C) 有誤。\n### 【選項辨析】\n- **(A) 少量多樣化**：符合航太特性。單批次數量少、規格迭代快。\n- **(B) 結構最佳化**：符合航太特性。內部隨形中空與仿生晶格。\n- **(C) 產品量產化**：非 AM 優勢（本題正解）。AM 生產週期長，不適於百萬件規模量產。\n- **(D) 材料輕量化**：符合航太特性。直接降低起飛全重與油耗。",
