    "num": 9,
    "stem": "粉末床熔融成型技術 (PBF) 與指向性沈積成型技術 (DED) 列印金屬件，下列敘 述何者有誤？",
    "question": "粉末床熔融成型技術 (PBF) 與指向性沈積成型技術 (DED) 列印金屬件，下列敘 述何者有誤？",
