    "explanation": "### 【核心考點】PBF 與 DED 金屬積層製造支撐結構 (Support) 必要性辨析\n### 【正確答案說明】\n在金屬 3D 列印中（PBF 與 DED）：\n- **金屬粉末床熔融 (PBF)**：雖然塑膠 SLS 的周圍散粉可作為天然支撐，但金屬 PBF（SLM）在千瓦雷射熔化金屬時會產生巨大的溫度梯度與極高的冷卻熱應力；若沒有設計實體金屬支撐將工件牢牢錨定在成型基板上，金屬件會產生劇烈翹曲變形而報廢，且金屬支撐還扮演著「將熔池巨額熱量快速導走冷卻」的關鍵散熱通道。因此金屬 PBF「絕對必須建立支撐結構」。\n- **指向性能量沉積 (DED)**：在三軸加工時底面需要棧板；而配備 5 軸聯動系統的 DED 機台可透過工作台傾斜旋轉使熔池法線永遠朝上，在特定空間路徑下可減少支撐。\n因此，金屬 PBF 與 DED「都不需建立支撐結構」的說法是完全錯誤的。故選 (C)。\n### 【選項辨析】\n- **(A) 都可使用粉末為原料**：正確。PBF 為預鋪粉末床，DED 具備同軸送粉噴嘴。\n- **(B) 都可使用雷射束為能量源**：正確。高功率光纖雷射是兩者的主流熱源。\n- **(C) 都不需建立支撐結構**：錯誤（本題正解）。金屬成型中熱應力極大，PBF 必須藉由實體金屬支撐錨固與散熱。\n- **(D) 都需考慮材料的熱應力影響**：正確。急熱急冷在熔池邊界會累積巨大的殘餘熱應力。",
