    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】雷射立體光固化成型技術 (SLA) 雙軸振鏡光學掃描機構識別\n### 【正確答案說明】\n題圖所示為典型的上照式立體光固化成型系統：\n- 頂部設置紫外雷射光源（UV Laser）；\n- 光束射向一組由 X/Y 雙軸微型步進馬達控制的高精密光學振鏡（Galvanometer Scanners / 反射鏡系統）；\n- 振鏡透過精密轉動鏡片反射角，控制雷射光斑在液態光敏樹脂槽表面以向量路徑高速移動掃描，掃描過之處單體交聯硬化形成固態薄層；\n- 成型平台向下沉降一個層厚，刮刀整平液面，重複加工。\n此專利製程正是 3D Systems 創始人 Chuck Hull 於 1986 年發明的 **立體光固化成型技術（Laser Stereolithography, SLA）**。故選 (C)。\n### 【選項辨析】\n- **(A) Selective Laser Printing**：非標準專用術語。\n- **(B) Digital Light Processing (DLP)**：採用 DMD 微鏡陣列晶片進行整層面投影，無振鏡單點掃描。\n- **(C) Laser Stereolithography (SLA)**：正確。以雷射經振鏡雙反射鏡偏轉路徑掃描光聚合。\n- **(D) On-Demand Resin Writing**：為直寫墨水成型技術（DIW），非雷射掃描樹脂槽。",
    "id": 110,
