    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】核殼型複合粉末 (Core-Shell Powder) 之選擇性雷射燒結 (SLS) 早期工藝\n### 【正確答案說明】\n在早期金屬積層製造技術尚未成熟（雷射功率較低且無光纖雷射）的發展階段，業界採用了間接金屬成型工藝：\n- 研發「核殼型粉末（Core-Shell Powder）」：內部為高熔點金屬或陶瓷顆粒作為「核心（Core）」，外部包裹一層薄薄的低熔點高分子聚合物（如尼龍 PA 或樹脂）作為「外殼（Shell）」；\n- 鋪粉後，使用低功率 CO2 雷射掃描粉末床，雷射能量只需將外層的高分子外殼熔融軟化產生熱黏著，將金屬核心黏結在成型平面上（形成生胚）；\n- 此利用雷射選擇性熱黏結粉末的工藝屬於經典的 **選擇性雷射燒結（Selective Laser Sintering, SLS）** 製程。列印後的生胚再置入脫脂燒結爐中高溫燒除高分子並使金屬核心冶金燒結緻密化。故選 (A)。\n### 【選項辨析】\n- **(A) 選擇性雷射燒結 (SLS)**：正確。利用雷射局部加熱融化核殼粉末表面高分子黏著劑黏結成型。\n- **(B) 選擇性雷射熔結 (SLM)**：全熔融製程，直接熔化純金屬顆粒本體，不使用高分子包覆殼。\n- **(C) 雷射指向性沉積 (DED)**：噴嘴直接送粉，非粉末床鋪平堆疊作業。\n- **(D) 薄片雷射疊層 (SHL/LOM)**：使用片材切割疊合，非粉末原料。",
