    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】黏著劑噴印成型技術 (BJT) 之常溫大氣加工環境優勢\n### 【正確答案說明】\n黏著劑噴印成型技術（Binder Jetting, BJ / BJT）的成型過程是在粉末床上室溫進行：\n- 壓電噴墨噴頭選擇性噴出微量液態有機膠水（如水性或高分子黏結劑）潤濕並黏合粉末顆粒；\n- 整個噴印過程中，粉末與黏著劑均處於常溫大氣環境下，**完全不需要高溫加熱、無金屬劇烈氧化風險，因此「完全無需控制嚴格的真空或惰性保護氣氛（如氬氣）」**。\n- 原料粉末極具廣泛性，石膏、砂粒、金屬合金粉、陶瓷粉均可使用；未受黏著劑浸潤的周圍散粉本身天然充當支撐材料，列印完吹除後可 100% 篩分回收再利用。\n故 (A) 選項「需要妥善的氣氛控制」敘述有誤，為本題正解。\n### 【選項辨析】\n- **(A) 其加工方式與粉末床熔融技術類似，需要妥善的氣氛控制**：錯誤（本題正解）。BJT 為常溫化學黏結，無需真空或惰性氣體保護艙。\n- **(B) 粉末可以是石膏、金屬、高分子等各類粉末**：正確。材料適應性極廣。\n- **(C) 未經黏著劑噴印的粉末，可再被回收利用**：正確。常溫散粉未受高溫劣化，篩分後可重複使用。\n- **(D) 粉末本身就是支撐材料**：正確。散粉全方位托附懸空幾何。",
