    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】粉末床熔融技術 (PBF) 核心子系統架構識別\n### 【正確答案說明】\n工業級金屬或高分子粉末床熔融（PBF）設備包含五大核心子系統：\n1. **光學模組（Optical System）**：雷射震盪器、擴束鏡、動態聚焦鏡及高精密雙軸反射振鏡；\n2. **鋪粉模組（Recoating System）**：鋪粉刮刀或反向旋轉滾筒、供粉缸、溢粉回收槽；\n3. **平台升降模組（Build Elevator）**：具備微米級閉迴路光學尺定位的高剛性 Z 軸螺桿工作台；\n4. **氣氛保護模組（Gas Flow & Filter System）**：抽真空閥、氬氣/氮氣循環增壓系統、煙塵層流過濾循環器；\n5. **熱場控制與中央監控模組**。\n「壓電模組（Piezoelectric Actuator Module）」是用於 MJT / BJT 噴墨噴頭中驅動微滴微射之核心元件，在 PBF 設備中並不存在。故選 (C)。\n### 【選項辨析】\n- **(A) 光學模組**：PBF 核心。負責雷射聚焦與空間偏轉掃描。\n- **(B) 鋪粉模組**：PBF 核心。負責刮平微米級均勻粉末薄層。\n- **(C) 壓電模組**：非 PBF 零組件（本題正解）。屬於噴墨列印技術之專用驅動單元。\n- **(D) 氣氛模組**：PBF 核心。維持艙內高純度惰性保護氛圍與吹掃熔融煙塵。",
