    "stem": "材料擠出技術系統輸入 STL 格式後 ， 進行加工設定後 ， 輸出何者格式進行加工？",
    "question": "材料擠出技術系統輸入 STL 格式後 ， 進行加工設定後 ， 輸出何者格式進行加工？",
    "options": [
      "PNG 格式；",
      "Part 格式；",
      "Asm 格式；",
      "G-code 格式"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】材料擠出 (ME / FFF) 數位製造工作流程與 G-code 輸出\n### 【正確答案說明】\n材料擠出技術（Material Extrusion, ME / FFF）之標準數位製造流程為：\n1. 三維電腦輔助設計（3D CAD）繪製模型；\n2. 匯出標準三角網格格式檔案（STL 或 3MF 格式）；\n3. 載入切層軟體（Slicer），設定層厚、外壁、填充率、溫度與速度等製程參數；\n4. 切層軟體演算出三維路徑，並編譯輸出為電腦數值控制語言——「**G-code（G代碼）加工程式檔案**」；\n5. 列印機主機板解譯 G-code 指令（如 G0/G1 直線插補移動、M104/M109 噴頭加熱、E 擠出軸步進），驅動馬達與加熱器進行實體加工。\n故輸出格式為 G-code，選 (D)。\n### 【選項辨析】\n- **(A) PNG 格式**：為 2D點陣圖影像格式，主要用於 LCD 光固化之光罩切片圖片。\n- **(B) Part 格式**：為 SolidWorks / NX 等 CAD 軟體之原始三維零件設計圖檔。\n- **(C) IGES 格式**：為傳統曲面交換通用格式，機台無法直接依此運算路徑。\n- **(D) G-code 格式**：正確。為數值控制工具機與 FFF 列印機標準加工控制碼。",
