    "num": 3,
    "stem": "材料擠出系統中，遇到必須建立支撐結構時，最有效的拆除支撐結構的支撐建 構方法是？",
    "question": "材料擠出系統中，遇到必須建立支撐結構時，最有效的拆除支撐結構的支撐建 構方法是？",
    "options": [
      "以較軟的材料製作支撐結構 ；",
      "以較硬的材料製作支撐結構 ；",
      "以與主結 構相同的材料建立支撐結構；",
      "以上皆非"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】雙噴頭材料擠出 (ME) 支撐拆除效益最佳化\n### 【正確答案說明】\n在材料擠出系統中，若模型存在深孔、盲孔、懸臂或極為細緻的曲面，使用同種硬質材料（如 PLA 印本體且 PLA 印支撐）會因層間熱熔結合過緊，在機械剝除時極易折斷精細特徵或留下嚴重凹凸疤痕。\n最有效、最乾淨且無損表面品質的支撐解決方案是採用配備雙擠出機的機台：\n- **主噴頭擠出結構主體材料**（如 PLA / ABS）；\n- **第二噴頭使用「水溶性材料（如 PVA、BVOH）」或「可溶解於檸檬烯之 HIPS」或「低黏結力易剝離之專用支撐材料」製作支撐結構**；\n列印完成後直接將工件投入水中或專用溶劑浴中完全溶解，或因介面剪切強度極低而能以手輕柔剝除，完全保護零件本體。故選 (A)。\n### 【選項辨析】\n- **(A) 以不同且較易拆卸/溶解之材料製作支撐結構**：正確。雙噴頭水溶性或專用易撕材料是保護表面與無損拆除的最佳策略。\n- **(B) 增加支撐接觸面積**：大面積緊密接觸會使支撐與模型熔合更緊，拆除更加困難。\n- **(C) 提高支撐列印溫度**：高溫加劇材料互溶，導致支撐黏死無法拆卸。\n- **(D) 將支撐與模型完全融合不留間隙**：會使支撐徹底成為模型本體一部分，無法剝除。",
    "id": 117,
