    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】材料擠出 (ME) 內部填充率 (Infill Density) 與強度之因果關係\n### 【正確答案說明】\n在材料擠出系統（FFF / FDM）中，工件是中空多孔結構：\n- 填充率（Infill Density）設定決定了封閉外殼內部塑料骨架的實心體積百分比；\n- 填充率由 10% 提高到 50%、80% 乃至 100%，零件內部承載受力的高分子實體橫截面積成倍增加，能有效抵抗外力引發的剪切、拉伸與壓潰應變；\n- 實驗力學研究證實，在壁厚固定前提下，「**內部填充率與工件最終承受破壞載重之機械強度具有最直接的正向因果關係**」。故選 (B)。\n### 【選項辨析】\n- **(A) 外壁列印速度**：速度微調影響外觀光澤與吐料均勻，非決定整體承載強度的最核心因數。\n- **(B) 填充率 (Infill Density)**：正確。實體受力截面積大小直接決定零件巨觀力學極限強度。\n- **(C) 裙邊 (Skirt) 寬度**：裙邊僅用於噴嘴引流排氣，列印後即丟棄，與模型強度完全無關。\n- **(D) 底層初始抬升速度**：影響脫盤穩定性，不決定硬化後工件的整體內部結構剛性。",
