    "num": 6,
    "stem": "雷射能量與光聚合固化樹脂間之光聚合程度可依據何者法則來定義？",
    "question": "雷射能量與光聚合固化樹脂間之光聚合程度可依據何者法則來定義？",
    "options": [
      "Beer-Lambert ；",
      "Gaussian ；",
      "Maxwell ；",
      "Scaling"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】光化學反應定律：Jacobs 光固化方程與 Beer-Lambert 法則\n### 【正確答案說明】\n在光聚合固化成型技術（VP）中，光固化樹脂的硬化深度（Cure Depth, $C_d$）與雷射或光源照射能量密度（Exposure, $E$）之間的定量關係式被稱為 Jacobs 工作曲線方程：\n$$C_d = D_p \\ln\\left(\\frac{E}{E_c}\\right)$$\n該方程的物理數學基礎是建立在描述光在均勻吸收介質中穿透吸收衰減的 **Beer-Lambert 法則（比爾-朗伯吸收定律）**。該定律定義了光強隨照射深度呈負指數關係衰減，由此導出固化深度與曝光量之自然對數關係。故選 (A)。\n### 【選項辨析】\n- **(A) Beer-Lambert 法則**：正確。光固化深度與能量衰減之基礎光化學理論基石。\n- **(B) Gaussian 法則**：高斯分佈描述的是雷射光束空間橫截面光斑的光強輻射輪廓，非固化穿透吸收關係。\n- **(C) Maxwell 方程**：為宏觀電磁場理論基礎方程組，非光聚合深度特徵方程。\n- **(D) Scaling 縮放定律**：為力學與流體力學無因次幾何相似縮放準則。",
