    "subject": "s1",
    "subject_name": "第一科：3D列印概論",
    "chapter": "第二章 3D 列印設備系統(ME 與VP 技術)",
    "assessmentTopic": "S12",
    "assessmentContent": "S1201",
    "num": 7,
    "stem": "材料擠製成型技術的加工物件常會因為熱效應 而發生縮收的現象 ， 則展現在加 工完成物件上會有什麼影響？",
    "question": "材料擠製成型技術的加工物件常會因為熱效應 而發生縮收的現象 ， 則展現在加 工完成物件上會有什麼影響？",
    "options": [
      "縮孔；",
      "尺寸誤差；",
      "牽絲於結構中；",
      "以上皆是"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】材料擠製熱膨脹係數冷卻收縮引發之多種缺陷\n### 【正確答案說明】\n材料擠製成型（FFF）將塑料自高溫熔融狀態（約 200°C 以上）擠出堆疊於室溫環境中，塑料在由液態降溫冷卻結晶凝固的過程中，由於分子熱運動減緩、鏈段緊密排布，體積必然發生熱收縮（如 ABS 收縮率達 0.8%）。\n熱收縮現象在加工件上的具體缺陷表徵包括：\n1. **尺寸誤差（Dimensional Error）**：模型整體外觀幾何尺寸比 CAD 設計尺寸等比例偏小；\n2. **縮孔與凹陷（Sink Marks / Voids）**：在厚壁實心區域，表層先凝固而內部後冷卻收縮，在表面形成微觀凹坑縮孔；\n3. **牽絲（Stringing）**：熔體在高溫殘熱下受內壓流涎於非列印間隙。\n故縮孔、尺寸誤差、內部應力微裂皆屬熱效應收縮引發之問題，選 (D) 以上皆是。\n### 【選項辨析】\n- **(A) 縮孔**：厚壁區域冷卻體積不均勻收縮產生。\n- **(B) 尺寸誤差**：宏觀熱脹冷縮使冷卻後零件尺寸低於設計標稱值。\n- **(C) 牽絲於結構中**：噴嘴殘熱使熔體流動流涎拉絲。\n- **(D) 以上皆是**：正確。涵蓋了熱塑性冷卻熱效應所引發之綜合缺陷。",
    "id": 121,
    "display_num": 7,
