    "subject_name": "第一科：3D列印概論",
    "chapter": "第二章 3D 列印設備系統(ME 與VP 技術)",
    "assessmentTopic": "S12",
    "assessmentContent": "S1201",
    "num": 15,
    "stem": "光聚合固化成型技術 (VP)之光照射與成型方式，下列敘述何者正確？",
    "question": "光聚合固化成型技術 (VP)之光照射與成型方式，下列敘述何者正確？",
    "options": [
      "可區分為上照式 (Top-Down) 與下照式 (Bottom -Up)兩種 ；",
      "一般使用的樹脂 對 IR(紅外光 )能有良好硬化反應；",
      "光能量與固化深度呈線性關係；",
      "光聚 合反應會伴隨著些微體積的膨脹"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】光聚合固化 (VPP) 空間光照方向架構分類\n### 【正確答案說明】\n在光聚合固化成型技術（VP / VPP）中，依據光源相對於樹脂槽液面的幾何相對方位，標準分類嚴格區分為兩大基本形式：\n1. **上照式（Top-Down）**：光源架設於樹脂液面上方，垂直向下聚焦或投影照射，成型平台浸沒於液體中由上往下逐層沉降；\n2. **下照式（Bottom-Up）**：光源安裝於底部密封機箱內，穿透透明平底樹脂槽向上投射，成型板由槽底逐步向上拉拔抬升。\n一般光敏樹脂對紫外光（UV 365-405 nm）感光，對紅外光（IR）不具光化學反應；光聚合過程伴隨分子鍵長縮短產生微觀體積收縮（而非膨脹）；光能量與固化深度呈半對數關係而非線性。故 (A) 選項完全正確。\n### 【選項辨析】\n- **(A) 可區分為上照式 (Top-Down) 與下照式 (Bottom-Up) 兩種**：正確。光固化設備兩大空間運動學架構。\n- **(B) 一般使用的樹脂對 IR (紅外光) 能有良好硬化反應**：錯誤。IR 僅有熱效應，感光化學反應需紫外線 UV。\n- **(C) 光能量與固化深度呈線性關係**：錯誤。依 Beer-Lambert 定律呈自然對數關係。\n- **(D) 光聚合反應會伴隨著些微體積的膨脹**：錯誤。單體轉化為高分子網絡會伴隨體積收縮（Shrinkage）。",
