    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】FFF 成型平台水平校正 (Bed Leveling) 之幾何約束維度\n### 【正確答案說明】\n在 FFF 列印機中進行平台校正（Bed Leveling，手動旋鈕調平或利用 BLTouch / 近接感應器進行自動網床調平）：\n- 其唯一的物理任務是：「**校正成型平台在三維空間中的水平度，確保工作平台表面處處與噴頭運動的 XY 平面嚴格平行，並保證整個底板上各點的 Z 軸起始高度間隙一致**」；\n- 平台校正僅調整 Z 軸方向的垂直間隙與傾角，**「完全無法消除或補償 X/Y 軸水平運動方向上的固有機械幾何誤差」**（例如 X/Y 軸皮帶鬆弛導致的橢圓失圓、X 軸與 Y 軸導軌不垂直引起的剪切菱形平行四邊形誤差、步進馬達步距脈衝誤差等）。\n故 (D) 選項稱「平台校正後可減少 XY 方向的誤差」敘述有誤。\n### 【選項辨析】\n- **(A) 透過手動調整可以校正平台的高低落差**：正確。調節四角螺簧手擰螺母。\n- **(B) 用極限開關或感應器可協助自動校正落差**：正確。自動生成網格高度補償矩陣。\n- **(C) 平台校正後仍然可能列印出歪斜物件**：正確。若 X/Y/Z 運動機械軸本身不垂直，模型仍會整體斜偏。\n- **(D) 平台校正後可減少 XY 方向的誤差**：錯誤（本題正解）。調平僅作用於 Z 軸法向距離，與 XY 幾何尺寸誤差無關。",
