    "stem": "關於光固化列印設備使用的安全注意事項，以下敘述何者有誤？",
    "question": "關於光固化列印設備使用的安全注意事項，以下敘述何者有誤？",
    "options": [
      "不慎噴濺眼睛時，應立即用有機溶劑沖洗；",
      "使用設備時，應配戴手套和 活 性碳口罩 以避免接觸 到樹脂；",
      "若皮膚不 慎觸碰到 樹脂應盡快 做清潔；",
      "工作環境有溶劑及樹脂的使用，環境應通風"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】化學品危害防護規範：有機溶劑噴濺眼睛之緊急急救處置\n### 【正確答案說明】\n在操作光固化（VPP）設備與處理化學耗材時，若液態光敏樹脂或異丙醇（IPA）等有機化學溶劑不慎噴濺進入眼睛：\n- **唯一正確的緊急醫療處置程序為**：「**立即使用大量潔淨的流動清水或實驗室專用洗眼器持續溫和沖洗眼睛至少 15 至 20 分鐘**」，沖洗時強迫翻開上下眼瞼徹底稀釋沖走化學品，並立即送醫急救。\n- 「**絕對嚴禁使用任何有機溶劑（如酒精、乙醚、丙酮）沖洗眼睛**」！有機溶劑具強烈脫脂性與細胞毒性，會瞬間溶解角膜上皮細胞與基質層，引發不可逆的角膜化學灼傷壞死與永久失明。故 (A) 選項「立即用有機溶劑沖洗」為嚴重致命錯誤操作。\n### 【選項辨析】\n- **(A) 不慎噴濺眼睛時，應立即用有機溶劑沖洗**：嚴重錯誤（本題正解）。嚴禁使用溶劑洗眼，必須以大量純水沖洗。\n- **(B) 使用設備時，應配戴耐化學手套和活性碳口罩**：正確安全規範。阻絕經皮吸收與 VOCs 呼吸危害。\n- **(C) 若皮膚不慎觸碰到樹脂應盡快做清潔**：正確安全規範。以肥皂水徹底洗淨。\n- **(D) 工作環境有溶劑及樹脂的使用，環境應維持通風**：正確安全規範。排風防有機蒸氣蓄積爆炸與中毒。",
    "id": 133,
    "display_num": 19,
    "source_id": "3d-36bc478618a1d656",
    "source_version": "official-through-115-05",
    "question_uid": "3d-dc3f1527c3cf497df5729793",
    "content_hash": "a0d7e211ed6843c1eb8e66149d019ad0f0783cd5cfc60a2024791ddd7e6c33c7"
