    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】材料擠製進料輪磨耗打滑與堵料過熱安全防護\n### 【正確答案說明】\n在 FFF 列印機運轉過程中，擠出機進料齒輪（棘輪）負責緊咬線材強推入喉管：\n- 若發現「**進料棘輪發出異音（如喀喀打滑跳步聲），且齒輪齒縫佈滿被刨磨下的材料碎屑**」，這代表噴頭熱端或喉管內部已經發生嚴重堵塞（Clogging），導致進料背壓阻力遠大於馬達推力，齒輪正在刨削線材打滑；\n- 此時若抱持「只要還可以勉強出料就繼續列印」的僥倖心態，線材隨時會被完全磨斷造成缺料空打；更嚴重的是，熱端內部積聚的塑料在長時間高溫烘烤下會深度碳化結焦，甚至引發加熱塊散熱失效與熱失控起火危險。\n因此正確作法必須「**立即停機暫停，拆卸清理進料齒輪溝槽碎屑並排查噴嘴堵塞**」。故 (B) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 若發現接頭接觸不良，需停機檢修**：正確安全規範。防止電氣跳火與熱失控火災。\n- **(B) 若進料輪有異音佈滿碎屑，只要還能出料可繼續列印**：錯誤（本題正解）。必須停機清理排除堵料，防止設備損壞與火災。\n- **(C) 列印時若聞到燒焦味道，可能是加熱溫度過高**：正確安全常識。塑料過熱熱解焦化之警訊。\n- **(D) 列印運作中請勿用手清除噴頭殘料以防燙傷**：正確安全規範。噴頭高達 200°C 以上極易嚴重燙傷。",
