    "subject_name": "第二科：3D製程與材料概論",
    "chapter": "第一章 3D 建模(ME 及VP 技術)",
    "assessmentTopic": "S21",
    "assessmentContent": "S2101",
    "num": 1,
    "stem": "以下何者為正確 3D 列印模型與列印的描述？",
    "question": "以下何者為正確 3D 列印模型與列印的描述？",
    "options": [
      "有了 3D 列印，任何數位的 模型都可以直接列印出來；",
      "數位的模型都需要轉成 G-Code 為輸出，3D 列印設 備才能使用；",
      "3D 列印實體數位模型的資料結構是以 G-Code 來定義；",
      "實體 數位模型在 3D 列印前會需要前處理程序。"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】3D 實體模型切層前處理 (Pre-Processing) 的必要性\n### 【正確答案說明】\n在積層製造工作流程中，電腦上設計的三維 CAD 數位幾何模型並不能直接傳輸給 3D 列印機列印。因為不同的積層製造技術（如 MEX 熔融擠出、VP 光聚合固化、PBF 粉床熔融）具備完全不同的成型物理限制（如懸臂極限、離型脫模拉拔力、最小壁厚、封閉內腔排膠孔等）。在實際列印前，必須透過前處理軟體對實體數位模型進行：檔案修復、擺放方位設定、設計必備支撐結構、設定切層厚度與填充參數，並由切層引擎計算生成機台運動控制代碼（如 G-code）。故 (D) 選項正確。\n### 【選項辨析】\n- **(A) 任何數位模型都可以直接列印出來**：錯誤。存在壁厚過薄、非流形（Non-manifold）邊緣或懸臂等幾何限制。\n- **(B) 數位的模型都需要轉成 G-code 為輸出**：錯誤。部分光固化或彩色噴墨設備使用點陣圖切片（PNG/SVG）而非 G-code。\n- **(C) 3D 列印實體數位模型的資料結構是以 G-code 來定義**：錯誤。3D 模型是由邊界幾何（STL、BREP）定義，G-code 僅是機台運動指令。\n- **(D) 實體數位模型在 3D 列印前會需要前處理程序**：正確。需經模型檢查、擺放、支撐設計與切層前處理。",
