    "subject_name": "第二科：3D製程與材料概論",
    "chapter": "第一章 3D 建模(ME 及VP 技術)",
    "assessmentTopic": "S21",
    "assessmentContent": "S2101",
    "num": 6,
    "stem": "標準的 AMF 文件包含 object 、material 、texture 、constel lation 、metadata 等五 個頂級的元素，下列描述何者錯誤？",
    "question": "標準的 AMF 文件包含 object 、material 、texture 、constel lation 、metadata 等五 個頂級的元素，下列描述何者錯誤？",
    "options": [
      "object 表示欲建構模型不含形狀的其它資訊；",
      "material 表示欲建構模型 的材料；",
      "texture 表示欲建構模型的顏色；",
      "constellation 表示欲建構模型 的結構與結構的關係"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】新一代 3MF 相比 STL 格式之現代化優勢\n### 【正確答案說明】\n3MF（3D Manufacturing Format）是由微軟協同 HP、Autodesk、Stratasys 等巨頭組成的 3MF 聯盟推出的新一代開源積層製造資料交換格式：\n- STL 僅能記錄無色彩的幾何三角形邊界，容易發生拓撲破面、反向法線等錯誤；\n- **3MF 採用壓縮包裝的 XML 格式**，能完美在單一檔案內同時包含：**完整的全彩色資訊、表面微觀材質貼圖（Textures）、多材料分配、組裝件階層關係（Assemblies）、以及列印切層製程設定與縮圖**；且其幾何資料結構天然保證水密閉合性，不會出現破面錯誤。故選 (A)。\n### 【選項辨析】\n- **(A) 可完整包含色彩、材質貼圖、組裝階層與切層設定**：正確。3MF 全面超越 STL 之核心優勢。\n- **(B) 檔案體積必定比 Binary STL 大數十倍**：錯誤。3MF 內建高效壓縮，體積通常比相同精度的 ASCII STL 小得多。\n- **(C) 僅能由微軟特定作業系統專屬讀取**：錯誤。為跨平臺開放標準格式。\n- **(D) 無法記錄空間三角形頂點**：錯誤。3MF 亦是以先進網格或幾何實體描述空間形狀。",
    "id": 140,
