    "assessmentTopic": "S21",
    "assessmentContent": "S2101",
    "num": 7,
    "stem": "在三角網格最佳化的情況下，立方體是由幾個三角形組裝而成？",
    "question": "在三角網格最佳化的情況下，立方體是由幾個三角形組裝而成？",
    "options": [
      "8；",
      "10；",
      "12；",
      "14"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】標準立方體 STL 網格幾何數量計算\n### 【正確答案說明】\n在三維歐幾里得幾何中，一個封閉的正六面體（正方體 Cube）擁有 6 個互相垂直的正方形平面表面：\n- 由於 STL 格式嚴格規定表面必須由三角形小平面構成，每個平面的四邊形正方形沿對角線最少必須且只能被分割為 **2 個三角形**；\n- 因此描述一個幾何封閉完整的正方體實體表面，最少需要的三角形小平面總數為：\n  $$6 \\times 2 = 12 \\text{ 個三角網格}$$\n每個三角形包含 3 個空間三維頂點與 1 個法向量（總計 12 個浮點數）。故正方體最少需 12 個小平面，選 (C)。\n### 【選項辨析】\n- **(A) 6 個**：僅為正方形表面數，未細分為三角形。\n- **(B) 8 個**：為頂點數量，非三角形面數。\n- **(C) 12 個**：正確。6 個面每面 2 個三角形，共計 12 個三角網格。\n- **(D) 24 個**：若過度細分亦可，但最少只需 12 個。",
    "id": 141,
