    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】排料塔 / 犧牲層 (Purge / Prime Tower) 真正目的辨析\n### 【正確答案說明】\n在多材料或多色 FFF 3D 列印中，切層軟體常在工作台角落生成一個方形柱狀「排料塔（Prime Tower / Purge Tower，又稱犧牲層）」：\n- 其真正工程目的為：在噴頭切換不同顏色或不同材質線材時，先在排料塔上進行耗材擠出清洗，排乾淨前一顏色殘料（防混色混濁），並在噴嘴內部重新建立穩定的熔融流動擠出壓力，確保回到主模型列印時出料飽滿均勻。\n- 「增加整體列印時間」是列印排料塔必然帶來的**負面副產物代價**，絕對「不是」工程師設計犧牲層的目的。故 (A) 選項「增加列印時間」非其目的，符合題意。\n### 【選項辨析】\n- **(A) 增加列印時間**：非其目的（本題正解）。增加工時為負面代價，絕非設計出發點。\n- **(B) 清除換料時噴嘴內之殘餘舊料**：為其主要目的。避免不同色料互相污染。\n- **(C) 重新建立噴嘴內部擠出熔融壓力**：為其主要目的。消除空行程滲漏引發的吐料不足。\n- **(D) 改善多色列印邊界分明度**：為其主要目的。確保換色接縫清晰銳利。",
