    "stem": "在以材料擠製成型的前處理時 ， 會選擇建構支撐結構 ， 還有設定支撐結構的密 度，支撐結構的密度表示為？",
    "question": "在以材料擠製成型的前處理時 ， 會選擇建構支撐結構 ， 還有設定支撐結構的密 度，支撐結構的密度表示為？",
    "options": [
      "密度越高則物件的支撐結構強度越大；",
      "列印出來的支撐結構會影響到物 件的填充率；",
      "列印出來的支撐結構會也會在物件上表面長出支撐；",
      "以上 皆是"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】光固化薄殼中空模型抽真空吸盤效應與排氣孔 (Vent) 設計\n### 【正確答案說明】\n在下照式光固化中，若列印封閉的中空薄殼球體或容器（中空模型且未開孔）：\n- 當成型板帶著薄殼向上抬升時，中空內部的樹脂無法及時流出，內部封閉腔體形成嚴重的「真空負壓吸盤效應（Suction Cup Effect）」；\n- 巨大的大氣壓差與拉拔力會直接將薄殼壁面吸破撕裂，或使整件模型從支撐柱上拔落。\n解決方案為：在「**靠近成型平台的最底部壁面上預先設計至少一個氣孔/排膠孔（Vent / Drain Hole）**」，使抬升時空氣能順暢進入腔體平衡內外氣壓，消除真空吸盤效應，並便於列印完成後排淨內部積存的液態樹脂。故選 (A)。\n### 【選項辨析】\n- **(A) 平衡內外氣壓，消除真空吸盤效應並利於殘膠排出**：正確。中空光固化件必備之設計準則。\n- **(B) 增加模型對外的散熱通風**：錯誤。光固化在常溫液體中進行，非風冷散熱。\n- **(C) 提高模型光線穿透度**：錯誤。固化完成後已無透光需求。\n- **(D) 減小模型實體重量**：中空已減重，開孔專門為平衡壓差與排液。",
    "id": 146,
    "display_num": 12,
