    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】切層軟體支撐生成器 (Support Generator) 關鍵參數設定\n### 【正確答案說明】\n在 Meshmixer、Cura、PreForm 等前處理軟體的自動支撐生成器中，工程師調控支撐形態的核心參數包含：\n1. **懸垂閥值角度（Overhang Angle Threshold，如 45°）**：判定模型表面與垂直軸夾角大於何值時自動生長支撐；\n2. **接觸點直徑（Contact Point Size / Tip Diameter）**：支撐尖端與模型接觸的粗細；\n3. **支撐柱密度與間距（Support Density / Spacing）**。\n合理設定這些參數能在「提供充足抗拉拔支撐力」與「拆除後表面傷痕最小化」之間取得最佳平衡。故選 (A)。\n### 【選項辨析】\n- **(A) 懸垂角度閾值、接觸點直徑與支撐密度**：正確。支撐生成器三大核心演算法參數。\n- **(B) 雷射波長與雷射功率**：為硬體光學物理參數，非幾何支撐生成演算法參數。\n- **(C) 樹脂化學反應活化能**：為化學材料常數，非切層軟體幾何設定。\n- **(D) 伺服馬達脈衝解析度**：為韌體硬體參數。",
