    "stem": "此圖用 CAD 繪製的兔子模型，在以熔融擠出的方式，以下何者是此模型載入 切層軟體 (Cura )的適當擺放位置？\n\n![CAD 繪製兔子模型](images/3d/sg_s2_c1_3_q1_stem.png)",
    "question": "此圖用 CAD 繪製的兔子模型，在以熔融擠出的方式，以下何者是此模型載入 切層軟體 (Cura )的適當擺放位置？\n\n![CAD 繪製兔子模型](images/3d/sg_s2_c1_3_q1_stem.png)",
