    "explanation": "### 【核心考點】材料擠製技術切層輸出檔案格式\n### 【正確答案說明】\n材料擠製成型（MEX / FFF）切層軟體將 3D 模型離散分層並規劃出走線軌跡後，輸出的加工程式標準檔案格式為 **G-code（G代碼）**，包含馬達空間座標位移、進給速度、加熱溫度與擠出量指令。故選 (B)。\n### 【選項辨析】\n- **(A) STL**：切層前輸入的網格模型檔案。\n- **(B) G-code**：正確。切層運算後輸出之數值控制加工代碼檔案。\n- **(C) DXF**：二維向量工程圖檔案。\n- **(D) STEP**：三維實體 CAD 模型交換格式。",
