    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】自適應切層 (Adaptive Layering / 可變層厚) 機制識別\n### 【正確答案說明】\n如題圖所示，切層分層線條在不同高度上間距各不相同：\n- 在模型垂直平直、幾何變化平緩的區域，切層厚度自動放大（間距較寬），以大幅提高列印掃描速度；\n- 在模型曲率急劇變化、細節豐富或傾斜角度平緩的特徵區域，切層厚度自動動態縮小（間距極窄），以極度削弱階梯效應、提升曲面細緻度。\n這種根據幾何特徵曲率自動動態調整每層厚度的方法，被稱為「**自適應切層（Adaptive Layering / Variable Layer Height）**」。故選 (B)。\n### 【選項辨析】\n- **(A) 固定層厚切層**：所有分層間距完全均勻相等。\n- **(B) 自適應切層 (可變層厚)**：正確。兼顧成型效率與曲面高精度的現代切層算法。\n- **(C) 放射狀切層**：分層沿徑向展開，非平面水平分層。\n- **(D) 隨機層厚切層**：層厚具備幾何自適應規則，非隨機無序分佈。",
