    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】階梯效應 (Staircase Effect) 與切層厚度之物理因果反比\n### 【正確答案說明】\n積層製造是以平整薄層堆疊逼近連續傾斜曲面：\n- 單層厚度 $\\Delta z$ 越大，微觀台階向外凸出的階梯台階寬度 $\\Delta x = \\Delta z / \\tan\\theta$ 越大，理論輪廓與真實加工表面之間的「成型階梯幾何誤差就越大」；\n- 若要減小成型誤差，必須「大幅降低加工層厚（使用極薄切層）」，使微觀階梯趨於無限細微。\n因此，若敘述稱「加工層越厚，層間產生的誤差就越小，所以應以最大可能層厚加工」，完全顛倒了幾何切層誤差的物理因果關係。故 (A) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 加工層越厚，層間產生的誤差就越小，應以最大厚度加工**：有誤（本題正解）。層越厚階梯誤差越大，薄層才能減小誤差。\n- **(B) 每一層鋪塗的材料厚度需要維持均勻一致**：正確。保證尺寸穩定。\n- **(C) 階梯效應是積層製造固有的離散逼近特徵**：正確。分層製造之必然現象。\n- **(D) 斜率越平緩的表面，階梯效應越顯著**：正確。小傾角表面台階寬度最明顯。",
    "id": 151,
    "display_num": 17,
    "source_id": "3d-3768cdad2abfe808",
    "source_version": "official-through-115-05",
    "question_uid": "3d-072426d39df8edd33459baaa",
    "content_hash": "4849ec5de22126b6f3a0ac46c56cbd6bb68dde850c059907bc36a121c43e6764"
