    "assessmentTopic": "S21",
    "assessmentContent": "S2101",
    "num": 18,
    "stem": "積層製造是一層層推疊上去，理論上完成工件的輪廓會形成下圖的形狀 (粗線 是加工件輪廓，曲線是 CAD 輪廓，細直線是三角網格 )，工件的輪廓與細線所 形成的三角形所代表的誤差，即是所謂的？\n\n![階梯效應示意圖](images/3d/sg_s2_c1_3_q5.png)",
    "question": "積層製造是一層層推疊上去，理論上完成工件的輪廓會形成下圖的形狀 (粗線 是加工件輪廓，曲線是 CAD 輪廓，細直線是三角網格 )，工件的輪廓與細線所 形成的三角形所代表的誤差，即是所謂的？\n\n![階梯效應示意圖](images/3d/sg_s2_c1_3_q5.png)",
    "options": [
      "蝴蝶效應；",
      "輪廓效應；",
      "堆疊效應；",
      "階梯效應"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】階梯效應微觀輪廓特徵判讀\n### 【正確答案說明】\n題圖展示了連續平滑傾斜幾何輪廓（細斜線）與實際由一層層矩形薄層離散堆疊加工後的階梯狀邊緣（粗折線）：\n這種由切層厚度限制導致的微觀鋸齒台階現象，在積層製造領域被統稱為「**階梯效應（Staircase Effect）**」。故選 (D)。\n### 【選項辨析】\n- **(A) 翹曲效應**：指熱應力造成的邊角起拱。\n- **(B) 遲滯效應**：指控制系統響應滯後。\n- **(C) 潛變效應**：材料在高溫持續受力下的塑性變形。\n- **(D) 階梯效應 (Staircase Effect)**：正確。二維分層逼近三維斜曲面的固有鋸齒現象。",
    "id": 152,
    "display_num": 18,
    "source_id": "3d-3768cdad2abfe808",
