    "assessmentTopic": "S21",
    "assessmentContent": "S2101",
    "num": 19,
    "stem": "下列為面照式光聚合固化成型 (VP)以不同列印方式製作的掛勾 ， 其斜線表示原 切層紋路，在移除支撐材料後，以箭頭方向為施力，下列那一個切層方式 製作 的掛勾比較不容易斷裂？\n\n![掛勾列印方式示意圖](images/3d/sg_s2_c1_3_q6_a.png)",
    "question": "下列為面照式光聚合固化成型 (VP)以不同列印方式製作的掛勾 ， 其斜線表示原 切層紋路，在移除支撐材料後，以箭頭方向為施力，下列那一個切層方式 製作 的掛勾比較不容易斷裂？\n\n![掛勾列印方式示意圖](images/3d/sg_s2_c1_3_q6_a.png)",
    "options": [
      "![選項A](images/3d/sg_s2_c1_3_q6_a.png)",
      "![選項B](images/3d/sg_s2_c1_3_q6_b.png)",
      "![選項C](images/3d/sg_s2_c1_3_q6_c.png)",
      "![選項D](images/3d/sg_s2_c1_3_q6_d.png)"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】積層製造非均質各向異性：拉力方向與層面平行配置準則\n### 【正確答案說明】\n如題圖掛勾零件在承受垂直向下重物拉力時：\n- 積層製造零件層與層之間（Z 軸）是依靠分子間熱熔或化學交聯結合，層間抗拉強度與抗剪切能力最為脆弱；\n- 水平層面內部（XY 面）連續沉積的線條或聚合物骨架具有最高的抗拉強度；\n- 因此，當掛勾承受向下工作拉伸載重時，最理想的擺放方位是讓「**切層層面（斜線方向）與受拉力主方向保持平行（即拉力完全由連續層面內部承受，如選項 D 所示）**」，避免脆弱的層面分界直接承受垂直剝離正應力，以獲得最大的掛載結構強度。故選 (D)。\n### 【選項辨析】\n- **(A) 層面垂直於拉力方向**：最危險方位。重物拉力直接垂直拉扯層間接縫，極易瞬間層間剝離斷裂。\n- **(B) 夾角受剪**：層間承受剪切應力，強度不佳。\n- **(C) 受力方向貫穿脆弱分層**：抗拉強度低。\n- **(D) 層面走向平行於工作拉伸應力方向**：正確。完全發揮層內最高抗拉強度，承載力最強。",
    "id": 153,
    "display_num": 19,
