    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】STL 檔案幾何屬性邊界：純幾何表面網格\n### 【正確答案說明】\nSTL 格式最初由 3D Systems 定義，其名稱來源即為 Stereolithography（立體光固化）：\n- STL 檔案「**僅描述三維物體的表面封閉幾何形狀（三角面網格座標與法向）**」，不具備任何內部材料密度、全彩顏色、光學透明度或材質紋理貼圖；\n- STL 並非 CAD 原始特徵參數建模檔，無法直接以特徵樹進行 CAD 幾何尺寸編修（逆向編修極其繁瑣）。故 (A) 選項敘述完全正確。\n### 【選項辨析】\n- **(A) 僅描述三維物體表面幾何形狀，不具有內部材質貼圖**：正確。STL 核心格式特性。\n- **(B) 名稱最初來源是 Standard Triangle Language**：非最初來源。最初源自 Stereolithography。\n- **(C) 是一種跨系統的最終列印輸出檔**：STL 需先經切層軟體轉為 G-code 或切片，非機台直接執行的最終加工碼。\n- **(D) 可用於 CAD 系統間輕鬆進行特徵編修**：錯誤。缺乏參數特徵樹，修改極其困難。",
