    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】正方體 STL 浮點數 (Floating Point Numbers) 存儲總量計算\n### 【正確答案說明】\n在標準 STL 檔案資料結構中：\n- 每個三角形小平面（Facet）需要記錄：1 個法向量（$n_x, n_y, n_z$）+ 3 個頂點（每個頂點包含 $x, y, z$），總共由 **12 個單精度浮點數（$12 \\times 4\\text{ bytes} = 48\\text{ bytes}$）** 構成；\n- 一個閉合的正方體表面包含 6 個正方形平面，每個正方形最少需要分割為 2 個三角形，因此完整記錄正方體最少需要 **12 個三角形小平面**；\n- 記錄該正方體所需的浮點數總數為：\n  $$12 \\text{ 個三角形} \\times 12 \\text{ 個浮點數/三角形} = 144 \\text{ 個浮點數}$$\n故最少需要 144 個浮點數，選 (B)。\n### 【選項辨析】\n- **(A) 288**：若每個正方形細分為 4 個三角形才需 288 個。\n- **(B) 144**：正確。12 個三角形 × 12 個浮點數 = 144。\n- **(C) 72**：僅計算了頂點座標（36個）加法向，未按 STL 標準 12 浮點數結構計算。\n- **(D) 36**：僅計算 12 個頂點的三維座標（12×3=36），忽略了法向量與頂點重複記錄規範。",
