    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】FFF 幾何切層路徑規劃運算所考慮之核心維度\n### 【正確答案說明】\n切層引擎（Slicer Engine）在進行純幾何切層與路徑規劃時，運算模型三維網格與空間平面的幾何交集，其考慮的運算因素包括：\n- **切層厚度**：決定水平切割平面的垂直 Z 間距；\n- **支撐型態與演算法**：決定懸空處額外生成的幾何支撐網格；\n- **內部填充密度與走線角度**：決定閉合輪廓內部填充線段幾何。\n而「**成型底板溫度（Bed Temperature）**」純屬機台硬體熱工溫控參數，由切層軟體以靜態 M140/M190 代碼寫入檔案供列印前預熱，完全「不參與」切層演算法幾何分層與刀路路徑拓撲的空間數學運算。故選 (D)。\n### 【選項辨析】\n- **(A) 切層厚度**：核心幾何分層間距參數。\n- **(B) 支撐型態**：支撐幾何演算法運算參數。\n- **(C) 填充密度**：內部刀路間距幾何參數。\n- **(D) 成型底板溫度**：正確（不包含）。純電氣加熱溫控設定，不參與幾何切層路徑之數學運算。",
