    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】下照式 (Bottom-Up) VP 擺放方式與成型成功率因果關係\n### 【正確答案說明】\n在下照式光固化中，提升列印成功率的核心原則是「**盡可能減小每層分離拉拔力，並防止懸空孤島產生**」：\n- **切層面積朝 Z+ 方向由大到小遞減**：底座牢固且後續層皆被前層完整支撐，成功率高；\n- **每層切層截面積越小越好**：截面積小，離型脫模時產生的負壓吸附力與拉拔阻力越小，越不易拉斷脫落；\n- **每層切層重疊率越大越好**：層間物理接觸面積大，層間結合力強不易分層。\n而「**切層厚度越厚**」意味著單層需要更深的光固化深度與更強的曝光，且樹脂重流填補間隙變慢，若參數未微調極易導致層間剝離失敗，因此「切層厚度越厚愈好」絕對無法提高列印成功率。故選 (D)。\n### 【選項辨析】\n- **(A) 切層面積盡量朝 Z+ 方向由大到小**：能提高成功率。自支撐連續性佳。\n- **(B) 每層切層面積越小越好**：能提高成功率。大幅降低槽底拉拔脫模力。\n- **(C) 每層切層間重疊率越大越好**：能提高成功率。增進層間物理黏著結合面積。\n- **(D) 切層厚度越厚愈好**：無法提高成功率（本題正解）。厚層易固化不均且階梯紋粗糙，無助於提高成功率。",
