    "stem": "請問用下照式 (Bottom -Up) 光 聚 合 固 化 成 型 技術 (VP) 列印右圖中的楔型模型，在相同層 厚下，何種的擺放方式列印時間最短 ？\n\n![楔型模型](images/3d/sg_s2_c1_3_q13.png)",
    "question": "請問用下照式 (Bottom -Up) 光 聚 合 固 化 成 型 技術 (VP) 列印右圖中的楔型模型，在相同層 厚下，何種的擺放方式列印時間最短 ？\n\n![楔型模型](images/3d/sg_s2_c1_3_q13.png)",
