    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】面曝光 VPP 列印時間支配因素：工件 Z 軸總高度與平放姿態\n### 【正確答案說明】\n在下照式面投影光聚合固化（DLP / LCD）中：\n- 每一層是整個截面一次性同步曝光，單層耗時固定（曝光時間約 2-3 秒 + 升降脫模約 3-4 秒，每層合計約 6-7 秒）；\n- **總列印時間「嚴格且唯一取決於總切層層數」**，而在層厚固定的前提下，總層數直接由工件在垂直 Z 軸方向的「**最大空間高度**」決定（總時間 $\\propto$ Z 軸高度）；\n- 題目中的楔型模型長寬高分別為 $8\\times 5\\times 3$ 或類似尺寸：\n  若以面積最大的 **$8\\times 5$ 面平貼於 XY 成型板上列印**，工件在垂直 Z 軸的高度僅剩最小邊（高度最低），所需的總切層層數最少，因此「**列印總時間最短**」。故選 (C)。\n### 【選項辨析】\n- **(A) 以 8x4 面貼平**：高度仍高於 (C)。\n- **(B) 以 8x3 面貼平**：垂直高度為 4 或 5，層數多於 (C)。\n- **(C) 以 8x5 面平貼於 XY 面列印**：正確。Z 軸垂直高度達到絕對最低，總層數最少，列印時間最短。\n- **(D) 以 4x3 面貼平**：長邊 8 垂直直立，高度最高，層數最多，列印時間最長。",
