    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】FFF 幾何懸空倒勾特徵與強制支撐判定\n### 【正確答案說明】\n在 FFF 熔融擠製加工題圖模型中：\n- 擺放方式 (A) 由於幾何懸臂特徵朝向側下方突出形成明顯的「水平倒勾（Downward-facing Overhang）」，該倒勾底面完全懸空於空氣中，且傾斜角度遠大於 45 度臨界極限；\n- 剛自噴嘴擠出的半熔融塑料在該倒勾處下方完全無任何物體承托，在重力作用下必然流淌下塌、拉絲成廢料；\n- 因此擺放方式 (A)「**一定要額外添加支撐結構**」方能完整列印出來。故選 (A)。\n### 【選項辨析】\n- **(A) 擺放方式 A**：正確。存在懸空向下突出的倒勾特徵，無支撐必塌陷，一定要加支撐。\n- **(B) 擺放方式 B**：幾何向上收斂，傾角滿足自支撐。\n- **(C) 擺放方式 C**：大底面貼床無懸空倒勾。\n- **(D) 擺放方式 D**：平整接觸平台，整體平穩。",
