    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】FFF 免支撐且最大化底板附著面積之黃金擺放方位\n### 【正確答案說明】\n在 FFF 列印中，評估最理想擺放方式的兩大核心標準：\n1. **完全無需支撐**：所有外壁特徵傾角小於 45 度，無懸空空中孤島與倒勾；\n2. **接觸平台的附著面積最大化**：提供極致的抗傾覆力矩與底板黏結力，徹底杜絕高速移動晃動與底層翹曲。\n在四種擺放方案中，擺放方式 (B) 將零件最大、最平整的底面平貼於成型平台上（附著面積最大），且側面上方呈階梯或斜坡平緩收斂，處於天然自支撐幾何範圍內，完全不需要支撐。故選 (B)。\n### 【選項辨析】\n- **(A) 擺放方式 A**：附著面積小且存在懸空。\n- **(B) 擺放方式 B**：正確。接觸底板面積最大，且完全符合自支撐幾何，免支撐品質最優。\n- **(C) 擺放方式 C**：接觸面積次之或存在微小懸空。\n- **(D) 擺放方式 D**：接觸面呈窄長條狀，穩定性弱於 (B)。",
