    "explanation": "### 【核心考點】下照式面曝光 VP 支撐設計原則與曝光時間獨立性\n### 【正確答案說明】\n在下照式面投影光固化（DLP / LCD）中，支撐設計的關鍵原則包括：\n- 支撐接觸點應盡量避開工件微小精密特徵或重要裝配面，以防拆除時破壞公差；\n- 在易產生應力翹曲的懸臂角落與最低點孤島處，必須牢固建立支撐柱；\n- **支撐結構的數量多寡完全「不會影響單層曝光時間」**！因為面曝光技術是整層所有像素（包含模型本體與所有支撐柱截面）一次性同步照射固化，增加支撐只會微幅增加單層總面積，單層所需的光照固化時間（如 2.5 秒）完全保持不變。若稱「增加支撐需增加曝光時間」，顯屬嚴重觀念錯誤。故 (A) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 增加支撐，需增加曝光時間**：錯誤（本題正解）。面曝光整層同步硬化，支撐數量與曝光時間完全無關。\n- **(B) 支撐的設計要避開微小特徵**：正確設計原則。避免拆除支撐時拉斷精細特徵。\n- **(C) 容易翹曲的地方，需要建立支撐**：正確設計原則。支撐提供機械拉力約束翹曲變形。\n- **(D) 有懸臂的地方要建構支撐**：正確設計原則。防止空中孤島硬化脫落於槽底。",
