    "explanation": "### 【核心考點】材料擠製 (ME / FFF) 切層參數範疇 vs 光學參數排除\n### 【正確答案說明】\n材料擠製成型（ME / FFF）切層軟體處理熱塑性線材機械擠出路徑，其標準參數包含：層厚、外壁圈數、內部填充率與樣式、列印溫度、列印速度、回抽距離與回抽速度。\n「**光罩解析度（Mask Resolution / Projector Resolution）**」專屬於 LCD / DLP 等光聚合固化（VP）設備的光學曝光解析度參數，在材料擠製成型製程中完全不涉及光學投影與光罩，故不屬於材料擠製切層參數。選 (C)。\n### 【選項辨析】\n- **(A) 切層厚度**：ME 標準切層參數。\n- **(B) 內部填充率**：ME 標準切層參數。\n- **(C) 光罩解析度**：正確（不屬於 ME）。為光固化光學系統專屬參數。\n- **(D) 噴頭列印溫度**：ME 標準熱工參數。",
