    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】熔融擠製加工參數說明之正誤辨析\n### 【正確答案說明】\n在熔融擠製（FFF）加工參數中：\n- 擠出溫度直接影響熔融塑料黏度與流動性，溫度適度提高會增加熔絲橫向鋪展寬度與層間熱融合強度；\n- 填料圖案與走線角度會決定內部熱應力方向性，影響工件冷卻時的翹曲傾向；\n- 擠製頭平移速度與出料流量必須維持體積守恆匹配。\n若稱「提高列印溫度會使塑料黏度大幅增加」，完全顛倒了高分子流變學常識（溫度升高熱運動加劇，熔融黏度必然急劇下降）。故選 (A)。\n### 【選項辨析】\n- **(A) 提高擠出溫度會大幅提高塑料熔融黏度使其難以流動**：錯誤（本題正解）。溫度升高熔體黏度急劇下降、流動性增強。\n- **(B) 擠出線寬與切層厚度為獨立可調參數**：正確。\n- **(C) 內部填充樣式會影響零件受力各向異性強度**：正確。\n- **(D) 適度提高列印溫度可改善層間黏結結合力**：正確。促進界面分子鏈熱擴散。",
