    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】熔融擠製成型物件強度與切層輔助結構之關聯\n### 【正確答案說明】\n熔融擠製成型（FFF）完成之零件實體強度，取決於零件內部的實體幾何與材料結合質量：\n- **內部填充率（Infill Density）**：直接決定承載實體截面積，對強度影響最顯著；\n- **外壁圈數與厚度（Wall Thickness）**：直接決定抗彎抗扭表面剛度；\n- **切層厚度與列印溫度**：決定層間熱熔結合面積與微觀強度。\n而「**裙邊寬度（Skirt Width / Brim Width）**」：\n裙邊（Skirt）是在零件外圍繪製的幾圈無接觸封閉線圈（僅用於噴嘴引流排氣，完工即丟棄），側裙（Brim）僅接觸最底層邊緣防止翹曲，它們在列印完成後均會被完全撕除丟棄，對「**工件本體最終的結構強度最無關**」。故選 (C)。\n### 【選項辨析】\n- **(A) 內部填充率**：與強度高度正相關。\n- **(B) 外壁厚度**：與強度高度正相關。\n- **(C) 裙邊寬度 (Skirt/Brim)**：正確（最無關）。僅為底層輔助特徵，完工即拆除，不影響主體強度。\n- **(D) 列印加熱溫度**：影響層間融合結合力。",
