    "explanation": "### 【核心考點】擠製頭移動速度與熔絲擠出寬度熱動力學匹配\n### 【正確答案說明】\n在 FFF 列印中，擠出機齒輪推送材料的線速度與噴頭在空間平移的速度必須嚴格精確同步：\n- 噴頭平移速度加快時，若擠出機供料速度未相應跟上，單位長度沉積的熔體體積減少，會導致拉絲變細甚至斷絲；\n- 降低列印速度能提供更充裕的熱傳導時間，促使擠出絲寬均勻鋪展並緊密熨燙於下層表面。故選 (D)。\n### 【選項辨析】\n- **(A) 速度越快擠出越寬**：錯誤。供料不變下提速會拉細熔絲。\n- **(B) 溫度越低黏結越強**：錯誤。低溫熔合不充分。\n- **(C) 層厚越厚精度越高**：錯誤。層厚越厚台階紋越粗糙。\n- **(D) 噴頭移動速度與出料流量必須維持體積守恆匹配，適度降速有助於出料飽滿穩定**：正確。",
