    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】填料圖案 (Infill Pattern) 對熱收縮內應力分佈之支配\n### 【正確答案說明】\n在 FFF 零件內部，冷卻熱收縮沿著擠出熔絲的長度方向（軸向）收縮率遠大於垂直方向。\n因此，採用不同的內部填充樣式（如網格直線型 Grid、三角形 Triangle、六角蜂巢 Honeycomb 或三維立體陀螺儀 Gyroid），高分子鏈取向冷卻時產生的收縮拉力在各空間軸向的分佈截然不同：\n直線單向填充易在單一軸向累積巨大彎矩引發翹曲，而對稱的蜂巢或各向同性的陀螺儀填充則能將熱應力三維均勻分散，大幅減緩特定方向的翹曲變形。故選 (D)。\n### 【選項辨析】\n- **(A) 填料圖案與收縮變形完全無關**：錯誤。圖案拓撲決定應力傳遞路徑。\n- **(B) 任何圖案皆呈現完全各向同性強度**：錯誤。多數二維圖案具強烈方向性。\n- **(C) 蜂巢狀圖案列印耗時最短**：錯誤。頻繁轉彎變向往往較直線圖案耗時。\n- **(D) 填滿層輪廓內的圖案方法會直接影響加工物件的冷卻變形行為與應力分佈**：正確。",
