    "explanation": "### 【核心考點】材料擠製切層參數綜合優化準則\n### 【正確答案說明】\n綜合材料擠製成型（FFF / ME）參數體系：\n- 線材束徑（線寬）通常由噴嘴出口幾何與擠出乘數控制，與分層層厚不需相等；\n- 適度提高噴頭溫度能改善熔絲層間界面熔接強度；\n- 填充密度與圖案樣式共同主導零件剛性與冷卻變形。\n綜合各項切層參數規範，選項 (D) 之論述完全正確。\n### 【選項辨析】\n- **(A) 線寬必須嚴格等於層厚**：錯誤。線寬通常約等於噴嘴徑，層厚遠小於噴嘴徑。\n- **(B) 提高速度可增強強度**：錯誤。高速出料易引發欠擠出降低強度。\n- **(C) 關閉熱床可防止變形**：錯誤。無熱床易劇烈翹曲。\n- **(D) 綜合參數設定需平衡幾何精度、層間結合強度與冷卻應力變形**：正確。",
