    "explanation": "### 【核心考點】同時主導牽絲 (Stringing) 與破頂 (Pillowing) 之關鍵加工參數\n### 【正確答案說明】\n在 FFF 加工不良現象中：\n1. **牽絲（Stringing）**：空移時熔體自噴嘴流涎，與「擠製溫度過高（熔融黏度太低流動太快）」及回抽不足直接相關；\n2. **破頂 / 頂面枕狀孔洞（Pillowing）**：在封頂實心層沉積時，底下的內部網格封閉孔隙內的熱空氣膨脹頂破頂面熔絲，或頂面熔絲因高溫軟化下陷產生破洞，與「擠製溫度過高、頂層厚度不足及風扇冷卻不足」直接相關。\n因此，「**擠製溫度（Printing Temperature）**」是同時直接影響牽絲嚴重度與頂層枕狀破洞缺陷的共同關鍵核心參數。故選 (C)。\n### 【選項辨析】\n- **(A) 平台調平高度**：僅影響第一層底盤，與頂層破頂及空中牽絲無直接關聯。\n- **(B) 裙邊圈數**：僅為底層輔助線。\n- **(C) 擠製溫度 (Printing Temperature)**：正確。溫度過高同時誘發噴嘴流涎牽絲與頂層熔融下陷破頂。\n- **(D) 底層曝光時間**：為光固化參數，與 FFF 無關。",
