    "explanation": "### 【核心考點】固定層厚切層幾何輪廓與成品階梯誤差\n### 【正確答案說明】\n目前一般 3D 列印系統大多採用固定層厚（Fixed Layer Thickness）分層建構，三維連續傾斜曲面在數學上被分割為一系列具有直角台階的離散二維薄層堆疊：\n實際加工成品的幾何外輪廓與 CAD 原始光滑輪廓之間，在斜面上必然呈現鋸齒狀的幾何凸出與凹陷，這種積層製造固有的輪廓逼近誤差即為「**階梯效應（Staircase Effect）**」。故選 (D)。\n### 【選項辨析】\n- **(A) 熱膨脹誤差**：為材料冷縮熱脹尺寸偏差。\n- **(B) 彈性變形**：外力加載引發之形變。\n- **(C) 潛變下垂**：高溫長期自重變形。\n- **(D) 階梯效應 (Staircase Effect)**：正確。固定層厚離散逼近傾斜幾何之固有微觀鋸齒台階誤差。",
