    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】多噴頭 FFF 多材料列印常見缺陷成因分析\n### 【正確答案說明】\n使用多擠製頭（雙噴頭 Dual Extruder）列印雙色或雙材料工件時，造成加工不良與成型失敗的典型原因包含：\n- 待機噴頭在停止出料時，內部殘熱導致熔體流涎滴落在當前模型表面造成顏色污染（Oozing）；\n- 雙噴頭機械物理相對空間座標（X/Y/Z Tool Offset）校準存在微米級偏差，導致兩種材料交界處錯位錯層或未熔合開裂；\n- 兩種不同聚合物材料之間的化學相容性差，介面熔接結合強度微弱而在受力時分層剝離。\n故上述各項皆為多噴頭列印常見之不良成因，選 (D) 以上皆是。\n### 【選項辨析】\n- **(A) 待機噴頭非工作時產生熔體滴漏流涎污染**：常見不良成因。需加裝刮料板或排料塔。\n- **(B) 雙噴嘴間之幾何偏置座標 (Tool Offset) 校準不精確**：常見不良成因。引發材料搭接對位偏差。\n- **(C) 異質材料間相容性差導致層間介面黏結力不足**：常見不良成因。化學結構差異引發層間開裂。\n- **(D) 以上皆是**：正確。涵蓋多噴頭列印核心缺陷根源。",
    "id": 172,
    "display_num": 9,
    "source_id": "3d-e65e8a5c7d8fc30d",
