    "assessmentTopic": "S22",
    "assessmentContent": "S2201",
    "num": 10,
    "stem": "在遠端送料 (Bowden Type) 的熔融擠出列印軟料時，較常發生失敗的狀況，其 原因何者有誤？",
    "question": "在遠端送料 (Bowden Type) 的熔融擠出列印軟料時，較常發生失敗的狀況，其 原因何者有誤？",
    "options": [
      "送料端與擠出頭路徑較長 ， 造成材料擠壓變型 ， 與送料管磨擦 ，阻力加大；",
      "線材存放受壓容易變形，使外徑改變，導致卡在進料端入口；",
      "支撐之懸 空角(angle threshold) 設定太小，物件變形而坍塌；",
      "軟料熔點較低，常在喉 管端提早軟化，造成出料不順"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】FFF 頂面封頂不良 (Top Surface Pillowing / Gaps) 成因排除\n### 【正確答案說明】\nFFF 零件頂部最後幾層實心層若出現表面未填滿、微小孔洞或枕狀下陷，常見原因為：\n- 封頂層數（Top Solid Layers）設定太少（例如僅 1-2 層），不足以完全跨越並覆蓋內部稀疏網格的空隙；\n- 內部填充率過於稀疏，網格間距跨度過大；\n- 模型散熱冷卻風扇風量不足，熔絲在跨越網格孔洞時下垂軟塌。\n故頂層層數不足、冷卻不良或填充過稀均為成因，選 (D) 以上皆是。\n### 【選項辨析】\n- **(A) 封頂實心層數設定不足**：主因。熔絲無法完全封閉內部空洞。\n- **(B) 內部填充過於稀疏導致跨距過大**：主因。懸空跨距超過熔絲搭接極限。\n- **(C) 冷卻風扇風量不足使得懸空熔絲下陷**：主因。高溫熔體失去支撐下垂。\n- **(D) 以上皆是**：正確。綜合因素共同引發頂部封頂不良。",
