    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】DLP 光固化設備光學防護與作業安全規範\n### 【正確答案說明】\n在 DLP 投影式光聚合固化成型技術設備操作環境中：\n- DLP 光機通常採用高亮度藍紫光或近紫外光（385-405 nm）作為激發光源，操作人員佩戴的防護眼鏡必須具備吸收並阻隔該特定有害波長之「專用光學防護濾光鏡片（抗 UV / 防藍光護目鏡）」；\n- 盛裝光敏樹脂之場所必須維持良好機械通風排氣，作業人員必須配戴丁腈防護手套阻絕單體接觸。\n故選項 (D) 敘述正確。\n### 【選項辨析】\n- **(A) PLA 無毒因此可在完全密閉無通風空調房長時間作業**：錯誤。任何高溫熔融皆會釋放微米顆粒，仍應維持適當通風。\n- **(B) ABS 加工中門窗必須嚴格密封且不得通風換氣**：錯誤。ABS 列印會釋放大量苯乙烯等刺激有害氣體，必須具備抽風排氣系統。\n- **(C) 設備有遮光罩即可在無通風之密閉房長時間停留**：錯誤。開罩取件與清洗時單體揮發極快，環境必須通風良好。\n- **(D) 操作人員應配戴專用光學護目鏡以防護光源對眼睛之傷害，環境應維持通風**：正確。工業安全標準規範。",
