    "explanation": "### 【核心考點】熱塑性高分子化學溶解度與 ABS 丙酮平滑處理\n### 【正確答案說明】\n丙烯腈-丁二烯-苯乙烯共聚物（ABS）的高分子聚合物結構容易被低沸點極性有機酮類溶劑快速溶解：\n- 工業界常利用「**丙酮（Acetone, $CH_3COCH_3$）**」蒸氣對 ABS 列印成品進行化學燻蒸表面平滑處理（Acetone Vapor Smoothing）；\n- 丙酮蒸氣在 ABS 模型表面微觀冷凝，迅速溶解最外層微薄的塑料表層，利用液體表面張力將粗糙的階梯層紋自然撫平填平，乾燥揮發後呈現鏡面般極致光澤與高平滑度。故選 (C)。\n### 【選項辨析】\n- **(A) 甲酸**：常用於溶解聚醯胺尼龍（PA），不適用於 ABS。\n- **(B) 乙醚**：極度易燃易爆且具麻醉危險，非工業表面平滑標準溶劑。\n- **(C) 丙酮**：正確。ABS 專用化學蒸氣平滑溶劑。\n- **(D) 丁醇**：揮發慢且對 ABS 溶解度有限。",
