    "explanation": "### 【核心考點】增加內部填充密度 (Infill Density) 之影響辨析\n### 【正確答案說明】\n使用熔融擠製成型機台，若將模型內部填充率（Infill Density）由 20% 大幅調高至 80%：\n- 模型內部塑料骨架顯著密實，工件整體抗壓剛性與機械強度大幅變強；\n- 由於內部堆積了巨量的高溫熔體，冷卻過程中體積熱收縮拉力成倍增加，模型邊緣「較容易產生翹曲變形」；\n- 噴頭需走訪繪製更多內部網格軌跡，成型時間顯著延長；\n- 消耗的線材重量大幅攀升，必然是「**更加消耗材料（成倍浪費材料）**」，絕不可能「比較節省材料」。故 (D) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 模型強度變強**：正確影響。實心受力面積增加。\n- **(B) 模型較易翹曲**：正確影響。內部熱收縮累積拉力增大。\n- **(C) 成型時間較久**：正確影響。內部路徑大幅增加。\n- **(D) 比較節省材料**：錯誤（本題正解）。填充率越高消耗材料越多，絕不可能節省材料。",
