    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】光聚合固化曝光時間 (Exposure Time) 過固化 (Over-Curing) 控制\n### 【正確答案說明】\n在光聚合固化（VP）成型中，曝光時間決定了光起始劑吸收的總能量密度：\n- 若曝光時間過長，紫外光不僅穿透設定層厚，更會透過光散射深入已固化層內部並橫向擴散，造成嚴重的「過深硬化（Over-curing）」與邊緣光暈毛邊（Flash），使微小孔洞被硬化填死、細節特徵消失膨脹；\n- 因此，「**為了避免過深硬化與尺寸膨脹，必須『降低』單層曝光時間**」，而非增加曝光時間。若稱「為了避免過深硬化須增加曝光時間」，顯屬完全顛倒之錯誤。故 (B) 選項敘述有誤。\n### 【選項辨析】\n- **(A) 增加平台附著力須增加底層曝光時間**：正確。強化底層交聯錨定於底板。\n- **(B) 為了避免過深硬化須增加曝光時間**：錯誤（本題正解）。防止過固化必須縮短（降低）曝光時間。\n- **(C) 減少毛邊 (Flash) 須降低曝光時間**：正確。抑制橫向光散射過固化。\n- **(D) 避免細微特徵消失閉合須降低曝光時間**：正確。防微孔被過固化樹脂填滿。",
