    "explanation": "### 【核心考點】3D 模型幾何精細度提升之關鍵切層參數\n### 【正確答案說明】\n在切層設定中，決定零件垂直軸向（Z 軸）幾何逼真度與精細度的最核心參數為「**切層厚度（Layer Thickness / Layer Height）**」：\n- 將層厚從 0.2 mm 縮小為 0.1 mm 或 0.05 mm，微觀階梯台階高度急劇縮小，斜面與曲面逼近理論 CAD 外形的幾何誤差最小化，表面最為細緻光滑；\n- 提高速度只會降低出料平穩性；增加網格密度為 CAD 轉換階段；支撐僅為懸空輔助。故選 (A)。\n### 【選項辨析】\n- **(A) 減少層厚 (Layer Height)**：正確。直接微細化階梯效應，極致提升表面幾何精細度。\n- **(B) 增加支撐**：僅承托懸空，無法改善本體光滑精細度。\n- **(C) 減少模型網格式**：減少 CAD 網格會降低精度產生多面體稜角。\n- **(D) 提高列印速度**：加速會增加機械振動，劣化精細度。",
