    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】FFF 切層加工參數對工件強度之負向影響因素\n### 【正確答案說明】\n在 FFF 熔融擠製成型中，要增強模型強度，通常採用：降低列印速度（出料飽滿）、提高填充率（骨架粗壯）、增加壁厚（外殼堅固）。\n而如果「**提高切層厚度（Layer Thickness，例如使用 0.4mm 噴嘴列印 0.35mm 大層厚）**」：\n- 單層熔絲截面過於粗大，噴嘴平唇面無法施加充足的垂直熨燙剪切力將熔絲充分壓扁，熔絲間的接觸截面積變窄；\n- 粗大熔絲內部降溫較慢而表面急冷，層與層之間的有效熱擴散融接面積顯著降低，導致垂直抗拉強度與抗層間剝離能力急劇下降；\n因此，「提高切層厚度」無法增加模型強度，反而通常會削弱層間結合強度。故 (A) 選項無法增加強度。\n### 【選項辨析】\n- **(A) 提高切層厚度**：無法增加強度（本題正解）。過大層厚削弱層間熱熔擠壓接觸面積，降低結合強度。\n- **(B) 降低列印速度**：能增加強度。延長高溫熔接接觸時間。\n- **(C) 提高填充率**：能增加強度。增大實體受力橫截面。\n- **(D) 增加壁厚**：能增加強度。強化外壁承載抗彎能力。",
    "id": 179,
    "display_num": 16,
    "source_id": "3d-e65e8a5c7d8fc30d",
