    "explanation": "### 【核心考點】圓柱體列印棧板 (Raft) 結構拓撲特徵判讀\n### 【正確答案說明】\n棧板（Raft）是預先在成型平台上列印的厚實墊板結構：\n- 標準 Raft 包含底層粗大稀疏的基礎底層（Base Layer）、中間交錯過渡層（Interface Layer）以及頂面平整緊密的表面層（Surface Layer），整體外邊界均勻向外擴展並完整包裹承托上方模型；\n- 如題圖所示之四種棧板幾何中，圖 (B) 精確展現了在圓柱體底面下方均勻向外延展、具備多層網狀交錯過渡結構之標準 Raft 特徵。故選 (B)。\n### 【選項辨析】\n- **(A) 圖 A**：邊界未完整向外擴展或缺乏基座分層。\n- **(B) 圖 B**：正確。呈現標準多層交錯且外擴之 Raft 棧板幾何特徵。\n- **(C) 圖 C**：為側裙（Brim）單層形態，非 Raft。\n- **(D) 圖 D**：邊界收縮無法提供抗傾覆承托。",
