    "stem": "在熔融擠製成型技術中，為了減少 3D 列印件有牽絲缺陷，下列調整的方式較 不合適？     第二章 3D 列印製程參數(ME 及 VP 技術)  2-23",
    "question": "在熔融擠製成型技術中，為了減少 3D 列印件有牽絲缺陷，下列調整的方式較 不合適？     第二章 3D 列印製程參數(ME 及 VP 技術)  2-23",
