    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】FFF 減少牽絲 (Stringing) 缺陷之不合適參數調整排除\n### 【正確答案說明】\n牽絲是由於空移時噴嘴內部熔體受重力與殘壓流涎所致。合適的改善對策為：降低列印溫度（提升熔體黏度）、增加回抽距離與回抽速度、提高空移速度。\n而如果「**提高噴頭列印溫度（或大幅降低回抽距離）**」，塑料熔融黏度急劇下降、流動性如水般劇增，噴嘴在移動時熔體會猛烈流涎拉絲，牽絲必然嚴重失控。因此提高溫度（或減少回抽）是完全相反、極不合適的調整方式。故選 (A)。\n### 【選項辨析】\n- **(A) 提高列印溫度以促進流動**：極不合適（本題正解）。黏度驟降加劇滲漏，使牽絲嚴重惡化。\n- **(B) 開啟回抽 (Retraction)**：合適。在噴嘴內部形成負壓吸回熔體。\n- **(C) 提高空行程移動速度**：合適。縮短空中流涎時間。\n- **(D) 增加回抽距離**：合適。徹底釋放熱端腔體壓力。",
