    "explanation": "### 【核心考點】高溫加熱熱床取件之冷卻規範與機械防護\n### 【正確答案說明】\n在 FFF 列印結束時，加熱熱床與模型底層溫度通常仍高達 60°C~100°C 以上：\n- 此時塑料高分子仍處於玻璃轉移溫度附近的熱軟化狀態，底膠亦處於高黏度附著狀態；\n- 正確取件規範必須「等待熱床完全自然冷卻至室溫（30°C以下）」，利用金屬彈簧鋼板與高分子冷縮係數差異引發的自動脫膠剝離輕鬆取件；\n- 若未經冷卻強行使用金屬鏟刀大力撬鏟，極易造成模型底部拉伸翹曲報廢，且鏟刀打滑極易嚴重割傷手指。故選 (B)。\n### 【選項辨析】\n- **(A) 趁高溫熱床未降溫前用力扳下**：錯誤。易燙傷且底層軟化變形損壞。\n- **(B) 待熱床充分自然冷卻後，輕微彎曲彈性鋼板或輕推取下**：正確操作規範。利用熱收縮溫差自然脫落。\n- **(C) 使用金屬鐵鎚敲擊模型頂部**：錯誤。敲擊直接破壞模型內部結構。\n- **(D) 立即以冷水直接潑灑高溫玻璃熱床**：錯誤。熱震極易使高溫鋼化玻璃瞬間爆裂。",
