    "explanation": "### 【核心考點】有機溶劑超音波清洗槽防爆與安全操作\n### 【正確答案說明】\n使用超音波清洗機搭配異丙醇（IPA）清洗光固化模型時：\n- 異丙醇屬於高度易燃液體（閃點僅約 12°C），超音波換能器長時間高頻振動會使溶劑溫度急劇上升並產生大量易燃易爆之有機蒸氣；\n- 正確規範：清洗槽必須加蓋密封防止溶劑揮發，超音波單次運轉時間不宜過長（通常 3-5 分鐘即可），且清洗機周圍嚴禁任何明火、電氣火花或高溫熱源；\n- 若以溶劑直接浸泡加熱，極易引發溶劑爆燃火災。故 (A) 選項敘述正確。\n### 【選項辨析】\n- **(A) 清洗槽應加蓋防止揮發，嚴禁煙火並避免超音波長時間運轉過熱**：正確安全規範。防範易燃有機溶劑蒸氣爆炸火災。\n- **(B) 可使用電熱棒直接插入異丙醇液體中加熱至沸騰**：極度危險。會引發猛烈化學火災與爆炸。\n- **(C) 清洗廢液可直接倒入一般下水道排放**：違法且錯誤。嚴重污染水體生態。\n- **(D) 清洗時不需配戴手套**：錯誤。IPA 經皮脫脂滲透，必須配戴丁腈手套。",
