    "explanation": "### 【核心考點】光敏樹脂化學廢棄物環境友善處置規範\n### 【正確答案說明】\n未完全固化的液態光敏樹脂含有游離丙烯酸酯單體與光起始劑，對水生生物與環境生態具有長期毒性危害（具 GHS 環境危害標誌）：\n- 正確處置流程：殘留的廢棄樹脂液或清洗後的異丙醇廢液，**絕對不可直接傾倒於洗手槽下水道或土壤中**；\n- 應將廢液置於透明容器中放置於陽光下或紫外燈下進行「**徹底光固化**」，待液體中的感光單體完全交聯固化為惰性固態塑料硬塊後，再依危險事業化學廢棄物法規交由合規環保廠商回收處理。故選 (D)。\n### 【選項辨析】\n- **(A) 直接沖入衛生間馬桶稀釋**：違法且嚴重破壞下水道水體環境。\n- **(B) 倒入室外花園泥土自然吸收**：破壞土壤生態造成地下水化學污染。\n- **(C) 摻入生活垃圾直接掩埋**：液態有毒單體滲濾液會污染環境。\n- **(D) 充分曝曬紫外線徹底硬化為固態惰性物後，依事業化學廢棄物法規分類回收**：正確環保標準流程。",
