    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】光敏樹脂配方組成：必備三大核心組分 vs 功能添加劑\n### 【正確答案說明】\n在光聚合固化成型技術（VP）中，光敏樹脂能夠完成光引發鏈式聚合並固化為固體的「三大必要核心成分」為：\n1. **單體（Monomer）**：作為活性稀釋劑，調節黏度並參與交聯；\n2. **寡聚物 / 預聚物（Oligomer）**：構成高分子主鏈骨架，主導硬化後的機械強度；\n3. **光起始劑（Photoinitiator）**：吸收紫外光躍遷產生自由基或陽離子，引發聚合。\n而「**螢光劑（Fluorescent Agent）**」僅為特殊視覺表現添加劑，並非光固化成型之必要成分。且螢光劑受光激發發出的短波冷光可能引起非預期局部微固化，反而劣化成品細緻度。故選 (D)。\n### 【選項辨析】\n- **(A) 單體**：必備核心成分。活性稀釋與交聯。\n- **(B) 寡聚物**：必備核心成分。決定樹脂本體力學性能。\n- **(C) 光起始劑**：必備核心成分。觸發光化學反應。\n- **(D) 螢光劑**：非必要成分（本題正解）。僅為特殊外觀添加劑。",
    "id": 186,
    "display_num": 1,
    "source_id": "3d-edbadd31e5bbf2d0",
