    "num": 2,
    "stem": "光固化聚合物固化過程 (不考慮溫度因素 )體積會有甚麼變化？",
    "question": "光固化聚合物固化過程 (不考慮溫度因素 )體積會有甚麼變化？",
    "options": [
      "膨脹 ；",
      "收縮 ；",
      "都不會改變 ；",
      "有時收縮、有時膨脹"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】光聚合固化反應之微觀分子間距變化與體積收縮\n### 【正確答案說明】\n液態光敏樹脂在固化前，單體與寡聚物分子之間是以分子間距較大的弱「凡得瓦力（Van der Waals force）」維繫（分子間隔約 0.3~0.4 nm）；\n當紫外光照射引發加成聚合反應時，不飽和雙鍵轉化為緊密連接的共價單鍵（C-C 共價鍵長僅約 0.15 nm），分子間距急劇拉近，自由體積顯著減少。因此在宏觀物理性質上，光固化反應必然伴隨顯著的「**體積收縮（Volumetric Shrinkage）**」，並放出聚合反應熱。故選 (B)。\n### 【選項辨析】\n- **(A) 膨脹**：錯誤。化學成鍵使分子間距縮小，絕非膨脹。\n- **(B) 收縮**：正確。由凡得瓦力轉變為共價鍵必然導致體積收縮。\n- **(C) 都不會改變**：錯誤。所有自由基光聚合皆存在收縮率。\n- **(D) 有時收縮、有時膨脹**：錯誤。不考慮熱膨脹下固化純反應均為收縮。",
    "id": 187,
