    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】聚乳酸 (PLA) 材料熱物理特性與耐熱極限\n### 【正確答案說明】\n聚乳酸（Polylactic Acid, PLA）是由乳酸經脫水縮合或丙交酯開環聚合製成的生物降解高分子：\n- PLA 具有環保、無毒、剛性高與好列印的優點；\n- 但其最大的物性弱點在於**玻璃轉移溫度（$）極低（僅約 55°C~65°C）**；\n- 當環境溫度超過 60°C（如盛裝熱咖啡、微波加熱或夏季烈日曝曬車內）時，PLA 會迅速軟化變形、失去剛度甚至坍塌洩漏，因此「**絕對不可用於高溫容器**」。故選項 (D) 描述有誤。\n### 【選項辨析】\n- **(A) 中文名稱為聚乳酸**：正確名稱。\n- **(B) 英文名稱為 Polylactic Acid**：正確英文全稱。\n- **(C) 由乳酸和丙交酯合成**：正確化學合成途徑。\n- **(D) 可用於高溫容器**：描述錯誤（本題正解）。耐熱溫度過低，遇熱水或高溫立即軟化變形。",
