    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】光聚合固化激發光源波長與光子能量之量子化關係\n### 【正確答案說明】\n光聚合固化依賴光子能量打破化學鍵生成自由基，光子能量公式為  = hc / \\lambda$（波長越短，光子能量越高）：\n- 常見光起始劑激發波長涵蓋紫外線與可見光近紫藍光：如 TPO 適用 355-385 nm、Irgacure 819 適用 405 nm、樟腦醌（CQ）適用 470 nm；\n- 而 **1064 nm 屬於近紅外光（Near-Infrared, NIR）**，其光子能量極低，根本無法激發常規光固化起始劑產生自由基，且紅外光主要表現為熱效應（多用於雷射金屬/高分子粉末燒結 SLM/SLS），最不適合做為光聚合固化光源。故選 (D)。\n### 【選項辨析】\n- **(A) 355 nm**：紫外光雷射（UV Laser），常用於工業級 SLA 機台。\n- **(B) 405 nm**：近紫外/紫光波長，桌面級 LCD/DLP 最主流波長。\n- **(C) 470 nm**：藍光可見光波長，適用於牙科 CQ 起始劑系統。\n- **(D) 1064 nm**：紅外光波長（本題正解）。光子能量不足，無法激發光化學反應。",
