    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】光敏樹脂流變特性、光反應動力學與反應熱辨析\n### 【正確答案說明】\n關於光固化樹脂的化學與物理特性：\n- **光起始劑濃度與固化速度**：在未達光學飽和吸收前，樹脂中光起始劑濃度越高，在相同光強照射下產生的活性自由基碎片數量越多，鏈引發與鏈增長聚合速率越快，樹脂由液體固化為固體的速度越快。故選項 (B) 正確；\n- 光聚合反應中碳碳雙鍵打開轉化為單鍵是典型釋放化學鍵能的「放熱反應」，並非吸熱反應；\n- 寡聚物分子量大於單體，其含量越高黏度越高；單體分子量越小自由體積越大，聚合時體積收縮率越大。\n### 【選項辨析】\n- **(A) 單體分子量愈大，則收縮率愈小**：單體雙鍵濃度高時收縮率通常較大，低分子量單體收縮率往往更顯著。\n- **(B) 光起始劑愈多，則固化速度愈快**：敘述正確（本題正解）。單位時間生成更多活性中心促進固化。\n- **(C) 寡聚物含量愈高，則黏度愈低**：錯誤。寡聚物鏈長分子量大，含量越高體系黏度越高。\n- **(D) 光聚合過程是吸熱反應**：錯誤。加成聚合為典型劇烈放熱反應。",
