    "explanation": "### 【核心考點】熱塑性 vs 熱固性積層製造材料之回收再利用原理\n### 【正確答案說明】\n不同 3D 列印材料的回收循環利用機制：\n1. **熱塑性高分子（如 FFF 使用的 ABS/PLA）**：加熱可反覆重熔塑化，廢料可粉碎重新擠出造粒抽線再利用；\n2. **粉末床熔融（PBF）與黏合劑噴射（BJT）**：未受熱熔融或未被噴墨沾黏的剩餘粉末，經震動篩網過篩去雜後可重新裝槽重複利用；\n3. **光聚合固化（VP）成型品**：在成型過程中單體與寡聚物形成了不可逆的「三維共價交聯網狀結構」，屬於**熱固性塑料（Thermoset）**；受熱只會碳化分解燃燒，**絕對不可能加熱重新熔化還原為液態樹脂**。故 (C) 是嚴重錯誤的回收方式。\n### 【選項辨析】\n- **(A) 熔融擠出 ABS 線材為成品，可熔融抽線再使用**：正確熱塑性回收方式。\n- **(B) 黏結劑噴塗成型後，剩餘粉末可篩粉再使用**：正確粉末回收循環工藝。\n- **(C) 光聚合固化成品，可加熱熔化回液態再使用**：錯誤回收方式（本題正解）。熱固性高分子不可逆，受熱不熔化。\n- **(D) 粉末床熔融成型後，剩餘粉末可篩粉再使用**：正確粉末回收循環工藝。",
