    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】聚乳酸 (PLA) 玻璃轉移溫度對日常耐溫容器之限制\n### 【正確答案說明】\nPLA 材料的玻璃轉移溫度（$）僅約 55°C~60°C：\n- 當溫度達到 60°C 以上時，PLA 的分子鏈段開始自由運動，高分子由堅硬剛性的玻璃態轉變為橡膠軟化態，結構瞬間喪失剛性發生嚴重熱下垂與變形；\n- **微波器皿**在微波加熱食物時，局部水溫與油脂溫度常達 100°C~120°C 以上，PLA 微波器皿會迅速熔化坍塌變形並析出物質，因此絕對不適合列印微波器皿。故選 (A)。\n- 玩具模型、節慶飾品、手機殼常溫使用環境（<40°C）皆在 PLA 安全範圍內。\n### 【選項辨析】\n- **(A) 微波器皿**：不適合（本題正解）。微波高溫超過其 $，導致器皿軟化崩塌。\n- **(B) 玩具模型**：適合。常溫室內環境，剛度充足色彩豐富。\n- **(C) 節慶應景用品**：適合。一次性或短期室內展示，無耐高溫需求。\n- **(D) 手機外殼**：常規常溫防摔防刮，一般使用無虞。",
    "id": 193,
    "display_num": 8,
    "source_id": "3d-edbadd31e5bbf2d0",
