    "stem": "用材料擠製 (ME)列印機列印時， ABS 的擠製溫度範圍，以下何者最有可能？",
    "question": "用材料擠製 (ME)列印機列印時， ABS 的擠製溫度範圍，以下何者最有可能？",
    "options": [
      "150-170°C；",
      "220-240°C；",
      "280-300°C；",
      "320-340°C"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】ABS 熱塑性線材之熔融擠出列印溫度範圍\n### 【正確答案說明】\nABS（丙烯腈-丁二烯-苯乙烯共聚物）屬於無定形非結晶熱塑性高分子：\n- 其玻璃轉移溫度約為 105°C；\n- 要使高黏度聚合物充分熔化並具備優良的層間融接流動性，噴嘴加工溫度必須達到熔體流動黏度適當的加工窗口，**ABS 標準熔融擠出列印溫度範圍為 220°C 至 240°C**（高溫版本甚至可達 250°C）；\n- 150-170°C 塑料完全未熔融出料困難，280°C 以上 ABS 會劇烈熱降解碳化分解並產生有毒煙霧。故選 (B)。\n### 【選項辨析】\n- **(A) 150-170°C**：溫度過低，ABS 尚未達到熱塑流動狀態，必定堵頭。\n- **(B) 220-240°C**：正確。ABS 官方標準推薦列印溫度區間。\n- **(C) 280-300°C**：溫度過高，ABS 劇烈熱裂解碳化並散發有害氣體。\n- **(D) 320-340°C**：遠超分解溫度，為超工程塑料（如 PEEK）加工溫度。",
