    "stem": "用材料擠製(ME)列印機熔融列印 PLA 時，下列何者的列印溫度範圍是合理的？",
    "question": "用材料擠製(ME)列印機熔融列印 PLA 時，下列何者的列印溫度範圍是合理的？",
    "options": [
      "190-210°C；",
      "220-240°C；",
      "260-280°C；",
      "300-320°C"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】PLA 熱塑性線材之熔融擠出列印溫度範圍\n### 【正確答案說明】\nPLA（聚乳酸）屬於半結晶型低熔點熱塑性高分子：\n- 其結晶熔點約為 150°C~160°C；\n- 在 FFF 熔融擠製成型機台中，為了獲得良好的流動性、避免過度拉絲與保持出料均勻，**PLA 的合理列印溫度範圍為 190°C 至 210°C**（視列印速度與熱端結構可浮動於 190°C~215°C）；\n- 超過 220°C-240°C 會使 PLA 熔體黏度過低導致嚴重流涎牽絲與表面結焦。故選 (A)。\n### 【選項辨析】\n- **(A) 190-210°C**：正確。PLA 標準官方推薦列印加工溫度區間。\n- **(B) 220-240°C**：為 ABS/PETG 之標準列印溫度，對 PLA 偏高易引發嚴重拉絲。\n- **(C) 260-280°C**：為尼龍（PA）/PC 之列印溫度，PLA 會過熱熱解變性。\n- **(D) 300-320°C**：超高溫，PLA 瞬間焦化碳化堵死噴嘴。",
