    "stem": "下列何種材料的耐溫性最差 (有最低的熱變形溫度 )？",
    "question": "下列何種材料的耐溫性最差 (有最低的熱變形溫度 )？",
    "options": [
      "Nylon( 尼龍)；",
      "ABS；",
      "PLA；",
      "PEEK"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】常用工程高分子材料熱變形溫度與玻璃轉移溫度排序\n### 【正確答案說明】\n材料的耐溫性能通常由其熱變形溫度（Heat Deflection Temperature, HDT）與玻璃轉移溫度（$）決定：\n- **PEEK（聚醚醚酮）**：特種超工程塑料， \u0007pprox 143^\\circ\text{C}$，HDT 高達 160°C~250°C 以上；\n- **Nylon（聚醯胺/尼龍）**：工程塑料，耐溫性良好，HDT 約 70°C~100°C（加玻纖更可達 150°C）；\n- **ABS（工程塑料）**： \u0007pprox 105^\\circ\text{C}$，HDT 約 85°C~95°C；\n- **PLA（聚乳酸）**：**$ 僅約 55°C~60°C，HDT 僅約 50°C~55°C**，在 60°C 溫水中即軟化變形，在題列材料中耐溫性最差、熱變形溫度最低。故選 (C)。\n### 【選項辨析】\n- **(A) Nylon (尼龍)**：耐溫良好，HDT 顯著高於 PLA。\n- **(B) ABS**：熱變形溫度約 85-95°C，耐溫性優於 PLA。\n- **(C) PLA**：耐溫性最差（本題正解）。熱變形溫度僅 50-55°C，極易受熱軟化。\n- **(D) PEEK**：特種超高溫耐熱塑料，耐溫性最強。",
