    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】熱塑性彈性體 (TPE/TPU) 物理特性與進料擠出機構適配性\n### 【正確答案說明】\n熱塑性彈性體（TPE / TPU）兼具硫化橡膠的高彈性與熱塑性塑料的熔融加工性：\n- TPU 屬於熱塑性聚氨酯彈性體，廣泛應用於 FFF 與 SLS（粉末床熔融）製造軟質鞋底、減震護具與保護殼；\n- **進料機構適配性分析**：\n  - 由於彈性體線材質地極為柔軟、彈性形變大且表面摩擦阻力高；\n  - 在**遠端送料機構（Bowden Extruder）**中，進料馬達與噴嘴之間有數十公分的鐵氟龍導管，當送料輪加壓推進時，軟質線材在導管內極易受壓彎曲打摺、彈性蓄能或在管壁卡死堵塞，無法精準定量擠出；\n  - 因此彈性體「**最適合近端進料機構（Direct Drive）**」，選項 (C) 稱其「適合於遠端送料的方式進行列印」顯屬錯誤。\n### 【選項辨析】\n- **(A) TPU 也算是 TPE 的一種**：敘述正確。TPU 為熱塑性聚氨酯彈性體。\n- **(B) 可以用來列印鞋底、手機殼等彈性物品**：敘述正確。具備高耐磨與優良彈性回彈。\n- **(C) 適合於遠端送料的方式進行列印**：敘述錯誤（本題正解）。軟料在遠端長導管中極易彎折擠出受阻，必須採用近端進料。\n- **(D) 可以運用粉末床熔融製程來製作**：敘述正確。SLS 常用 TPU 粉末列印晶格緩衝件。",
