    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】積層製造常用熱塑性線材之吸濕性與防潮儲存需求\n### 【正確答案說明】\n熱塑性高分子在空氣中吸收水分的傾向由其分子化學極性決定：\n- **PVA（聚乙烯醇）**：完全水溶性高分子，極度吸水，在潮濕環境中數小時即軟化黏結廢棄；\n- **Nylon（聚醯胺）**：分子鏈含極性醯胺鍵，飽和吸水率高達 2%~9%，吸濕後列印產生爆鳴起泡嚴重劣化強度；\n- **PLA（聚乳酸）**：具有酯鍵，高溫潮濕易吸水水解，導致列印發脆氣化拉絲；\n- **ABS（丙烯腈-丁二烯-苯乙烯）**：非極性碳氫芳香烴與橡膠基團為主，其平衡吸水率極低（通常小於 0.2%~0.4%），耐候抗濕性極佳，開封後在常態環境中最不容易因微量水氣而嚴重變質，**最不需要極端嚴苛的乾燥儲存環境**。故選 (B)。\n### 【選項辨析】\n- **(A) PLA**：具一定吸水性，受潮後列印氣化孔洞增加且易脆斷。\n- **(B) ABS**：正確（最不需極端乾燥環境）。吸濕性低，耐水防潮性能優異。\n- **(C) PVA**：極度吸水水溶性材料，暴露空氣中極快受潮報廢。\n- **(D) Nylon**：吸濕性極強，列印前必須經 70-80°C 烤箱嚴格烘乾數小時。",
