    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】光聚合固化成型技術 (VP) 引發化學反應之核心功能組分\n### 【正確答案說明】\n在光聚合固化（VP）成型技術中，各化學組分在化學反應中的職責分工如下：\n1. **光起始劑（Photoinitiator）**：是**唯一能夠吸收光子能量並裂解產生高反應活性化學種（自由基或陽離子）以引發鏈式聚合反應的關鍵成分**；\n2. **高分子單體（Monomer）**：低黏度小分子，作為活性稀釋劑並參與交聯反應；\n3. **寡聚物（Oligomer）**：預聚物主鏈，決定成型件本體機械強度與耐磨性；\n4. **填充物（Filler）**：如陶瓷微粉、色料，用於改善熱膨脹或調整外觀。故選 (C)。\n### 【選項辨析】\n- **(A) 高分子單體**：反應基質材料，自身無法主動吸收光子引發聚合。\n- **(B) 寡聚物**：聚合物主幹骨架，需依賴起始劑產生的活性中心引發。\n- **(C) 光起始劑**：正確。吸收光子裂解產生自由基引發聚合之核心成分。\n- **(D) 填充物**：非反應性物性調整組分。",
    "id": 200,
    "display_num": 15,
