    "answer": "D",
    "ans_text": "標準答案：(D)",
    "explanation": "### 【核心考點】尼龍 (PA) 與 PETG 材料物理特性與摩擦學性能對比\n### 【正確答案說明】\n尼龍（Polyamide, PA）與 PETG（改性聚對苯二甲酸乙二醇酯）材料特性對比：\n- **尼龍（PA）的摩擦學特性**：尼龍是世界著名的自潤滑工程塑料，其表面光滑，**具備「極低的摩擦係數（Low Coefficient of Friction，約 0.15~0.3）」與極高的耐磨損耗壽命**，常專門用來列印齒輪、軸承、滑塊等傳動零件；\n- 若稱「尼龍材料磨擦係數較高」，顯屬顛倒黑白的錯誤論述。故 (D) 選項有誤。\n- 此外，尼龍極性強較易染色，熱膨脹較大熱床需加熱至 80°C~100°C，斷裂延伸率高抗衝擊韌性好。\n### 【選項辨析】\n- **(A) 尼龍材料較易染色**：正確特性。醯胺鍵易與酸性染料牢固結合。\n- **(B) 尼龍材料列印平台加熱溫度較高**：正確特性。尼龍翹曲力大，熱床需 80-100°C 保溫。\n- **(C) 尼龍材料延伸率 (Elongation) 較高**：正確特性。斷裂伸長率高具極佳抗衝擊韌性。\n- **(D) 尼龍材料磨擦係數較高**：錯誤敘述（本題正解）。尼龍為低摩擦係數、耐磨自潤滑材料。",
