    "stem": "下列哪項 3D 列印技術的機台所製作的成品不可回收重製回原料？",
    "question": "下列哪項 3D 列印技術的機台所製作的成品不可回收重製回原料？",
    "options": [
      "熔融擠製成型技術 (FFF) ；",
      "光聚合固化成型技術 (VP)；",
      "指向性能量沉 積成型技術 (DED) ；",
      "粉末床熔融成型技術 (PBF)"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】積層製造七大製程材料微觀熱固性 vs 熱塑性可回收性辨析\n### 【正確答案說明】\n積層製造工件能否回收重熔製回原料，取決於高分子成型時的化學成鍵本質：\n1. **FFF、DED、PBF**：\n   - FFF 使用熱塑性塑料（PLA/ABS），加熱可反覆融化再抽線；\n   - DED / PBF 多使用金屬合金粉末或熱塑性尼龍粉末，金屬重熔或粉末重熔屬於物理可逆相變，可重複回收再熔製原料；\n2. **光聚合固化成型技術（VP）**：\n   - 工件是由液態感光樹脂在紫外光照射下，分子間產生大量強共價交聯鍵，形成不可逆的三維巨型立體網狀分子；\n   - 屬於**熱固性高分子（Thermoset）**，硬化後受熱不會熔化只會燃燒碳化，**絕對無法還原重製為液體樹脂原料**。故選 (B)。\n### 【選項辨析】\n- **(A) 熔融擠製成型技術 (FFF)**：熱塑性高分子，可重熔抽線回收。\n- **(B) 光聚合固化成型技術 (VP)**：不可回收（本題正解）。熱固性共價交聯網絡，無法重熔還原。\n- **(C) 指向性能量沉積成型技術 (DED)**：金屬或高分子，金屬可重新熔煉成合金。\n- **(D) 粉末床熔融成型技術 (PBF)**：熱塑性塑膠或金屬粉末，可重熔造粒或再霧化製粉。",
    "id": 202,
