    "stem": "一般熔融擠製成型技術使用的材料，依照其玻璃轉換溫度 (即材料開始軟化的 溫度)由高而低排列為？",
    "question": "一般熔融擠製成型技術使用的材料，依照其玻璃轉換溫度 (即材料開始軟化的 溫度)由高而低排列為？",
    "options": [
      "PEEK>ABS>PLA ；",
      "PEEK>PLA>ABS ；",
      "ABS>PLA>PEEK ；",
      "PLA>ABS>PEEK"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "explanation": "### 【核心考點】常用 FFF 熱塑性材料玻璃轉移溫度 ($) 排序\n### 【正確答案說明】\n玻璃轉移溫度（Glass Transition Temperature, $）是無定形高分子由剛硬玻璃態向黏彈橡膠態轉變的臨界溫度，直接決定材料的耐溫上限：\n- **PEEK（聚醚醚酮）**：特種高耐溫超工程塑料， \u0007pprox 143^\\circ\text{C}$（熔點更達 343°C）；\n- **ABS（丙烯腈-丁二烯-苯乙烯）**：通用耐熱工程塑料， \u0007pprox 100^\\circ\text{C}\\sim 105^\\circ\text{C}$；\n- **PLA（聚乳酸）**：生物基脂肪族聚酯， \u0007pprox 55^\\circ\text{C}\\sim 60^\\circ\text{C}$；\n由高至低之正確排列順序為：**PEEK > ABS > PLA**。故選 (A)。\n### 【選項辨析】\n- **(A) PEEK > ABS > PLA**：正確排序。數值約為 143°C > 105°C > 60°C。\n- **(B) PEEK > PLA > ABS**：錯誤排序。ABS 耐熱性顯著優於 PLA。\n- **(C) ABS > PLA > PEEK**：錯誤排序。PEEK 耐溫遠高於一般通用塑料。\n- **(D) PLA > ABS > PEEK**：完全顛倒錯誤。",
    "id": 203,
