    "stem": "3D 列印材料，下列何者具有較低的生物毒性及較高的生物降解性？",
    "question": "3D 列印材料，下列何者具有較低的生物毒性及較高的生物降解性？",
    "options": [
      "PA；",
      "PVC ；",
      "PLA ；",
      "ABS"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】生物基高分子材料環保性、低生物毒性與生物降解性\n### 【正確答案說明】\n常見 3D 列印材料的生物相容性與環境降解性：\n- **PLA（聚乳酸，Polylactic Acid）**：是由玉米、甘蔗等富含澱粉的農作物發酵產生乳酸，再經聚合製成的 100% 生物基聚酯；\n- 具有無毒、低異味、低刺激性等特點，在工業堆肥環境下可被微生物完全分解為二氧化碳和水，具有優異的**生物降解性與低生物毒性**，甚至廣泛應用於醫用可吸收縫合線與骨釘。故選 (C)。\n- PVC（聚氯乙烯）燃燒釋放氯化氫具高毒性；ABS 為石油基塑料難以降解；PA（尼龍）降解週期長達數十年。\n### 【選項辨析】\n- **(A) PA (尼龍)**：石油基工程塑料，環境生物降解極慢。\n- **(B) PVC**：含鹵素添加劑，加工受熱具化學毒性。\n- **(C) PLA**：正確。源於天然農作物，無毒無味且可在工業堆肥中完全生物降解。\n- **(D) ABS**：石油基不可降解塑料，燃燒散發苯乙烯有害毒氣。",
    "id": 204,
