    "answer": "C",
    "ans_text": "標準答案：(C)",
    "explanation": "### 【核心考點】運動承載傳動耐磨零件（輪子/軸承）積層製造選材\n### 【正確答案說明】\n電腦椅的旋轉滾輪在實際使用中需長期承受：人體垂直重力載荷、在粗糙地面上的持續滾動滾動摩擦、微小砂礫的磨蝕以及頻繁的轉向衝擊：\n- **Nylon（尼龍 / 聚醯胺 PA）**：是製造耐用機械輪子的黃金首選材料。尼龍具有極高的拉伸強度、極佳的抗衝擊韌性、優越的抗疲勞強度，最關鍵的是**具備極低的摩擦係數與卓越的耐磨耗自潤滑性能**，移動順暢阻力極小且經久耐磨；\n- PLA 硬脆易摔裂破碎；PVA 為遇水溶解的支撐材，遇潮立即毀損；PCL（聚己內酯）熔點僅 60°C 極度柔軟承重即永久變形。故選 (C)。\n### 【選項辨析】\n- **(A) PCL**：超低熔點（60°C）且軟化模數低，無法承受人體載重。\n- **(B) PVA**：水溶性耗材，環境空氣受潮即溶解軟爛。\n- **(C) Nylon (尼龍)**：正確。耐磨自潤滑、耐反覆衝擊震動、機械強度極高。\n- **(D) PLA**：性脆抗衝擊差，輪子滾動受震極易崩裂。",
