    "explanation": "### 【核心考點】PLA 與 ABS 熔融擠製加工參數與熔融流變性對比\n### 【正確答案說明】\nPLA 與 ABS 熱塑性線材之加工參數與流變特性對比：\n- **熔體流動性與速度**：熔融狀態下的 PLA 黏度較低、流動性優於 ABS，且高分子冷卻定型較慢，在強行高速擠出時散熱定型快，通常可容許相對平穩甚至較快的速度列印；\n- **溫度與熱床差異**：\n  - 噴嘴溫度：PLA（190-210°C）顯著低於 ABS（220-240°C）；\n  - 腔體與熱床：ABS 熱收縮率極高，熱床必須加熱至 100-110°C 並嚴格封箱保溫；PLA 收縮率低，可低溫加熱熱床（50-60°C）甚至在美紋膠帶上免加熱列印；\n- 選項 (C) 稱「PLA 的列印速度較 ABS 的為慢」敘述有誤（流動性好的 PLA 往往能以比易拉絲翹曲的 ABS 更快或同等速度列印）。故選 (C)。\n### 【選項辨析】\n- **(A) PLA 的噴嘴溫度較 ABS 的為低**：敘述正確。PLA 約 200°C，ABS 約 230°C。\n- **(B) PLA 的腔體溫度較 ABS 的為低**：敘述正確。ABS 需高溫保溫防翹曲。\n- **(C) PLA 的列印速度較 ABS 的為慢**：敘述有誤（本題正解）。流動性好的 PLA 可容許更平穩高速的擠出成型。\n- **(D) PLA 可不必要加熱熱床，ABS 列印時需要**：敘述正確。ABS 內應力極大必須熱床高溫保溫。",
