    "answer": "B",
    "ans_text": "標準答案：(B)",
    "explanation": "### 【核心考點】光聚合固化感光樹脂配方核心三大組分辨析\n### 【正確答案說明】\n光聚合固化成型技術（VP）所使用的感光樹脂，在化學體系中主導光聚合固化反應的核心三元組成為：\n1. **單體（Monomer）**；\n2. **寡聚物 / 預聚物（Oligomer）**；\n3. **光起始劑（Photoinitiator）**。\n在標準基礎化學配方定義中，「**安定劑（Stabilizer / 穩定劑）**」或熱聚合抑制劑（如對羥基苯甲醚 MEHQ）僅為微量添加劑（防止常溫自發暗聚合），並非樹脂的主體反應構造三大成分；本題選項 (B)「安定劑」不屬於題目所列核心三要素之一。故選 (B)。\n### 【選項辨析】\n- **(A) 單體**：核心組分。稀釋與參與網絡建構。\n- **(B) 安定劑**：不含此項（本題正解）。非核心三元主體構造。\n- **(C) 寡聚物**：核心組分。高分子骨架提供機械強度。\n- **(D) 光起始劑**：核心組分。吸收光子激發反應。",
